package heirrealm

import (
	"strconv"
	"time"

	"gno.land/p/nt/ufmt/v0"
)

// Render is the gnoweb homepage for the realm. It lists every vault
// with its owner, beneficiary, balance, deadline and status, plus a
// short how-to. A single vault can be viewed at /<id>.
func Render(path string) string {
	if path != "" {
		id, err := strconv.Atoi(path)
		if err != nil {
			return "# HeirRealm\n\nUnknown vault."
		}
		v := vaults.Get(strconv.Itoa(id))
		if v == nil {
			return "# HeirRealm\n\nUnknown vault."
		}
		return renderVault(v.(*Vault))
	}
	out := "# HeirRealm — dead-man's switch for Gno\n\n"
	out += "Name a beneficiary and a check-in window. Check in before the window ends and nothing happens. "
	out += "Miss the window and any keeper can trigger the release: the beneficiary gets 98%, the keeper earns a 2% fee. "
	out += "No custodian, no will, no trusted third party.\n\n"
	out += "## Vaults\n\n"
	if nextVault == 0 {
		out += "No vaults yet. Create one with `CreateVault(beneficiary, intervalSeconds)` and attach ugnot with `-send`.\n"
		return out
	}
	for i := 1; i <= nextVault; i++ {
		v := vaults.Get(strconv.Itoa(i))
		if v == nil {
			continue
		}
		vv := v.(*Vault)
		out += ufmt.Sprintf("- Vault #%d — %s — balance %d ugnot — deadline %s\n",
			vv.ID, vv.Status(), vv.Balance, vv.Deadline.Format(time.RFC3339))
	}
	out += "\n## How it works\n\n"
	out += "1. `CreateVault(beneficiary, intervalSeconds)` + `-send` ugnot — you are the owner.\n"
	out += "2. `CheckIn(vaultID)` before the deadline to reset the timer.\n"
	out += "3. `Heartbeat(vaultID)` during the post-deadline grace period to revive the vault and reset the deadline (owner only).\n"
	out += "4. `Deposit(vaultID)` + `-send` ugnot to top up (owner only, timer unchanged).\n"
	out += "5. After deadline + grace period, anyone except the owner or beneficiary calls `TriggerRelease(vaultID)` and earns 2%.\n"
	out += "6. `Cancel(vaultID)` refunds the owner in full — owner only, before the deadline.\n"
	return out
}

func renderVault(v *Vault) string {
	out := ufmt.Sprintf("# HeirRealm — Vault #%d\n\n", v.ID)
	out += ufmt.Sprintf("- Status: %s\n", v.Status())
	out += ufmt.Sprintf("- Owner: %s\n", v.Owner)
	out += ufmt.Sprintf("- Beneficiary: %s\n", v.Beneficiary)
	out += ufmt.Sprintf("- Balance: %d ugnot\n", v.Balance)
	out += ufmt.Sprintf("- Check-in interval: %d seconds\n", v.Interval)
	out += ufmt.Sprintf("- Deadline: %s\n", v.Deadline.Format(time.RFC3339))
	out += ufmt.Sprintf("- Grace period ends: %s (%d seconds)\n", v.GraceEnd().Format(time.RFC3339), v.GracePeriod)
	out += ufmt.Sprintf("- Keeper fee at release: %d ugnot (2%%)\n", v.KeeperFee())
	out += ufmt.Sprintf("- Beneficiary share at release: %d ugnot (98%%)\n", v.BeneficiaryShare())
	if v.Released {
		out += ufmt.Sprintf("- Released by keeper: %s at %s\n", v.Keeper, v.ReleasedAt.Format(time.RFC3339))
	}
	return out
}

// Package acak provides auditable, unpredictable commit-reveal randomness for
// Gno.land realms.
//
// Gno.land has no on-chain entropy. A realm that needs an unpredictable value
// must collect one from its users with commit-reveal: participants publish
// sha256(salt || payload) while the salts are still secret, and later publish
// the salts so the seed can be derived and checked by anyone.
//
// acak makes that scheme a single import:
//
//	commitment := acak.Commit(salt, payload)
//	seed       := acak.Seed(commitments, salts, closeHeight)
//	order      := acak.Draw(acak.RNG(seed), n, k)
//
// Every function here is pure: no realm state, no Render, no I/O. The seed is a
// pure function of the revealed material and the close height, so a stored seed
// reproduces the stored draw exactly, forever, for anyone.
//
// This package provides unpredictability and auditability, not secrecy.
// Commitments hide a value only until the salt is revealed; realm state is
// public.
package acak

import (
	"bytes"
	frand "crypto/chacha20/rand"
	"crypto/merkle"
	"crypto/sha256"
	"encoding/binary"
	"math/bits"
	"sort"
)

const (
	// saltSize is the only salt length Commit accepts. A salt shorter than the
	// hash output would let an attacker brute-force a commitment, which would
	// reveal the payload before the reveal phase.
	saltSize = 32

	// seedSize is the only seed length RNG accepts. crypto/chacha20/rand keys
	// ChaCha20 with 32 bytes; any other length is a caller bug, not a value to
	// silently stretch.
	seedSize = 32

	// hashSize is the length of every hash this package produces or consumes.
	hashSize = 32
)

// seedDomain separates this package's seed derivation from every other use of
// SHA-256 on chain. Two realms that both call Seed on the same material get the
// same seed (they must, for auditability), but a seed can never collide with a
// commitment, a Merkle node, or another package's digest.
var seedDomain = []byte("acak/seed/v1")

// Commit returns sha256(salt || payload).
//
// The salt must be exactly 32 bytes of material the committer keeps secret
// until the reveal phase. It panics otherwise: a short or reused salt is the
// single easiest way to make a commitment reversible before the reveal.
func Commit(salt, payload []byte) []byte {
	if len(salt) != saltSize {
		panic("acak: salt must be exactly 32 bytes")
	}
	buf := make([]byte, 0, saltSize+len(payload))
	buf = append(buf, salt...)
	buf = append(buf, payload...)
	sum := sha256.Sum256(buf)
	return sum[:]
}

// Seed derives the 32-byte seed from the revealed commitments and salts,
// bound to closeHeight.
//
// commitments and salts are each sorted before hashing, so a caller cannot
// bias the result by ordering. The sort is over the two multisets
// independently: the seed depends on the set of commitments and the set of
// salts, not on which salt a realm happens to pair with which commitment.
// (Pairing is checked by the realm, per participant, against Commit.)
//
// closeHeight is mixed into the digest, so material harvested from one round
// cannot be replayed into another round that closes at a different height.
//
// Seed panics on an empty commitment set and on a length mismatch. Both are
// caller bugs, and an empty set would produce a seed every observer can
// predict before anyone commits.
func Seed(commitments [][]byte, salts [][]byte, closeHeight int64) []byte {
	if len(commitments) == 0 {
		panic("acak: Seed requires at least one commitment")
	}
	if len(salts) != len(commitments) {
		panic("acak: commitments and salts must have equal length")
	}

	cs := sortedCopy(commitments)
	ss := sortedCopy(salts)

	buf := make([]byte, 0, len(seedDomain)+8+4+len(cs)*(4+hashSize)+4+len(ss)*(4+hashSize))
	buf = append(buf, seedDomain...)
	buf = appendUint64(buf, uint64(closeHeight))
	buf = appendItems(buf, cs)
	buf = appendItems(buf, ss)

	sum := sha256.Sum256(buf)
	return sum[:]
}

// RNG returns a ChaCha20-backed generator seeded with seed.
//
// It panics if len(seed) != 32. The generator is deterministic: the same seed
// always produces the same stream, which is what makes a stored draw
// replayable by an auditor.
func RNG(seed []byte) *frand.RNG {
	if len(seed) != seedSize {
		panic("acak: seed must be exactly 32 bytes")
	}
	// Copy so a caller mutating their slice cannot change a generator that has
	// already been handed out.
	key := make([]byte, seedSize)
	copy(key, seed)
	return frand.NewFromSeed(key)
}

// Perm returns a uniformly random permutation of [0,n) via Fisher-Yates.
//
// The pass runs forward from position 0, so the first k positions are decided
// by the first k draws. That makes Draw(rng,n,k) exactly Perm(rng,n)[:k] for the
// same generator state, and lets an auditor replay a partial draw.
func Perm(rng *frand.RNG, n int) []int {
	if rng == nil {
		panic("acak: Perm requires a non-nil RNG")
	}
	if n < 0 {
		panic("acak: Perm requires n >= 0")
	}
	m := make([]int, n)
	for i := 0; i < n; i++ {
		m[i] = i
	}
	shufflePrefix(rng, m, n)
	return m
}

// Draw returns k distinct indices from [0,n), in draw order.
//
// It is the first k positions of Perm for the same seed: the same generator
// state yields the same values, and only k draws are consumed.
//
// It panics if n <= 0, if k < 0, or if k > n: a draw of nothing from nothing is
// a caller bug, and silently returning an empty slice would let a realm settle
// a round with no winner. k == 0 with n > 0 returns an empty slice.
func Draw(rng *frand.RNG, n, k int) []int {
	if rng == nil {
		panic("acak: Draw requires a non-nil RNG")
	}
	if n <= 0 {
		panic("acak: Draw requires n > 0")
	}
	if k < 0 || k > n {
		panic("acak: Draw requires 0 <= k <= n")
	}

	pool := make([]int, n)
	for i := 0; i < n; i++ {
		pool[i] = i
	}
	shufflePrefix(rng, pool, k)
	out := make([]int, k)
	copy(out, pool[:k])
	return out
}

// shufflePrefix performs the first `steps` iterations of a forward Fisher-Yates
// shuffle over m: for i in [0,steps), swap m[i] with a uniform choice from
// [i,len(m)). Exactly `steps` values are drawn from rng, so a prefix of the
// shuffle consumes a prefix of the stream.
func shufflePrefix(rng *frand.RNG, m []int, steps int) {
	for i := 0; i < steps; i++ {
		j := i + rng.Intn(len(m)-i)
		m[i], m[j] = m[j], m[i]
	}
}

// Tree is a Tendermint simple Merkle tree over arbitrary leaves.
//
// The constructor is NewTree rather than Tree: Go and Gno share one package
// namespace, so a package cannot declare both a type Tree and a function Tree.
// The rest of the surface is unchanged.
type Tree struct {
	leaves [][]byte
	root   []byte
}

// NewTree builds a Merkle tree over leaves using merkle.LeafHash and
// merkle.InnerHash.
//
// The tree is exactly Tendermint's simple tree: the split point is the largest
// power of two strictly less than the number of items, so Root always equals
// crypto/merkle.HashFromByteSlices for the same items in the same order.
// Leaves are copied so later mutation by the caller cannot change the tree.
func NewTree(leaves [][]byte) *Tree {
	t := &Tree{leaves: make([][]byte, len(leaves))}
	for i, leaf := range leaves {
		cp := make([]byte, len(leaf))
		copy(cp, leaf)
		t.leaves[i] = cp
	}
	if len(t.leaves) > 0 {
		t.root = rootOf(t.leaves)
	}
	return t
}

// Root returns the 32-byte root, or nil for an empty tree.
func (t *Tree) Root() []byte {
	if len(t.root) == 0 {
		return nil
	}
	cp := make([]byte, len(t.root))
	copy(cp, t.root)
	return cp
}

// Prove returns the audit path for leaf i as a flat concatenation of 32-byte
// siblings, plus the total leaf count, in the encoding
// merkle.VerifySimpleProof expects: the leaf's own sibling first, the root's
// child sibling last.
//
// It panics if the tree is empty or i is out of range.
func (t *Tree) Prove(i int) (aunts []byte, total int) {
	if len(t.leaves) == 0 {
		panic("acak: Prove on an empty tree")
	}
	if i < 0 || i >= len(t.leaves) {
		panic("acak: Prove index out of range")
	}
	path := provePath(t.leaves, i)
	out := make([]byte, 0, len(path)*hashSize)
	for _, a := range path {
		out = append(out, a...)
	}
	return out, len(t.leaves)
}

// Verify checks a proof against a root using merkle.VerifySimpleProof.
//
// It returns false rather than panicking on malformed input, so a realm can
// reject a bad proof from an untrusted caller with an error instead of aborting
// the transaction.
func Verify(root, leaf []byte, index, total int, aunts []byte) bool {
	if len(root) != hashSize {
		return false
	}
	if total <= 0 || index < 0 || index >= total {
		return false
	}
	if len(aunts)%hashSize != 0 {
		return false
	}
	return merkle.VerifySimpleProof(root, leaf, index, total, aunts)
}

// rootOf computes the Tendermint simple root of items, which must be non-empty.
func rootOf(items [][]byte) []byte {
	if len(items) == 1 {
		return merkle.LeafHash(items[0])
	}
	k := splitPoint(len(items))
	return merkle.InnerHash(rootOf(items[:k]), rootOf(items[k:]))
}

// provePath returns the sibling hashes from the leaf up to the root's child.
func provePath(items [][]byte, i int) [][]byte {
	if len(items) == 1 {
		return nil
	}
	k := splitPoint(len(items))
	if i < k {
		path := provePath(items[:k], i)
		return append(path, rootOf(items[k:]))
	}
	path := provePath(items[k:], i-k)
	return append(path, rootOf(items[:k]))
}

// splitPoint returns the largest power of two strictly less than length,
// matching tm2's merkle.getSplitPoint.
func splitPoint(length int) int {
	if length < 1 {
		panic("acak: cannot split an empty tree")
	}
	k := 1 << uint(bits.Len(uint(length))-1)
	if k == length {
		k >>= 1
	}
	return k
}

// byteSlices sorts [][]byte lexicographically.
type byteSlices [][]byte

func (b byteSlices) Len() int           { return len(b) }
func (b byteSlices) Less(i, j int) bool { return bytes.Compare(b[i], b[j]) < 0 }
func (b byteSlices) Swap(i, j int)      { b[i], b[j] = b[j], b[i] }

// sortedCopy copies items, then sorts the copy so the caller's slice is never
// reordered underneath them.
func sortedCopy(items [][]byte) [][]byte {
	out := make([][]byte, len(items))
	for i, item := range items {
		cp := make([]byte, len(item))
		copy(cp, item)
		out[i] = cp
	}
	sort.Sort(byteSlices(out))
	return out
}

// appendUint64 appends v as 8 big-endian bytes.
func appendUint64(dst []byte, v uint64) []byte {
	var tmp [8]byte
	binary.BigEndian.PutUint64(tmp[:], v)
	return append(dst, tmp[:]...)
}

// appendItems appends a 4-byte big-endian count followed by each item as a
// 4-byte big-endian length and its bytes. Length prefixes make the encoding
// unambiguous, so no two distinct item lists can produce the same byte string.
func appendItems(dst []byte, items [][]byte) []byte {
	dst = appendUint32(dst, uint32(len(items)))
	for _, item := range items {
		dst = appendUint32(dst, uint32(len(item)))
		dst = append(dst, item...)
	}
	return dst
}

// appendUint32 appends v as 4 big-endian bytes.
func appendUint32(dst []byte, v uint32) []byte {
	var tmp [4]byte
	binary.BigEndian.PutUint32(tmp[:], v)
	return append(dst, tmp[:]...)
}

package tavernboard

// Tavern Board - On-chain forum with GNOT tips (Gno v1.8 API).
// Posts, replies, and tips are all chain state.
// Front page ranks posts by total tips received.
//
// API notes (Gno v1.8, cf. examples/gno.land/r/demo/disperse,
// examples/gno.land/r/gnoland/boards2):
// - `address` and `realm` are built-in types (no std import).
// - State-changing functions take `cur realm` first and read the caller
//   via cur.Previous().Address().
// - Tips arrive as a send envelope: the caller attaches ugnot with the
//   call (gnokey maketx call -send), the realm reads it via
//   unsafe.OriginSend() and forwards it with an OriginSend banker.
//   The IsUserCall guard is REQUIRED with OriginSend (see
//   docs/resources/gno-security-guide.md): a maketx-run ephemeral realm
//   could otherwise consume the envelope.
// - Render(path string) is the gnoweb entry point. The path is the URL
//   args after the colon: "" = front page, "post/<id>" = post detail.
//   User content is markdown-escaped so it cannot break the layout.

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
	"errors"
	"strconv"
	"strings"
	"time"
)

// Realm path (gnoweb absolute link base).
const gRealmPath = "/r/g15kxyhlw2zgz2l2sg8526j0nw5j77mkumyuztwj/tavernboard"

// Post represents a board post.
type Post struct {
	ID         int
	Title      string
	Body       string
	Author     address
	Created    int64
	TipTotal   int64 // total ugnot tipped
	ReplyCount int
}

// Reply represents a reply to a post.
type Reply struct {
	ID       int
	PostID   int
	Body     string
	Author   address
	Created  int64
	TipTotal int64 // total ugnot tipped
}

// State.
var (
	posts       = make(map[int]Post)
	replies     = make(map[int][]Reply) // postID -> replies
	nextPostID  = 1
	nextReplyID = 1
	authorTips  = make(map[address]int64) // address -> total tips received
	postOrder   = []int{}                 // post IDs sorted by tip total (desc)
)

// initPostOrder rebuilds the post order leaderboard.
func initPostOrder() {
	postOrder = make([]int, 0, len(posts))
	for id := range posts {
		postOrder = append(postOrder, id)
	}
	// Simple bubble sort by TipTotal desc (deterministic, no external deps).
	for i := 0; i < len(postOrder); i++ {
		for j := i + 1; j < len(postOrder); j++ {
			if posts[postOrder[i]].TipTotal < posts[postOrder[j]].TipTotal {
				postOrder[i], postOrder[j] = postOrder[j], postOrder[i]
			}
		}
	}
}

// CreatePost creates a new post on the default board.
func CreatePost(cur realm, title, body string) (int, error) {
	if title == "" {
		return 0, errors.New("title cannot be empty")
	}
	if body == "" {
		return 0, errors.New("body cannot be empty")
	}

	caller := cur.Previous().Address()
	id := nextPostID
	nextPostID++

	posts[id] = Post{
		ID:         id,
		Title:      title,
		Body:       body,
		Author:     caller,
		Created:    time.Now().Unix(),
		TipTotal:   0,
		ReplyCount: 0,
	}
	replies[id] = make([]Reply, 0)

	initPostOrder()
	return id, nil
}

// CreateReply adds a reply to a post.
func CreateReply(cur realm, postID int, body string) (int, error) {
	if body == "" {
		return 0, errors.New("reply body cannot be empty")
	}

	post, exists := posts[postID]
	if !exists {
		return 0, errors.New("post not found")
	}

	caller := cur.Previous().Address()
	id := nextReplyID
	nextReplyID++

	replies[postID] = append(replies[postID], Reply{
		ID:       id,
		PostID:   postID,
		Body:     body,
		Author:   caller,
		Created:  time.Now().Unix(),
		TipTotal: 0,
	})

	// Update post reply count.
	post.ReplyCount++
	posts[postID] = post

	return id, nil
}

// tip moves `amount` ugnot from the call's send envelope to `to`,
// refunding any leftover to the caller. The caller must be a user call
// and must have attached at least `amount` ugnot to the call.
//
// Money follows the disperse pattern (examples/gno.land/r/demo/disperse):
// a RealmSend banker moves coins out of the realm's own balance, and the
// IsUserCall guard is the security control — for a pure EOA call the send
// envelope really lands at the realm, so the realm balance covers the tip
// plus the refund; a maketx-run ephemeral realm or intermediate code realm
// could otherwise spend pre-existing realm balance to attacker-chosen
// addresses. The balance check below is a second layer: the tip only
// proceeds if the realm actually holds the sent coins.
// (An OriginSend banker would be safer by construction, but it can only
// spend an envelope credited to this realm in the same message, which a
// filetest cross-call cannot provide — the envelope belongs to the
// filetest package — so it is not testable; RealmSend + guard is the
// sanctioned, testable pattern.)
func tip(cur realm, to address, amount int64) error {
	if !cur.Previous().IsUserCall() {
		return errors.New("only user-call (maketx call) accepted")
	}
	if amount <= 0 {
		return errors.New("tip amount must be positive")
	}

	sent := unsafe.OriginSend().AmountOf("ugnot")
	if sent < amount {
		return errors.New("sent amount less than tip amount")
	}

	caller := cur.Previous().Address()
	realmAddr := cur.Address()
	b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	if b.GetCoin(realmAddr, "ugnot") < sent {
		return errors.New("realm balance less than sent amount")
	}
	b.SendCoins(realmAddr, to, chain.NewCoins(chain.NewCoin("ugnot", amount)))
	if leftover := sent - amount; leftover > 0 {
		b.SendCoins(realmAddr, caller, chain.NewCoins(chain.NewCoin("ugnot", leftover)))
	}
	return nil
}

// TipPost sends GNOT tips to a post author. Attach the tip with the call:
// gnokey maketx call -send <amount>ugnot -func TipPost -args <postID> -args <amount> ...
func TipPost(cur realm, postID int, amount int64) error {
	post, exists := posts[postID]
	if !exists {
		return errors.New("post not found")
	}
	if err := tip(cur, post.Author, amount); err != nil {
		return err
	}

	post.TipTotal += amount
	posts[postID] = post
	authorTips[post.Author] += amount
	initPostOrder()
	return nil
}

// TipReply sends GNOT tips to a reply author. Attach the tip with the call.
func TipReply(cur realm, postID int, replyID int, amount int64) error {
	postReplies, exists := replies[postID]
	if !exists {
		return errors.New("post not found")
	}

	var replyIndex = -1
	for i, r := range postReplies {
		if r.ID == replyID {
			replyIndex = i
			break
		}
	}
	if replyIndex == -1 {
		return errors.New("reply not found")
	}

	reply := postReplies[replyIndex]
	if err := tip(cur, reply.Author, amount); err != nil {
		return err
	}

	reply.TipTotal += amount
	postReplies[replyIndex] = reply
	replies[postID] = postReplies
	authorTips[reply.Author] += amount
	return nil
}

// GetPost returns a post by ID.
func GetPost(postID int) (Post, bool) {
	post, exists := posts[postID]
	return post, exists
}

// GetReplies returns all replies for a post.
func GetReplies(postID int) []Reply {
	return replies[postID]
}

// GetPosts returns all posts sorted by tip total (leaderboard).
func GetPosts() []Post {
	result := make([]Post, 0, len(postOrder))
	for _, id := range postOrder {
		result = append(result, posts[id])
	}
	return result
}

// GetAuthorTips returns total tips received by an author.
func GetAuthorTips(author address) int64 {
	return authorTips[author]
}

// escapeMD escapes markdown metacharacters so user content cannot break
// the page layout or inject links/images.
func escapeMD(s string) string {
	var b strings.Builder
	for _, r := range s {
		switch r {
		case '\\', '`', '*', '_', '[', ']', '#', '>', '|':
			b.WriteString("\\")
			b.WriteRune(r)
		default:
			b.WriteRune(r)
		}
	}
	return b.String()
}

// Render renders the board (gnoweb entry point).
// path "" = front page, "post/<id>" = post detail page.
func Render(path string) string {
	if path == "" {
		return renderBoard()
	}
	if strings.HasPrefix(path, "post/") {
		idStr := strings.TrimPrefix(path, "post/")
		id, err := strconv.Atoi(idStr)
		if err != nil || id <= 0 {
			return renderError("Invalid post ID")
		}
		return renderPostPage(id)
	}
	return renderError("Page not found")
}

func renderBoard() string {
	var b strings.Builder
	b.WriteString("# Tavern Board\n\n")
	b.WriteString("On-chain forum with GNOT tips. Posts ranked by tips received.\n\n")
	b.WriteString("Post from the Actions tab, tip from the Actions tab — tips land straight in the author's balance.\n\n")
	b.WriteString("---\n\n")

	postsList := GetPosts()
	if len(postsList) == 0 {
		b.WriteString("No posts yet. Be the first to post!\n")
		return b.String()
	}

	b.WriteString("## Posts (ranked by tips)\n\n")
	for _, post := range postsList {
		b.WriteString("### " + escapeMD(post.Title) + "\n\n")
		b.WriteString("By " + post.Author.String() + " | Tips: " + strconv.Itoa(int(post.TipTotal)) + " ugnot | Replies: " + strconv.Itoa(post.ReplyCount) + "\n\n")
		b.WriteString(escapeMD(post.Body) + "\n\n")
		b.WriteString("[View replies](" + gRealmPath + ":post/" + strconv.Itoa(post.ID) + ")\n\n")
		b.WriteString("---\n\n")
	}
	return b.String()
}

func renderPostPage(postID int) string {
	post, exists := GetPost(postID)
	if !exists {
		return renderError("Post not found")
	}

	var b strings.Builder
	b.WriteString("[← Back to Board](" + gRealmPath + ")\n\n")
	b.WriteString("# " + escapeMD(post.Title) + "\n\n")
	b.WriteString("By " + post.Author.String() + " | Tips: " + strconv.Itoa(int(post.TipTotal)) + " ugnot\n\n")
	b.WriteString(escapeMD(post.Body) + "\n\n")
	b.WriteString("Tip this author from the Actions tab (TipPost, attach ugnot with the call).\n\n")
	b.WriteString("---\n\n")
	b.WriteString("## Replies\n\n")

	postReplies := GetReplies(postID)
	if len(postReplies) == 0 {
		b.WriteString("No replies yet. Reply from the Actions tab.\n")
	} else {
		for _, reply := range postReplies {
			b.WriteString("> " + escapeMD(reply.Body) + "\n>\n")
			b.WriteString("> By " + reply.Author.String() + " | Tips: " + strconv.Itoa(int(reply.TipTotal)) + " ugnot\n\n")
		}
	}
	return b.String()
}

func renderError(msg string) string {
	return "# Error\n\n" + escapeMD(msg) + "\n\n[← Back to Board](" + gRealmPath + ")\n"
}

package tavernboard

// Unit tests for Tavern Board (Gno v1.8 API).
//
// In _test.gno the only crossable realm is the test frame's own `cur`,
// whose Previous() is the test package realm (a code realm, NOT a user
// call). So these tests cover CreatePost/CreateReply/Render and the
// validation paths. The tip flows (which REQUIRE a user caller for the
// OriginSend guard) are covered by the filetest in
// filetests/z_tip_filetest.gno, where testing.SetRealm works the way the
// boards filetests use it.
//
// Note: realm state is shared across tests in a package run, so tests use
// returned IDs and assert relative order, never absolute IDs or empty state.

import (
	"chain"
	"strconv"
	"strings"
	"testing"
)

// pkgAddr is the test caller: the package address of this realm.
// (In _test.gno, cross(cur) makes Previous() the test package realm.)
var pkgAddr = chain.PackageAddress("gno.land/r/g15kxyhlw2zgz2l2sg8526j0nw5j77mkumyuztwj/tavernboard")

func TestCreatePost(cur realm, t *testing.T) {
	id, err := CreatePost(cross(cur), "Hello Tavern", "First post body")
	if err != nil {
		t.Fatalf("CreatePost failed: %v", err)
	}
	if id <= 0 {
		t.Fatalf("CreatePost returned bad id %d", id)
	}
	post, ok := GetPost(id)
	if !ok {
		t.Fatalf("GetPost(%d) not found after create", id)
	}
	if post.Title != "Hello Tavern" {
		t.Fatalf("title %q != %q", post.Title, "Hello Tavern")
	}
	if post.Body != "First post body" {
		t.Fatalf("body %q != %q", post.Body, "First post body")
	}
	if post.Author != pkgAddr {
		t.Fatalf("author %v != %v", post.Author, pkgAddr)
	}
	if post.TipTotal != 0 {
		t.Fatalf("new post TipTotal %d != 0", post.TipTotal)
	}
	if post.ReplyCount != 0 {
		t.Fatalf("new post ReplyCount %d != 0", post.ReplyCount)
	}
}

func TestCreatePostValidation(cur realm, t *testing.T) {
	if _, err := CreatePost(cross(cur), "", "body"); err == nil {
		t.Fatalf("empty title should fail")
	}
	if _, err := CreatePost(cross(cur), "title", ""); err == nil {
		t.Fatalf("empty body should fail")
	}
}

func TestCreateReply(cur realm, t *testing.T) {
	postID, err := CreatePost(cross(cur), "Reply target", "Post for replies")
	if err != nil {
		t.Fatalf("CreatePost failed: %v", err)
	}
	replyID, err := CreateReply(cross(cur), postID, "First reply")
	if err != nil {
		t.Fatalf("CreateReply failed: %v", err)
	}
	if replyID <= 0 {
		t.Fatalf("CreateReply returned bad id %d", replyID)
	}
	post, _ := GetPost(postID)
	if post.ReplyCount != 1 {
		t.Fatalf("ReplyCount %d != 1", post.ReplyCount)
	}
	replies := GetReplies(postID)
	if len(replies) != 1 {
		t.Fatalf("GetReplies len %d != 1", len(replies))
	}
	if replies[0].Body != "First reply" {
		t.Fatalf("reply body %q != %q", replies[0].Body, "First reply")
	}
	if replies[0].Author != post.Author {
		t.Fatalf("reply author %v != post author %v", replies[0].Author, post.Author)
	}
	if replies[0].TipTotal != 0 {
		t.Fatalf("new reply TipTotal %d != 0", replies[0].TipTotal)
	}
}

func TestCreateReplyValidation(cur realm, t *testing.T) {
	if _, err := CreateReply(cross(cur), 999999, "nope"); err == nil {
		t.Fatalf("reply to missing post should fail")
	}
	postID, err := CreatePost(cross(cur), "Empty reply target", "body")
	if err != nil {
		t.Fatalf("CreatePost failed: %v", err)
	}
	if _, err := CreateReply(cross(cur), postID, ""); err == nil {
		t.Fatalf("empty reply body should fail")
	}
}

func TestRenderBoard(cur realm, t *testing.T) {
	id, err := CreatePost(cross(cur), "Render me", "Render body")
	if err != nil {
		t.Fatalf("CreatePost failed: %v", err)
	}
	res := Render("")
	if !strings.Contains(res, "# Tavern Board") {
		t.Fatalf("board render missing title: %q", res)
	}
	if !strings.Contains(res, "Render me") {
		t.Fatalf("board render missing post title: %q", res)
	}
	if !strings.Contains(res, "post/"+strconv.Itoa(id)) {
		t.Fatalf("board render missing post link: %q", res)
	}
}

func TestRenderPost(cur realm, t *testing.T) {
	id, err := CreatePost(cross(cur), "Detail title", "Detail body text")
	if err != nil {
		t.Fatalf("CreatePost failed: %v", err)
	}
	res := Render("post/" + strconv.Itoa(id))
	if !strings.Contains(res, "Detail title") {
		t.Fatalf("post render missing title: %q", res)
	}
	if !strings.Contains(res, "Detail body text") {
		t.Fatalf("post render missing body: %q", res)
	}
	if !strings.Contains(res, "Back to Board") {
		t.Fatalf("post render missing back link: %q", res)
	}
}

func TestRenderErrors(t *testing.T) {
	if res := Render("post/abc"); !strings.Contains(res, "Invalid post ID") {
		t.Fatalf("bad id render wrong: %q", res)
	}
	if res := Render("post/999999"); !strings.Contains(res, "Post not found") {
		t.Fatalf("missing post render wrong: %q", res)
	}
	if res := Render("unknown/path"); !strings.Contains(res, "Page not found") {
		t.Fatalf("unknown path render wrong: %q", res)
	}
}

func TestRenderEscapesUserContent(cur realm, t *testing.T) {
	id, err := CreatePost(cross(cur), "Title *with* [markdown]", "Body with `code` and # hash")
	if err != nil {
		t.Fatalf("CreatePost failed: %v", err)
	}
	res := Render("post/" + strconv.Itoa(id))
	if strings.Contains(res, "Title *with*") {
		t.Fatalf("title markdown not escaped: %q", res)
	}
	if strings.Contains(res, "`code`") {
		t.Fatalf("body markdown not escaped: %q", res)
	}
}

