)

// RenderGuildCrestSVG renders a pure on-chain SVG Guild Crest card for a builder
// or reviewer as a Markdown-embedded base64 data URI suitable for gnoweb.
//
// All user-supplied text is XML/HTML-escaped via p/nt/markdown/sanitize/v0
// before entering SVG <text> nodes.
func RenderGuildCrestSVG(handle string, score ReputationScore, completedBounties int64, earnedUgnot int64) string {
	safeHandle := sanitize.HTMLEscape(truncateString(handle, 26))
	if safeHandle == "" {
		safeHandle = "Anonymous Builder"
	}

	accent := score.Tier.AccentHex()
	tierLabel := score.Tier.String()
	xpLabel := strconv.FormatInt(score.XP, 10) + " XP"
	relLabel := FormatBpsPercent(score.ReliabilityBps) + " reliability"
	statsLabel := strconv.FormatInt(completedBounties, 10) + " quests  |  " + FormatGNOT(earnedUgnot)

	canvas := svg.NewCanvas(420, 128).WithViewBox(0, 0, 420, 128)
	canvas.AddStyle("text", "font-family:ui-monospace,SFMono-Regular,Menlo,monospace")

	// Card background & subtle inner border.
	bg := svg.NewRectangle(2, 2, 416, 124, "#111622")
	bg.RX, bg.RY = 14, 14
	bg.Attr.Stroke = accent
	bg.Attr.StrokeWidth = "2"
	canvas.Append(bg)

	// Left decorative shield emblem.
	shieldBg := svg.NewPolygon("48,22 78,34 74,74 48,96 22,74 18,34", "#1b2436")
	shieldBg.Attr.Stroke = accent
	shieldBg.Attr.StrokeWidth = "2.5"
	canvas.Append(shieldBg)

	shieldCore := svg.NewPolygon("48,34 66,42 63,68 48,82 33,68 30,42", accent)
	shieldCore.Attr.Opacity = "0.22"
	canvas.Append(shieldCore)

	// Tier glyph inside shield.
	tierLetter := tierLabel[:1]
	glyph := svg.NewText(42, 65, tierLetter, accent)
	glyph.Attr.Style = "font-size:24px;font-weight:700"
	canvas.Append(glyph)

	// Top eyebrow: TavernBoard Guild Crest + tier pill.
	eyebrow := svg.NewText(96, 30, "TAVERNBOARD GUILD CREST", "#94a3b8")
	eyebrow.Attr.Style = "font-size:10px;letter-spacing:1.2px"
	canvas.Append(eyebrow)

	pill := svg.NewRectangle(302, 16, 100, 20, accent)
	pill.RX, pill.RY = 10, 10
	pill.Attr.Opacity = "0.2"
	canvas.Append(pill)

	pillTxt := svg.NewText(314, 30, tierLabel, accent)
	pillTxt.Attr.Style = "font-size:11px;font-weight:700"
	canvas.Append(pillTxt)

	// Builder handle.
	nameTxt := svg.NewText(96, 56, safeHandle, "#f8fafc")
	nameTxt.Attr.Style = "font-size:16px;font-weight:700"
	canvas.Append(nameTxt)

	// Stats line.
	statsTxt := svg.NewText(96, 76, statsLabel+"  |  "+relLabel, "#cbd5e1")
	statsTxt.Attr.Style = "font-size:11px"
	canvas.Append(statsTxt)

	// XP progress bar track & fill.
	barTrack := svg.NewRectangle(96, 92, 304, 10, "#1e293b")
	barTrack.RX, barTrack.RY = 5, 5
	canvas.Append(barTrack)

	fillW := int((304 * score.ProgressBps) / BasisPointsTotal)
	if fillW < 10 && score.XP > 0 {
		fillW = 10
	}
	if fillW > 304 {
		fillW = 304
	}
	if fillW > 0 {
		barFill := svg.NewRectangle(96, 92, fillW, 10, accent)
		barFill.RX, barFill.RY = 5, 5
		canvas.Append(barFill)
	}

	xpFooter := svg.NewText(96, 116, xpLabel, accent)
	xpFooter.Attr.Style = "font-size:11px;font-weight:700"
	canvas.Append(xpFooter)

	nextLabel := "MAX TIER ACHIEVED"
	if score.NextTierXP > 0 {
		nextLabel = "Next tier: " + strconv.FormatInt(score.NextTierXP, 10) + " XP"
	}
	nextTxt := svg.NewText(246, 116, nextLabel, "#94a3b8")
	nextTxt.Attr.Style = "font-size:10px"
	canvas.Append(nextTxt)

	return canvas.Render("Guild Crest for " + safeHandle)
}

// RenderEscrowCardSVG renders an on-chain SVG Escrow Vault status & milestone
// progress card for a bounty page in gnoweb.
func RenderEscrowCardSVG(bountyID string, status Status, fundedUgnot, releasedUgnot int64, doneMilestones, totalMilestones int) string {
	safeID := sanitize.HTMLEscape(truncateString(bountyID, 20))
	statusColor := status.ColorHex()
	lockedUgnot := fundedUgnot - releasedUgnot
	if lockedUgnot < 0 {
		lockedUgnot = 0
	}

	canvas := svg.NewCanvas(420, 106).WithViewBox(0, 0, 420, 106)
	canvas.AddStyle("text", "font-family:ui-monospace,SFMono-Regular,Menlo,monospace")

	bg := svg.NewRectangle(2, 2, 416, 102, "#0f172a")
	bg.RX, bg.RY = 12, 12
	bg.Attr.Stroke = statusColor
	bg.Attr.StrokeWidth = "2"
	canvas.Append(bg)

	title := svg.NewText(18, 28, "ISOLATED SUB-REALM ESCROW VAULT #"+safeID, "#94a3b8")
	title.Attr.Style = "font-size:10px;letter-spacing:0.8px"
	canvas.Append(title)

	badge := svg.NewRectangle(314, 14, 90, 20, statusColor)
	badge.RX, badge.RY = 10, 10
	badge.Attr.Opacity = "0.22"
	canvas.Append(badge)

	badgeTxt := svg.NewText(324, 28, status.String(), statusColor)
	badgeTxt.Attr.Style = "font-size:10px;font-weight:700"
	canvas.Append(badgeTxt)

	valTxt := svg.NewText(18, 56, "Locked: "+FormatGNOT(lockedUgnot)+"  |  Paid: "+FormatGNOT(releasedUgnot), "#f8fafc")
	valTxt.Attr.Style = "font-size:13px;font-weight:700"
	canvas.Append(valTxt)

	// Segmented milestone progress bar.
	if totalMilestones < 1 {
		totalMilestones = 1
	}
	totalW := 384
	gap := 4
	segW := (totalW - gap*(totalMilestones-1)) / totalMilestones
	if segW < 8 {
		segW = 8
	}
	for i := 0; i < totalMilestones; i++ {
		fill := "#1e293b"
		if i < doneMilestones {
			fill = statusColor
		}
		seg := svg.NewRectangle(18+i*(segW+gap), 70, segW, 12, fill)
		seg.RX, seg.RY = 4, 4
		canvas.Append(seg)
	}

	footer := svg.NewText(18, 96,
		"Milestones settled: "+strconv.Itoa(doneMilestones)+"/"+strconv.Itoa(totalMilestones)+"  |  Total Vault: "+FormatGNOT(fundedUgnot),
		"#cbd5e1",
	)
	footer.Attr.Style = "font-size:10px"
	canvas.Append(footer)

	return canvas.Render("Escrow Vault " + safeID)
}

func truncateString(s string, maxLen int) string {
	if len(s) <= maxLen {
		return s
	}
	return s[:maxLen]
}

// Package tavernkit is a reusable, stateless pure Gno package powering
// TavernBoard and any third-party Gno.land realm that needs:
//
//   - Dust-free basis-point milestone escrow allocation (integer math only)
//   - Deterministic on-chain builder & reviewer reputation scoring and Craft Tiers
//   - Stake-weighted quorum verdict evaluation for milestone disputes
//   - On-chain SVG Guild Crest and Escrow Progress Card rendering (via p/nt/svg/v0)
//   - Safe GNOT coin formatting and address abbreviation utilities
//
// Because tavernkit lives in /p/ and carries zero mutable state, any Gno realm,
// DAO, or grant program can import it directly to compose milestone escrow math,
// verify Craft Tiers, or render on-chain SVG achievement badges inside gnoweb.
package tavernkit

package tavernkit

import (
	"errors"
	"strconv"
	"strings"
)

// ParseMilestoneSpecs parses a comma-separated milestone specification string.
//
// Supported formats:
//   - Single milestone shorthand: "Full Delivery" -> [{Title: "Full Delivery", WeightBps: 10000}]
//   - Multi-milestone weighted:   "Spec:3000,Implementation:5000,Tests & Docs:2000"
//   - Empty string defaults to a single 100% milestone ("Full Delivery").
//
// Weights must be strictly positive and sum to exactly 10000 basis points (100%).
func ParseMilestoneSpecs(spec string) ([]MilestoneSpec, error) {
	trimmed := strings.TrimSpace(spec)
	if trimmed == "" {
		return []MilestoneSpec{{Title: "Full Delivery", WeightBps: BasisPointsTotal}}, nil
	}

	// Single shorthand without ":" or "," -> 100% single milestone.
	if !strings.Contains(trimmed, ",") && !strings.Contains(trimmed, ":") {
		if len(trimmed) > 80 {
			return nil, errors.New("milestone title exceeds 80 bytes")
		}
		return []MilestoneSpec{{Title: trimmed, WeightBps: BasisPointsTotal}}, nil
	}

	parts := strings.Split(trimmed, ",")
	if len(parts) > MaxMilestones {
		return nil, errors.New("too many milestones: max 8")
	}

	specs := make([]MilestoneSpec, 0, len(parts))
	var sumBps int64

	for _, raw := range parts {
		entry := strings.TrimSpace(raw)
		if entry == "" {
			return nil, errors.New("empty milestone entry")
		}
		sep := strings.LastIndex(entry, ":")
		if sep <= 0 || sep == len(entry)-1 {
			return nil, errors.New("milestone must use 'Title:WeightBps' format")
		}
		title := strings.TrimSpace(entry[:sep])
		weightStr := strings.TrimSpace(entry[sep+1:])
		if title == "" {
			return nil, errors.New("milestone title cannot be empty")
		}
		if len(title) > 80 {
			return nil, errors.New("milestone title exceeds 80 bytes")
		}
		w, err := strconv.ParseInt(weightStr, 10, 64)
		if err != nil || w <= 0 || w > BasisPointsTotal {
			return nil, errors.New("milestone weight must be an integer in 1..10000")
		}
		sumBps += w
		specs = append(specs, MilestoneSpec{
			Title:     title,
			WeightBps: w,
		})
	}

	if sumBps != BasisPointsTotal {
		return nil, errors.New("milestone weights must sum to exactly 10000 basis points")
	}
	return specs, nil
}

// AllocatePayouts splits totalAmount across weightsBps using exact integer math.
// Any rounding dust is assigned to the final milestone so sum(result) == totalAmount.
func AllocatePayouts(totalAmount int64, weightsBps []int64) ([]int64, error) {
	if totalAmount < 0 {
		return nil, errors.New("totalAmount cannot be negative")
	}
	if len(weightsBps) == 0 || len(weightsBps) > MaxMilestones {
		return nil, errors.New("invalid milestone count")
	}

	var sumBps int64
	for _, w := range weightsBps {
		if w <= 0 {
			return nil, errors.New("milestone weight must be positive")
		}
		sumBps += w
	}
	if sumBps != BasisPointsTotal {
		return nil, errors.New("milestone weights must sum to 10000 bps")
	}

	payouts := make([]int64, len(weightsBps))
	var allocated int64
	for i, w := range weightsBps {
		if i == len(weightsBps)-1 {
			payouts[i] = totalAmount - allocated
		} else {
			share := (totalAmount * w) / BasisPointsTotal
			payouts[i] = share
			allocated += share
		}
	}
	return payouts, nil
}

// ComputeReputation deterministically computes XP, CraftTier, and ReliabilityBps
// from on-chain activity counters using pure integer arithmetic.
func ComputeReputation(in ReputationInput) ReputationScore {
	gnotEarned := in.TotalEarnedUgnot / UgnotPerGnot
	if gnotEarned < 0 {
		gnotEarned = 0
	}
	// Cap earnings XP bonus at 500 GNOT (2500 XP) so whales cannot buy Archmage
	// without actually delivering bounties and aligned reviews.
	if gnotEarned > 500 {
		gnotEarned = 500
	}

	xp := in.CompletedBounties*250 +
		in.ApprovedMilestones*80 +
		gnotEarned*5 +
		in.ReviewsAligned*60 +
		in.DisputesWon*100 -
		in.ReviewsSlashed*120 -
		in.DisputesLost*150

	if xp < 0 {
		xp = 0
	}

	tier := TierForXP(xp)
	nextXP := nextTierThreshold(tier)
	var progressBps int64 = BasisPointsTotal
	if nextXP > 0 {
		floorXP := tier.MinXP()
		span := nextXP - floorXP
		if span > 0 {
			progressBps = ((xp - floorXP) * BasisPointsTotal) / span
			if progressBps < 0 {
				progressBps = 0
			}
			if progressBps > BasisPointsTotal {
				progressBps = BasisPointsTotal
			}
		}
	}

	positive := in.ApprovedMilestones + in.ReviewsAligned + in.DisputesWon
	negative := in.ReviewsSlashed + in.DisputesLost
	totalOutcomes := positive + negative
	var reliabilityBps int64 = BasisPointsTotal
	if totalOutcomes > 0 {
		reliabilityBps = (positive * BasisPointsTotal) / totalOutcomes
	}

	return ReputationScore{
		XP:             xp,
		Tier:           tier,
		ReliabilityBps: reliabilityBps,
		NextTierXP:     nextXP,
		ProgressBps:    progressBps,
	}
}

// TierForXP returns the CraftTier corresponding to an XP score.
func TierForXP(xp int64) CraftTier {
	switch {
	case xp >= TierArchmage.MinXP():
		return TierArchmage
	case xp >= TierMaster.MinXP():
		return TierMaster
	case xp >= TierArtisan.MinXP():
		return TierArtisan
	case xp >= TierJourneyman.MinXP():
		return TierJourneyman
	default:
		return TierApprentice
	}
}

func nextTierThreshold(t CraftTier) int64 {
	switch t {
	case TierApprentice:
		return TierJourneyman.MinXP()
	case TierJourneyman:
		return TierArtisan.MinXP()
	case TierArtisan:
		return TierMaster.MinXP()
	case TierMaster:
		return TierArchmage.MinXP()
	default:
		return 0
	}
}

// EvaluateQuorum checks whether reviewer votes have reached a decisive outcome.
// Ties are not decisive; an extra vote is required to break a tie so disputes
// always resolve by strict majority once minQuorum is met.
func EvaluateQuorum(approveVotes, rejectVotes, minQuorum int) QuorumTally {
	if minQuorum < 1 {
		minQuorum = 1
	}
	total := approveVotes + rejectVotes
	decided := total >= minQuorum && approveVotes != rejectVotes
	return QuorumTally{
		ApproveVotes: approveVotes,
		RejectVotes:  rejectVotes,
		TotalVotes:   total,
		MinQuorum:    minQuorum,
		Decided:      decided,
		BuilderWins:  decided && approveVotes > rejectVotes,
	}
}

// FormatGNOT formats an amount in ugnot as a clean human-readable GNOT string
// without floating-point arithmetic.
func FormatGNOT(ugnot int64) string {
	if ugnot == 0 {
		return "0 GNOT"
	}
	sign := ""
	if ugnot < 0 {
		sign = "-"
		ugnot = -ugnot
	}
	whole := ugnot / UgnotPerGnot
	frac := ugnot % UgnotPerGnot
	if frac == 0 {
		return sign + strconv.FormatInt(whole, 10) + " GNOT"
	}
	fracStr := strconv.FormatInt(frac, 10)
	// Pad left to 6 digits.
	for len(fracStr) < 6 {
		fracStr = "0" + fracStr
	}
	// Trim trailing zeroes while keeping at least 2 decimal places for readability.
	for len(fracStr) > 2 && fracStr[len(fracStr)-1] == '0' {
		fracStr = fracStr[:len(fracStr)-1]
	}
	return sign + strconv.FormatInt(whole, 10) + "." + fracStr + " GNOT"
}

// FormatBpsPercent formats basis points (e.g. 9550) as "95.5%".
func FormatBpsPercent(bps int64) string {
	if bps <= 0 {
		return "0%"
	}
	whole := bps / 100
	tenth := (bps % 100) / 10
	if tenth == 0 {
		return strconv.FormatInt(whole, 10) + "%"
	}
	return strconv.FormatInt(whole, 10) + "." + strconv.FormatInt(tenth, 10) + "%"
}

// ShortAddr returns a compact representation of a bech32 address (e.g. g1abcd...wxyz).
func ShortAddr(addr address) string {
	s := string(addr)
	if len(s) <= 14 {
		return s
	}
	return s[:8] + "..." + s[len(s)-4:]
}

package tavernkit

import (
	"fmt"
	"strings"
	"testing"

	"gno.land/p/nt/uassert/v0"
)

func TestParseMilestoneSpecs(t *testing.T) {
	// Empty defaults to 100% single milestone.
	specs, err := ParseMilestoneSpecs("")
	uassert.NoError(t, err)
	uassert.Equal(t, 1, len(specs))
	uassert.Equal(t, "Full Delivery", specs[0].Title)
	uassert.Equal(t, int64(10000), specs[0].WeightBps)

	// Shorthand single milestone.
	specs, err = ParseMilestoneSpecs("Ship GRC20 Bridge")
	uassert.NoError(t, err)
	uassert.Equal(t, 1, len(specs))
	uassert.Equal(t, "Ship GRC20 Bridge", specs[0].Title)
	uassert.Equal(t, int64(10000), specs[0].WeightBps)

	// Multi-milestone weighted.
	specs, err = ParseMilestoneSpecs("Design Spec:2500, Core Realm:5000, Tests & Docs:2500")
	uassert.NoError(t, err)
	uassert.Equal(t, 3, len(specs))
	uassert.Equal(t, "Design Spec", specs[0].Title)
	uassert.Equal(t, int64(2500), specs[0].WeightBps)
	uassert.Equal(t, "Core Realm", specs[1].Title)
	uassert.Equal(t, int64(5000), specs[1].WeightBps)
	uassert.Equal(t, "Tests & Docs", specs[2].Title)
	uassert.Equal(t, int64(2500), specs[2].WeightBps)

	// Bad sum rejected.
	_, err = ParseMilestoneSpecs("A:3000,B:3000")
	uassert.Error(t, err)

	// Zero weight rejected.
	_, err = ParseMilestoneSpecs("A:0,B:10000")
	uassert.Error(t, err)

	// Too many milestones (> 8) rejected.
	_, err = ParseMilestoneSpecs("1:1000,2:1000,3:1000,4:1000,5:1000,6:1000,7:1000,8:1000,9:2000")
	uassert.Error(t, err)
}

func TestAllocatePayoutsDustFree(t *testing.T) {
	// 100 ugnot split 3333 / 3333 / 3334 -> 33 + 33 + 34 = 100 (zero dust lost!)
	payouts, err := AllocatePayouts(100, []int64{3333, 3333, 3334})
	uassert.NoError(t, err)
	uassert.Equal(t, 3, len(payouts))
	uassert.Equal(t, int64(33), payouts[0])
	uassert.Equal(t, int64(33), payouts[1])
	uassert.Equal(t, int64(34), payouts[2])
	uassert.Equal(t, int64(100), payouts[0]+payouts[1]+payouts[2])

	// Odd amount 1_000_007 across 3 milestones sums identically.
	payouts, err = AllocatePayouts(1000007, []int64{2500, 5000, 2500})
	uassert.NoError(t, err)
	uassert.Equal(t, int64(1000007), payouts[0]+payouts[1]+payouts[2])

	// Negative rejected.
	_, err = AllocatePayouts(-1, []int64{10000})
	uassert.Error(t, err)
}

func TestComputeReputationAndTiers(t *testing.T) {
	// Fresh builder -> Apprentice, 0 XP, 100% reliability.
	s0 := ComputeReputation(ReputationInput{})
	uassert.Equal(t, int64(0), s0.XP)
	uassert.Equal(t, TierApprentice.String(), s0.Tier.String())
	uassert.Equal(t, int64(10000), s0.ReliabilityBps)
	uassert.Equal(t, int64(250), s0.NextTierXP)

	// Active builder -> Journeyman (250 + 160 + 50 = 460 XP).
	s1 := ComputeReputation(ReputationInput{
		CompletedBounties:  1,
		ApprovedMilestones: 2,
		TotalEarnedUgnot:   10 * UgnotPerGnot,
	})
	uassert.Equal(t, int64(460), s1.XP)
	uassert.Equal(t, TierJourneyman.String(), s1.Tier.String())
	uassert.Equal(t, int64(750), s1.NextTierXP)

	// Slashing reduces XP and reliability, floored at 0.
	sSlash := ComputeReputation(ReputationInput{
		ReviewsAligned: 1,
		ReviewsSlashed: 3,
		DisputesLost:   1,
	})
	uassert.Equal(t, int64(0), sSlash.XP)
	uassert.Equal(t, TierApprentice.String(), sSlash.Tier.String())
	uassert.Equal(t, int64(2000), sSlash.ReliabilityBps) // 1 / 5 = 20%

	// Archmage ceiling.
	sMax := ComputeReputation(ReputationInput{
		CompletedBounties:  15,
		ApprovedMilestones: 30,
		TotalEarnedUgnot:   10000 * UgnotPerGnot, // capped at 500 GNOT bonus
		ReviewsAligned:     10,
	})
	uassert.Equal(t, TierArchmage.String(), sMax.Tier.String())
	uassert.Equal(t, int64(0), sMax.NextTierXP)
	uassert.Equal(t, int64(10000), sMax.ProgressBps)
}

func TestEvaluateQuorum(t *testing.T) {
	// Below quorum -> undecided.
	q1 := EvaluateQuorum(2, 0, 3)
	uassert.False(t, q1.Decided)

	// Tie at quorum (e.g. 2 vs 2 with minQuorum 3) -> undecided.
	qTie := EvaluateQuorum(2, 2, 3)
	uassert.False(t, qTie.Decided)

	// Strict majority builder wins (2 vs 1 with minQuorum 3).
	qWin := EvaluateQuorum(2, 1, 3)
	uassert.True(t, qWin.Decided)
	uassert.True(t, qWin.BuilderWins)

	// Strict majority sponsor wins (1 vs 2 with minQuorum 3).
	qReject := EvaluateQuorum(1, 2, 3)
	uassert.True(t, qReject.Decided)
	uassert.False(t, qReject.BuilderWins)
}

func TestFormatGNOT(t *testing.T) {
	uassert.Equal(t, "0 GNOT", FormatGNOT(0))
	uassert.Equal(t, "5 GNOT", FormatGNOT(5000000))
	uassert.Equal(t, "12.50 GNOT", FormatGNOT(12500000))
	uassert.Equal(t, "0.0025 GNOT", FormatGNOT(2500))
	uassert.Equal(t, "-1.25 GNOT", FormatGNOT(-1250000))
}

func TestRenderSVGSanitizesInput(t *testing.T) {
	score := ComputeReputation(ReputationInput{
		CompletedBounties:  4,
		ApprovedMilestones: 8,
		TotalEarnedUgnot:   25 * UgnotPerGnot,
	})
	crest := RenderGuildCrestSVG(`<script>alert(1)</script>`, score, 4, 25*UgnotPerGnot)
	uassert.True(t, strings.HasPrefix(crest, "![Guild Crest for "))
	uassert.True(t, strings.Contains(crest, "data:image/svg+xml;base64,"))
	uassert.False(t, strings.Contains(crest, "<script>"))

	escrow := RenderEscrowCardSVG("1", StatusInReview, 10*UgnotPerGnot, 4*UgnotPerGnot, 1, 3)
	uassert.True(t, strings.HasPrefix(escrow, "![Escrow Vault 1](data:image/svg+xml;base64,"))
}

