package tavernkit

// BasisPointsTotal represents 100.00% in integer basis points.
const BasisPointsTotal int64 = 10000

// UgnotPerGnot is the number of micro-GNOT (ugnot) per 1 GNOT.
const UgnotPerGnot int64 = 1000000

// MaxMilestones bounds milestone count per bounty to keep storage & gas predictable.
const MaxMilestones = 8

// Status represents the lifecycle phase of a TavernBoard bounty.
type Status uint8

const (
	StatusOpen Status = iota
	StatusClaimed
	StatusInReview
	StatusDisputed
	StatusCompleted
	StatusCancelled
	StatusArchived
)

// String returns a human-readable label for a bounty Status.
func (s Status) String() string {
	switch s {
	case StatusOpen:
		return "OPEN"
	case StatusClaimed:
		return "CLAIMED"
	case StatusInReview:
		return "IN REVIEW"
	case StatusDisputed:
		return "DISPUTED"
	case StatusCompleted:
		return "COMPLETED"
	case StatusCancelled:
		return "CANCELLED"
	case StatusArchived:
		return "ARCHIVED"
	default:
		return "UNKNOWN"
	}
}

// ColorHex returns a hex color for SVG rendering of the status badge.
func (s Status) ColorHex() string {
	switch s {
	case StatusOpen:
		return "#22c55e"
	case StatusClaimed:
		return "#38bdf8"
	case StatusInReview:
		return "#f59e0b"
	case StatusDisputed:
		return "#ef4444"
	case StatusCompleted:
		return "#a855f7"
	case StatusCancelled:
		return "#64748b"
	case StatusArchived:
		return "#475569"
	default:
		return "#94a3b8"
	}
}

// MilestoneStatus represents the state of an individual bounty milestone.
type MilestoneStatus uint8

const (
	MilestonePending MilestoneStatus = iota
	MilestoneSubmitted
	MilestoneRevisionRequested
	MilestoneApproved
	MilestoneDisputed
	MilestoneResolvedBuilder
	MilestoneResolvedSponsor
)

// String returns a human-readable label for MilestoneStatus.
func (ms MilestoneStatus) String() string {
	switch ms {
	case MilestonePending:
		return "PENDING"
	case MilestoneSubmitted:
		return "SUBMITTED"
	case MilestoneRevisionRequested:
		return "REVISION"
	case MilestoneApproved:
		return "APPROVED"
	case MilestoneDisputed:
		return "DISPUTED"
	case MilestoneResolvedBuilder:
		return "PAID (QUORUM)"
	case MilestoneResolvedSponsor:
		return "REFUNDED (QUORUM)"
	default:
		return "UNKNOWN"
	}
}

// IsTerminal reports whether the milestone has already been settled.
func (ms MilestoneStatus) IsTerminal() bool {
	return ms == MilestoneApproved ||
		ms == MilestoneResolvedBuilder ||
		ms == MilestoneResolvedSponsor
}

// CraftTier represents a builder's on-chain reputation rank.
type CraftTier uint8

const (
	TierApprentice CraftTier = iota
	TierJourneyman
	TierArtisan
	TierMaster
	TierArchmage
)

// String returns the display title of a CraftTier.
func (t CraftTier) String() string {
	switch t {
	case TierApprentice:
		return "Apprentice"
	case TierJourneyman:
		return "Journeyman"
	case TierArtisan:
		return "Artisan"
	case TierMaster:
		return "Master"
	case TierArchmage:
		return "Archmage"
	default:
		return "Apprentice"
	}
}

// MinXP returns the minimum XP threshold required for this tier.
func (t CraftTier) MinXP() int64 {
	switch t {
	case TierApprentice:
		return 0
	case TierJourneyman:
		return 250
	case TierArtisan:
		return 750
	case TierMaster:
		return 2000
	case TierArchmage:
		return 5000
	default:
		return 0
	}
}

// AccentHex returns the primary crest accent color for this CraftTier.
func (t CraftTier) AccentHex() string {
	switch t {
	case TierApprentice:
		return "#94a3b8"
	case TierJourneyman:
		return "#38bdf8"
	case TierArtisan:
		return "#f59e0b"
	case TierMaster:
		return "#c084fc"
	case TierArchmage:
		return "#fbbf24"
	default:
		return "#94a3b8"
	}
}

// MilestoneSpec defines a single milestone's title and basis-point payout share.
type MilestoneSpec struct {
	Title     string
	WeightBps int64
}

// ReputationInput aggregates verifiable on-chain activity for a builder or reviewer.
type ReputationInput struct {
	CompletedBounties  int64
	ApprovedMilestones int64
	TotalEarnedUgnot   int64
	ReviewsAligned     int64
	ReviewsSlashed     int64
	DisputesWon        int64
	DisputesLost       int64
}

// ReputationScore is the deterministic reputation output computed from ReputationInput.
type ReputationScore struct {
	XP             int64
	Tier           CraftTier
	ReliabilityBps int64 // 0..10000 (10000 = 100.00%)
	NextTierXP     int64 // 0 if already at TierArchmage
	ProgressBps    int64 // progress toward next tier in basis points (0..10000)
}

// QuorumTally summarizes reviewer quorum voting state for a disputed milestone.
type QuorumTally struct {
	ApproveVotes int
	RejectVotes  int
	TotalVotes   int
	MinQuorum    int
	Decided      bool
	BuilderWins  bool
}

// Package tavernboard implements TavernBoard — an on-chain micro-bounty,
// isolated sub-realm escrow, stake-backed reviewer quorum, and composable
// builder reputation realm built for Gno.land v1.8 (Onyx & Mainnet).
//
// Key Gno.land v1.8 capabilities demonstrated:
//   - Per-bounty cryptographically isolated Sub-Realm Escrow Vaults via
//     cur.Sub("escrow/<id>") and per-dispute Reviewer Stake Vaults via
//     cur.Sub("stake/<id>"), enforced at the GnoVM banker level.
//   - Direct EOA funding guarded by cur.Previous().IsUserCall() +
//     BankerTypeOriginSend, plus composable DAO / cross-realm top-ups via
//     chain.DerivePkgSubAddr + SyncBountyVault.
//   - Strict Interrealm v2 security hygiene: no leaked mutable pointers,
//     no unsafe.PreviousRealm(), single-denom banker.GetCoin reads, and
//     slot-aware Markdown sanitization via p/nt/markdown/sanitize/v0.
//   - Rich gnoweb-native multi-route Render(path) UI with on-chain SVG
//     Guild Crests, Escrow Progress Cards, one-click txlink actions, and
//     permissionless storage-deposit reclamation via ArchiveClosedBounty.
package tavernboard

package tavernboard

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
	"strconv"
)

// escrowSubpath returns the canonical sub-realm path for a bounty's isolated
// escrow vault (e.g. "escrow/42"). Matches Gno v1.8 cur.Sub subpath grammar.
func escrowSubpath(bountyID uint64) string {
	return "escrow/" + strconv.FormatUint(bountyID, 10)
}

// stakeSubpath returns the canonical sub-realm path for a bounty's isolated
// reviewer stake vault (e.g. "stake/42").
func stakeSubpath(bountyID uint64) string {
	return "stake/" + strconv.FormatUint(bountyID, 10)
}

// DeriveEscrowAddress returns the deterministic bech32 address of the isolated
// sub-realm escrow vault for bountyID. Any external user, DAO, or realm can
// send ugnot directly to this address and call SyncBountyVault to co-fund it.
func DeriveEscrowAddress(bountyID uint64) address {
	if bountyID == 0 {
		panic("invalid bounty ID")
	}
	return chain.DerivePkgSubAddr(realmPkgPath, escrowSubpath(bountyID))
}

// DeriveStakeAddress returns the deterministic bech32 address of the isolated
// sub-realm reviewer stake vault for bountyID.
func DeriveStakeAddress(bountyID uint64) address {
	if bountyID == 0 {
		panic("invalid bounty ID")
	}
	return chain.DerivePkgSubAddr(realmPkgPath, stakeSubpath(bountyID))
}

// sweepOriginSendToSub validates an inbound direct EOA ugnot transfer and
// immediately moves the exact sent ugnot from this realm's address into the
// target sub-realm vault using BankerTypeOriginSend.
//
// Security invariant:
//   - Requires cur.Previous().IsUserCall() (blocks MsgRun ephemeral realms &
//     intermediate code realms from spoofing OriginSend).
//   - Uses BankerTypeOriginSend so at most this message's exact send-envelope
//     can ever be swept; host-realm balances cannot be touched.
//   - Rejects unexpected coin denominations so users never strand non-ugnot
//     tokens inside the realm.
func sweepOriginSendToSub(_ int, rlm realm, subpath string, minUgnot int64) (address, int64) {
	requireDirectUserCall(0, rlm)

	sent := unsafe.OriginSend()
	if len(sent) != 1 || sent[0].Denom != nativeDenom {
		panic("attach native ugnot only (e.g. -send 1000000ugnot)")
	}
	amount := sent[0].Amount
	if amount < minUgnot {
		panic("insufficient ugnot sent: minimum is " + strconv.FormatInt(minUgnot, 10) + nativeDenom)
	}

	sub := rlm.Sub(subpath)
	origBanker := banker.NewBanker(banker.BankerTypeOriginSend, rlm)
	origBanker.SendCoins(rlm.Address(), sub.Address(), chain.NewCoins(chain.NewCoin(nativeDenom, amount)))
	return sub.Address(), amount
}

// sendFromSubVault transfers ugnot out of an isolated sub-realm vault using a
// RealmSend banker scoped exclusively to that sub-realm token.
//
// Security invariant: the GnoVM banker strictly checks sub.Address() == from,
// making cross-bounty vault drains structurally impossible at the VM layer.
func sendFromSubVault(_ int, rlm realm, subpath string, to address, amount int64) {
	if amount <= 0 {
		return
	}
	sub := rlm.Sub(subpath)
	subBanker := banker.NewBanker(banker.BankerTypeRealmSend, sub)
	subBanker.SendCoins(sub.Address(), to, chain.NewCoins(chain.NewCoin(nativeDenom, amount)))
}

// liveVaultUgnot reads the live native ugnot balance of a vault using a
// single-denom GetCoin lookup (O(1) store read; immune to unsolicited-denom
// gas-griefing attacks).
func liveVaultUgnot(vaultAddr address) int64 {
	return banker.NewReadonlyBanker().GetCoin(vaultAddr, nativeDenom)
}

package tavernboard

import (
	"chain"
	"strconv"
	"strings"
	"time"

	"gno.land/p/nt/markdown/sanitize/v0"
	"gno.land/p/g1uhez53ghm94hh8m4ezxs82240ql87vfppjq0mc/tavernkit"
)

// PostBounty creates a new multi-milestone bounty funded by the attached native
// ugnot (-send) and locks the coins inside a freshly minted, isolated sub-realm
// escrow vault (cur.Sub("escrow/<id>")).
//
// Parameters:
//   - title: concise quest title (1..120 bytes)
//   - summary: detailed acceptance criteria & deliverables (1..1200 bytes)
//   - tags: optional comma-separated categories (e.g. "realm,defi,gnoweb")
//   - milestoneSpec: "Full Delivery" or "Spec:3000,Core:5000,Docs:2000" (sum = 10000 bps)
//   - deadlineDays: number of days until sponsor may reclaim unsettled escrow (1..365)
//   - minReviewerStakeUgnot: minimum ugnot stake per dispute reviewer (0 uses default 50,000 ugnot)
//   - reviewerQuorum: minimum reviewers to settle a dispute (0 uses default 3; range 1..7)
func PostBounty(
	cur realm,
	title string,
	summary string,
	tags string,
	milestoneSpec string,
	deadlineDays int64,
	minReviewerStakeUgnot int64,
	reviewerQuorum int,
) uint64 {
	sponsor := requireDirectUserCall(0, cur)

	title = strings.TrimSpace(title)
	summary = strings.TrimSpace(summary)
	tags = strings.TrimSpace(tags)

	if title == "" || len(title) > MaxTitleLen {
		panic("title must be between 1 and 120 bytes")
	}
	if summary == "" || len(summary) > MaxSummaryLen {
		panic("summary must be between 1 and 1200 bytes")
	}
	if len(tags) > MaxTagsLen {
		panic("tags exceed 120 bytes")
	}
	if deadlineDays < 1 || deadlineDays > MaxDeadlineDays {
		panic("deadlineDays must be between 1 and 365")
	}

	if minReviewerStakeUgnot == 0 {
		minReviewerStakeUgnot = DefaultMinReviewerStakeUgnot
	}
	if minReviewerStakeUgnot < FloorReviewerStakeUgnot {
		panic("minReviewerStakeUgnot below floor of 10000ugnot")
	}

	if reviewerQuorum == 0 {
		reviewerQuorum = DefaultReviewerQuorum
	}
	if reviewerQuorum < 1 || reviewerQuorum > MaxReviewerQuorum {
		panic("reviewerQuorum must be between 1 and 7")
	}

	specs, err := tavernkit.ParseMilestoneSpecs(milestoneSpec)
	if err != nil {
		panic("invalid milestoneSpec: " + err.Error())
	}

	id := uint64(nextBountyID.Next())
	vaultAddr, funded := sweepOriginSendToSub(0, cur, escrowSubpath(id), MinBountyUgnot)

	weights := make([]int64, len(specs))
	for i, sp := range specs {
		weights[i] = sp.WeightBps
	}
	payouts, err := tavernkit.AllocatePayouts(funded, weights)
	if err != nil {
		panic("payout allocation failed: " + err.Error())
	}

	ms := make([]*milestone, len(specs))
	for i, sp := range specs {
		ms[i] = &milestone{
			index:       i,
			title:       sp.Title,
			weightBps:   sp.WeightBps,
			payoutUgnot: payouts[i],
			status:      tavernkit.MilestonePending,
		}
	}

	now := time.Now()
	b := &bounty{
		id:                    id,
		title:                 title,
		summary:               summary,
		tags:                  tags,
		sponsor:               sponsor,
		status:                tavernkit.StatusOpen,
		totalFundedUgnot:      funded,
		vaultAccountedUgnot:   funded,
		createdAt:             now,
		deadline:              now.Add(time.Duration(deadlineDays) * 24 * time.Hour),
		minReviewerStakeUgnot: minReviewerStakeUgnot,
		reviewerQuorum:        reviewerQuorum,
		milestones:            ms,
	}

	bounties.Set(bountyKey(id), b)
	p := getOrCreateProfile(sponsor)
	p.bountiesPosted++

	statTotalBounties++
	statOpenBounties++
	statTotalFundedUgnot += funded
	statActiveEscrowUgnot += funded

	chain.Emit(
		"BountyPosted",
		"id", strconv.FormatUint(id, 10),
		"sponsor", sponsor.String(),
		"vault", vaultAddr.String(),
		"fundedUgnot", strconv.FormatInt(funded, 10),
		"milestones", strconv.Itoa(len(ms)),
	)
	return id
}

// TopUpBounty allows any direct EOA co-sponsor to add additional ugnot to an
// active bounty's isolated escrow vault. The bonus is distributed dust-free
// across all remaining unsettled milestones according to their relative weights.
func TopUpBounty(cur realm, bountyID uint64) int64 {
	funder := requireDirectUserCall(0, cur)
	b := mustGetBounty(bountyID)
	ensureTopUpAllowed(b)

	_, added := sweepOriginSendToSub(0, cur, escrowSubpath(bountyID), 1)
	creditAdditionalFunding(b, added)

	chain.Emit(
		"BountyToppedUp",
		"id", strconv.FormatUint(bountyID, 10),
		"funder", funder.String(),
		"addedUgnot", strconv.FormatInt(added, 10),
		"newTotalUgnot", strconv.FormatInt(b.totalFundedUgnot, 10),
	)
	return b.totalFundedUgnot
}

// SyncBountyVault enables composable DAO / cross-realm / direct bank co-funding:
// if any external actor transferred ugnot directly to DeriveEscrowAddress(bountyID),
// calling SyncBountyVault detects the surplus balance and allocates it across
// unsettled milestones.
func SyncBountyVault(cur realm, bountyID uint64) int64 {
	caller := requireLiveCaller(0, cur)
	b := mustGetBounty(bountyID)
	ensureTopUpAllowed(b)

	vaultAddr := DeriveEscrowAddress(bountyID)
	live := liveVaultUgnot(vaultAddr)
	delta := live - b.vaultAccountedUgnot
	if delta <= 0 {
		panic("no uncredited ugnot in escrow vault")
	}

	creditAdditionalFunding(b, delta)

	chain.Emit(
		"BountyVaultSynced",
		"id", strconv.FormatUint(bountyID, 10),
		"caller", caller.String(),
		"syncedUgnot", strconv.FormatInt(delta, 10),
		"newTotalUgnot", strconv.FormatInt(b.totalFundedUgnot, 10),
	)
	return delta
}

func ensureTopUpAllowed(b *bounty) {
	if b.status == tavernkit.StatusCompleted || b.status == tavernkit.StatusCancelled || b.status == tavernkit.StatusArchived {
		panic("cannot fund a closed bounty")
	}
	if countUnsettledMilestones(b) == 0 {
		panic("no unsettled milestones remaining")
	}
}

func creditAdditionalFunding(b *bounty, added int64) {
	var unsettled []*milestone
	var sumWeights int64
	for _, m := range b.milestones {
		if !m.status.IsTerminal() {
			unsettled = append(unsettled, m)
			sumWeights += m.weightBps
		}
	}
	// Distribute dust-free proportionally across unsettled milestones.
	var distributed int64
	for i, m := range unsettled {
		var share int64
		if i == len(unsettled)-1 {
			share = added - distributed
		} else {
			share = (added * m.weightBps) / sumWeights
			distributed += share
		}
		m.payoutUgnot += share
	}
	b.totalFundedUgnot += added
	b.vaultAccountedUgnot += added
	statTotalFundedUgnot += added
	statActiveEscrowUgnot += added
}

// ClaimBounty assigns an Open bounty to the caller. Sponsors cannot claim their
// own bounty to prevent wash-farming on-chain reputation XP.
func ClaimBounty(cur realm, bountyID uint64, pitch string) {
	builder := requireLiveCaller(0, cur)
	b := mustGetBounty(bountyID)

	if b.status != tavernkit.StatusOpen {
		panic("bounty is not open for claims")
	}
	if time.Now().After(b.deadline) {
		panic("bounty deadline has passed")
	}
	if builder == b.sponsor {
		panic("sponsor cannot claim own bounty")
	}
	pitch = strings.TrimSpace(pitch)
	if len(pitch) > MaxPitchLen {
		panic("pitch exceeds 400 bytes")
	}

	b.builder = builder
	b.builderPitch = pitch
	b.status = tavernkit.StatusClaimed
	statOpenBounties--

	p := getOrCreateProfile(builder)
	p.bountiesClaimed++

	chain.Emit(
		"BountyClaimed",
		"id", strconv.FormatUint(bountyID, 10),
		"builder", builder.String(),
	)
}

// ReleaseClaim lets the active builder step down before any milestone has been
// submitted or settled, returning the bounty to Open status.
func ReleaseClaim(cur realm, bountyID uint64) {
	caller := requireLiveCaller(0, cur)
	b := mustGetBounty(bountyID)

	if caller != b.builder {
		panic("only the assigned builder can release a claim")
	}
	if b.status != tavernkit.StatusClaimed {
		panic("can only release claim while status is CLAIMED")
	}
	for _, m := range b.milestones {
		if m.status != tavernkit.MilestonePending {
			panic("cannot release claim after milestone work has been submitted or settled")
		}
	}

	b.builder = ""
	b.builderPitch = ""
	b.status = tavernkit.StatusOpen
	statOpenBounties++

	chain.Emit(
		"ClaimReleased",
		"id", strconv.FormatUint(bountyID, 10),
		"builder", caller.String(),
	)
}

// SubmitMilestone submits a verifiable proof-of-delivery URL (e.g. GitHub PR,
// commit hash, deployed onyx-1 realm link) and delivery notes for a milestone.
func SubmitMilestone(cur realm, bountyID uint64, milestoneIdx int, proofURL string, notes string) {
	caller := requireLiveCaller(0, cur)
	b := mustGetBounty(bountyID)

	if caller != b.builder {
		panic("only the assigned builder can submit milestones")
	}
	if b.status != tavernkit.StatusClaimed && b.status != tavernkit.StatusInReview {
		panic("bounty is not accepting milestone submissions")
	}
	m := mustGetMilestone(b, milestoneIdx)
	if m.status != tavernkit.MilestonePending && m.status != tavernkit.MilestoneRevisionRequested {
		panic("milestone is not pending or awaiting revision")
	}

	proofURL = strings.TrimSpace(proofURL)
	notes = strings.TrimSpace(notes)
	if proofURL == "" || len(proofURL) > MaxProofURLLen {
		panic("proofURL must be between 1 and 256 bytes")
	}
	// Reject unsafe URL schemes (javascript:, data:text/html, etc.) at write time.
	if sanitize.URL(proofURL) == "" {
		panic("proofURL rejected: must use a safe https://, http://, or relative URL")
	}
	if len(notes) > MaxNotesLen {
		panic("delivery notes exceed 800 bytes")
	}

	m.proofURL = proofURL
	m.deliveryNotes = notes
	m.status = tavernkit.MilestoneSubmitted
	m.submittedAt = time.Now()
	b.status = tavernkit.StatusInReview

	chain.Emit(
		"MilestoneSubmitted",
		"id", strconv.FormatUint(bountyID, 10),
		"milestone", strconv.Itoa(milestoneIdx),
		"builder", caller.String(),
	)
}

// ApproveMilestone allows the bounty sponsor to accept a submitted milestone
// and immediately release that milestone's exact ugnot payout from the bounty's
// isolated sub-realm escrow vault to the builder.
func ApproveMilestone(cur realm, bountyID uint64, milestoneIdx int, feedback string) {
	caller := requireLiveCaller(0, cur)
	b := mustGetBounty(bountyID)

	if caller != b.sponsor {
		panic("only the bounty sponsor can approve milestones")
	}
	m := mustGetMilestone(b, milestoneIdx)
	if m.status != tavernkit.MilestoneSubmitted {
		panic("milestone is not awaiting review")
	}
	feedback = strings.TrimSpace(feedback)
	if len(feedback) > MaxFeedbackLen {
		panic("feedback exceeds 500 bytes")
	}

	payout := m.payoutUgnot
	m.sponsorFeedback = feedback
	m.status = tavernkit.MilestoneApproved
	m.settledAt = time.Now()

	// Effects before transfer, then spend from this bounty's isolated sub-vault.
	b.totalReleasedUgnot += payout
	b.vaultAccountedUgnot -= payout
	statTotalPaidUgnot += payout
	statActiveEscrowUgnot -= payout

	sendFromSubVault(0, cur, escrowSubpath(bountyID), b.builder, payout)

	bp := getOrCreateProfile(b.builder)
	bp.approvedMilestones++
	bp.totalEarnedUgnot += payout

	refreshBountyCompletion(b, bp)

	chain.Emit(
		"MilestoneApproved",
		"id", strconv.FormatUint(bountyID, 10),
		"milestone", strconv.Itoa(milestoneIdx),
		"builder", b.builder.String(),
		"payoutUgnot", strconv.FormatInt(payout, 10),
	)
}

// RequestRevision lets the sponsor return a submitted milestone to the builder
// with actionable feedback (up to MaxRevisionRequests times).
func RequestRevision(cur realm, bountyID uint64, milestoneIdx int, feedback string) {
	caller := requireLiveCaller(0, cur)
	b := mustGetBounty(bountyID)

	if caller != b.sponsor {
		panic("only the bounty sponsor can request revisions")
	}
	m := mustGetMilestone(b, milestoneIdx)
	if m.status != tavernkit.MilestoneSubmitted {
		panic("milestone is not awaiting review")
	}
	if m.revisionCount >= MaxRevisionRequests {
		panic("maximum revision requests reached; approve or open a dispute")
	}
	feedback = strings.TrimSpace(feedback)
	if feedback == "" || len(feedback) > MaxFeedbackLen {
		panic("revision feedback must be between 1 and 500 bytes")
	}

	m.sponsorFeedback = feedback
	m.revisionCount++
	m.status = tavernkit.MilestoneRevisionRequested
	updateActiveBountyStatus(b)

	chain.Emit(
		"RevisionRequested",
		"id", strconv.FormatUint(bountyID, 10),
		"milestone", strconv.Itoa(milestoneIdx),
		"revisionCount", strconv.Itoa(m.revisionCount),
	)
}

// OpenDispute escalates a contested milestone to an on-chain stake-backed
// reviewer quorum.
//
// Eligibility:
//   - Sponsor may dispute any MilestoneSubmitted deliverable.
//   - Builder may dispute a MilestoneRevisionRequested deliverable, OR a
//     MilestoneSubmitted deliverable if the sponsor has not responded within
//     ReviewGracePeriod (48h).
func OpenDispute(cur realm, bountyID uint64, milestoneIdx int, reason string) {
	caller := requireLiveCaller(0, cur)
	b := mustGetBounty(bountyID)
	m := mustGetMilestone(b, milestoneIdx)

	if m.dispute != nil {
		panic("dispute already exists for this milestone")
	}
	reason = strings.TrimSpace(reason)
	if reason == "" || len(reason) > MaxRationaleLen {
		panic("dispute reason must be between 1 and 400 bytes")
	}

	switch caller {
	case b.sponsor:
		if m.status != tavernkit.MilestoneSubmitted {
			panic("sponsor can only dispute a submitted milestone")
		}
	case b.builder:
		if m.status == tavernkit.MilestoneRevisionRequested {
			// Allowed immediately if builder disagrees with revision request.
		} else if m.status == tavernkit.MilestoneSubmitted {
			if time.Now().Before(m.submittedAt.Add(ReviewGracePeriod)) {
				panic("sponsor still within 48h review grace period")
			}
		} else {
			panic("milestone is not eligible for builder dispute")
		}
	default:
		panic("only sponsor or assigned builder may open a dispute")
	}

	m.status = tavernkit.MilestoneDisputed
	m.dispute = &dispute{
		openedBy: caller,
		reason:   reason,
		openedAt: time.Now(),
	}
	b.status = tavernkit.StatusDisputed

	chain.Emit(
		"DisputeOpened",
		"id", strconv.FormatUint(bountyID, 10),
		"milestone", strconv.Itoa(milestoneIdx),
		"openedBy", caller.String(),
	)
}

// StakeAndVoteDispute lets an independent third-party reviewer stake native
// ugnot (attached via -send >= b.minReviewerStakeUgnot) into the bounty's
// isolated stake sub-vault (cur.Sub("stake/<id>")) and cast a binding vote.
//
// As soon as the stake-backed quorum reaches a strict majority (>= reviewerQuorum
// votes with no tie), the dispute resolves atomically in the same transaction:
//   - Escrowed milestone payout goes to builder (if approved) or refunds sponsor.
//   - Aligned reviewers reclaim 100% of their stake + an equal split of 50% of
//     dissenting reviewers' slashed stakes.
//   - Builder and reviewer on-chain reputations update immediately.
func StakeAndVoteDispute(
	cur realm,
	bountyID uint64,
	milestoneIdx int,
	approveBuilder bool,
	rationale string,
) bool {
	reviewer := requireDirectUserCall(0, cur)
	b := mustGetBounty(bountyID)
	m := mustGetMilestone(b, milestoneIdx)

	if m.status != tavernkit.MilestoneDisputed || m.dispute == nil || m.dispute.resolved {
		panic("milestone does not have an active dispute")
	}
	if reviewer == b.sponsor || reviewer == b.builder {
		panic("sponsor and builder cannot vote as reviewers on their own dispute")
	}
	for _, existing := range m.dispute.votes {
		if existing.reviewer == reviewer {
			panic("reviewer has already voted on this dispute")
		}
	}
	rationale = strings.TrimSpace(rationale)
	if rationale == "" || len(rationale) > MaxRationaleLen {
		panic("rationale must be between 1 and 400 bytes")
	}

	_, stakeAmt := sweepOriginSendToSub(0, cur, stakeSubpath(bountyID), b.minReviewerStakeUgnot)

	d := m.dispute
	d.votes = append(d.votes, &reviewVote{
		reviewer:       reviewer,
		approveBuilder: approveBuilder,
		stakeUgnot:     stakeAmt,
		rationale:      rationale,
		castAt:         time.Now(),
	})
	d.stakePoolUgnot += stakeAmt
	if approveBuilder {
		d.approveCount++
	} else {
		d.rejectCount++
	}

	chain.Emit(
		"DisputeVoteCast",
		"id", strconv.FormatUint(bountyID, 10),
		"milestone", strconv.Itoa(milestoneIdx),
		"reviewer", reviewer.String(),
		"approveBuilder", strconv.FormatBool(approveBuilder),
		"stakeUgnot", strconv.FormatInt(stakeAmt, 10),
	)

	tally := tavernkit.EvaluateQuorum(d.approveCount, d.rejectCount, b.reviewerQuorum)
	if tally.Decided {
		settleDispute(0, cur, b, m, tally.BuilderWins)
		return true
	}
	return false
}

func settleDispute(_ int, rlm realm, b *bounty, m *milestone, builderWins bool) {
	d := m.dispute
	d.resolved = true
	d.builderWon = builderWins
	d.resolvedAt = time.Now()
	m.settledAt = d.resolvedAt
	statDisputesResolved++

	// 1. Settle escrowed milestone funds from escrow/<id> sub-vault.
	payout := m.payoutUgnot
	b.vaultAccountedUgnot -= payout
	statActiveEscrowUgnot -= payout

	bp := getOrCreateProfile(b.builder)
	if builderWins {
		m.status = tavernkit.MilestoneResolvedBuilder
		b.totalReleasedUgnot += payout
		statTotalPaidUgnot += payout
		bp.approvedMilestones++
		bp.totalEarnedUgnot += payout
		bp.disputesWon++
		sendFromSubVault(0, rlm, escrowSubpath(b.id), b.builder, payout)
	} else {
		m.status = tavernkit.MilestoneResolvedSponsor
		b.totalRefundedUgnot += payout
		bp.disputesLost++
		sendFromSubVault(0, rlm, escrowSubpath(b.id), b.sponsor, payout)
	}

	// 2. Settle reviewer stakes from stake/<id> sub-vault:
	//    - Dissenting reviewers forfeit DissentSlashBps (50%) of their stake
	//      and receive back the remaining 50%.
	//    - Aligned reviewers receive 100% of their stake + an equal share of
	//      the slashed bonus pool (dust goes to first aligned reviewer so zero
	//      ugnot is stranded in the stake sub-vault).
	var winners []*reviewVote
	var losers []*reviewVote
	var slashedPool int64

	for _, v := range d.votes {
		if v.approveBuilder == builderWins {
			winners = append(winners, v)
		} else {
			losers = append(losers, v)
			slash := (v.stakeUgnot * DissentSlashBps) / tavernkit.BasisPointsTotal
			slashedPool += slash
		}
	}

	stakePath := stakeSubpath(b.id)
	for _, lv := range losers {
		slash := (lv.stakeUgnot * DissentSlashBps) / tavernkit.BasisPointsTotal
		returnAmt := lv.stakeUgnot - slash
		if returnAmt > 0 {
			sendFromSubVault(0, rlm, stakePath, lv.reviewer, returnAmt)
		}
		lp := getOrCreateProfile(lv.reviewer)
		lp.reviewsSlashed++
	}

	winnerCount := int64(len(winners))
	var bonusEach, bonusRem int64
	if winnerCount > 0 && slashedPool > 0 {
		bonusEach = slashedPool / winnerCount
		bonusRem = slashedPool % winnerCount
	}
	for i, wv := range winners {
		reward := wv.stakeUgnot + bonusEach
		if i == 0 {
			reward += bonusRem
		}
		sendFromSubVault(0, rlm, stakePath, wv.reviewer, reward)
		wp := getOrCreateProfile(wv.reviewer)
		wp.reviewsAligned++
		if reward > wv.stakeUgnot {
			wp.totalEarnedUgnot += (reward - wv.stakeUgnot)
		}
	}
	d.stakePoolUgnot = 0

	refreshBountyCompletion(b, bp)

	chain.Emit(
		"DisputeResolved",
		"id", strconv.FormatUint(b.id, 10),
		"milestone", strconv.Itoa(m.index),
		"builderWins", strconv.FormatBool(builderWins),
		"slashedPoolUgnot", strconv.FormatInt(slashedPool, 10),
	)
}

// CancelOrReclaimExpired lets the sponsor cancel an unclaimed Open bounty
// immediately, OR reclaim remaining unsettled escrow funds after the bounty's
// deadline has expired (as long as no milestone is currently under active
// quorum dispute).
func CancelOrReclaimExpired(cur realm, bountyID uint64) int64 {
	caller := requireLiveCaller(0, cur)
	b := mustGetBounty(bountyID)

	if caller != b.sponsor {
		panic("only the bounty sponsor can cancel or reclaim")
	}
	if b.status == tavernkit.StatusCompleted || b.status == tavernkit.StatusCancelled || b.status == tavernkit.StatusArchived {
		panic("bounty is already closed")
	}
	if b.status != tavernkit.StatusOpen && !time.Now().After(b.deadline) {
		panic("claimed bounty cannot be cancelled before deadline")
	}
	for _, m := range b.milestones {
		if m.status == tavernkit.MilestoneDisputed {
			panic("cannot reclaim while a milestone dispute is active")
		}
	}

	var refund int64
	for _, m := range b.milestones {
		if !m.status.IsTerminal() {
			refund += m.payoutUgnot
			m.status = tavernkit.MilestoneResolvedSponsor
			m.settledAt = time.Now()
		}
	}

	if b.status == tavernkit.StatusOpen {
		statOpenBounties--
	}
	b.status = tavernkit.StatusCancelled
	b.totalRefundedUgnot += refund
	b.vaultAccountedUgnot -= refund
	statActiveEscrowUgnot -= refund

	if refund > 0 {
		sendFromSubVault(0, cur, escrowSubpath(bountyID), b.sponsor, refund)
	}

	chain.Emit(
		"BountyCancelled",
		"id", strconv.FormatUint(bountyID, 10),
		"sponsor", b.sponsor.String(),
		"refundedUgnot", strconv.FormatInt(refund, 10),
	)
	return refund
}

// ArchiveClosedBounty is a permissionless Gno.land storage-deposit hygiene
// endpoint: once a bounty is Completed or Cancelled and its vaults hold zero
// accounted ugnot, ANY user can prune heavy prose fields (summary, pitch,
// delivery notes, feedback, dispute rationales) into a compact tombstone.
// Per Gno's storage-deposit model, freeing those bytes refunds storage deposit
// to the transaction sender while preserving financial & reputation history.
func ArchiveClosedBounty(cur realm, bountyID uint64) {
	caller := requireLiveCaller(0, cur)
	b := mustGetBounty(bountyID)

	if b.archived {
		panic("bounty is already archived")
	}
	if b.status != tavernkit.StatusCompleted && b.status != tavernkit.StatusCancelled {
		panic("only completed or cancelled bounties can be archived")
	}
	if b.vaultAccountedUgnot != 0 {
		panic("cannot archive while vault balance is non-zero")
	}

	b.summary = ""
	b.builderPitch = ""
	for _, m := range b.milestones {
		m.deliveryNotes = ""
		m.sponsorFeedback = ""
		if m.dispute != nil {
			m.dispute.reason = ""
			for _, v := range m.dispute.votes {
				v.rationale = ""
			}
		}
	}
	b.archived = true
	b.status = tavernkit.StatusArchived
	statArchivedBounties++

	chain.Emit(
		"BountyArchived",
		"id", strconv.FormatUint(bountyID, 10),
		"archiver", caller.String(),
	)
}

func mustGetMilestone(b *bounty, idx int) *milestone {
	if idx < 0 || idx >= len(b.milestones) {
		panic("milestone index out of range")
	}
	return b.milestones[idx]
}

func countUnsettledMilestones(b *bounty) int {
	n := 0
	for _, m := range b.milestones {
		if !m.status.IsTerminal() {
			n++
		}
	}
	return n
}

func countApprovedMilestones(b *bounty) int {
	n := 0
	for _, m := range b.milestones {
		if m.status == tavernkit.MilestoneApproved || m.status == tavernkit.MilestoneResolvedBuilder {
			n++
		}
	}
	return n
}

func refreshBountyCompletion(b *bounty, bp *builderProfile) {
	if countUnsettledMilestones(b) == 0 {
		b.status = tavernkit.StatusCompleted
		statCompletedBounties++
		// Credit completedBounties only if builder successfully won/delivered at
		// least one milestone on the quest.
		if countApprovedMilestones(b) > 0 && bp != nil {
			bp.completedBounties++
		}
		return
	}
	updateActiveBountyStatus(b)
}

func updateActiveBountyStatus(b *bounty) {
	hasDispute := false
	hasSubmitted := false
	for _, m := range b.milestones {
		switch m.status {
		case tavernkit.MilestoneDisputed:
			hasDispute = true
		case tavernkit.MilestoneSubmitted:
			hasSubmitted = true
		}
	}
	switch {
	case hasDispute:
		b.status = tavernkit.StatusDisputed
	case hasSubmitted:
		b.status = tavernkit.StatusInReview
	default:
		b.status = tavernkit.StatusClaimed
	}
}

package tavernboard

import (
	"strconv"
	"strings"

	"gno.land/p/g1uhez53ghm94hh8m4ezxs82240ql87vfppjq0mc/tavernkit"
)

// -----------------------------------------------------------------------------
// Composable Cross-Realm & Off-Chain Read APIs
// Every getter returns pure value copies (never pointers to internal state).
// -----------------------------------------------------------------------------

// GetStats returns aggregate realm-wide escrow and reputation metrics.
func GetStats() BoardStats {
	return BoardStats{
		TotalBounties:     statTotalBounties,
		OpenBounties:      statOpenBounties,
		CompletedBounties: statCompletedBounties,
		DisputesResolved:  statDisputesResolved,
		TotalFundedUgnot:  statTotalFundedUgnot,
		TotalPaidUgnot:    statTotalPaidUgnot,
		ActiveEscrowUgnot: statActiveEscrowUgnot,
		RankedBuilders:    profiles.Size(),
		ArchivedBounties:  statArchivedBounties,
	}
}

// GetReputation returns the deterministic ReputationScore for any address.
// Designed for other Gno.land realms and DAOs to gate proposals, grant tiers,
// or reviewer privileges based on verified TavernBoard delivery history.
func GetReputation(addr address) tavernkit.ReputationScore {
	return tavernkit.ComputeReputation(profileToReputationInput(getProfileReadOnly(addr)))
}

// HasCraftTier reports whether addr has earned at least minTier on TavernBoard.
// Example composable check from another DAO realm:
//
//	if !tavernboard.HasCraftTier(caller, tavernkit.TierArtisan) { panic("artisan rank required") }
func HasCraftTier(addr address, minTier tavernkit.CraftTier) bool {
	return GetReputation(addr).Tier >= minTier
}

// GetProfile returns an immutable snapshot of a participant's complete stats.
func GetProfile(addr address) ProfileSnapshot {
	p := getProfileReadOnly(addr)
	score := tavernkit.ComputeReputation(profileToReputationInput(p))
	if p == nil {
		return ProfileSnapshot{
			Address: addr,
			Score:   score,
		}
	}
	return ProfileSnapshot{
		Address:            p.addr,
		Score:              score,
		CompletedBounties:  p.completedBounties,
		ApprovedMilestones: p.approvedMilestones,
		TotalEarnedUgnot:   p.totalEarnedUgnot,
		ReviewsAligned:     p.reviewsAligned,
		ReviewsSlashed:     p.reviewsSlashed,
		DisputesWon:        p.disputesWon,
		DisputesLost:       p.disputesLost,
		BountiesPosted:     p.bountiesPosted,
		BountiesClaimed:    p.bountiesClaimed,
	}
}

// GetBounty returns an immutable snapshot of a bounty and its live sub-realm
// vault balances. Returns (zero, false) if bountyID does not exist.
func GetBounty(bountyID uint64) (BountySnapshot, bool) {
	b := getBounty(bountyID)
	if b == nil {
		return BountySnapshot{}, false
	}
	escrowAddr := DeriveEscrowAddress(b.id)
	stakeAddr := DeriveStakeAddress(b.id)
	settled := 0
	for _, m := range b.milestones {
		if m.status.IsTerminal() {
			settled++
		}
	}
	return BountySnapshot{
		ID:                    b.id,
		Title:                 b.title,
		Summary:               b.summary,
		Tags:                  b.tags,
		Sponsor:               b.sponsor,
		Builder:               b.builder,
		Status:                b.status,
		TotalFundedUgnot:      b.totalFundedUgnot,
		TotalReleasedUgnot:    b.totalReleasedUgnot,
		TotalRefundedUgnot:    b.totalRefundedUgnot,
		EscrowVaultAddr:       escrowAddr,
		StakeVaultAddr:        stakeAddr,
		EscrowVaultLiveUgnot:  liveVaultUgnot(escrowAddr),
		StakeVaultLiveUgnot:   liveVaultUgnot(stakeAddr),
		CreatedAtUnix:         b.createdAt.Unix(),
		DeadlineUnix:          b.deadline.Unix(),
		MinReviewerStakeUgnot: b.minReviewerStakeUgnot,
		ReviewerQuorum:        b.reviewerQuorum,
		MilestoneCount:        len(b.milestones),
		SettledMilestones:     settled,
		Archived:              b.archived,
	}, true
}

// GetMilestones returns an immutable slice of milestone snapshots for bountyID.
func GetMilestones(bountyID uint64) []MilestoneSnapshot {
	b := getBounty(bountyID)
	if b == nil {
		return nil
	}
	out := make([]MilestoneSnapshot, len(b.milestones))
	for i, m := range b.milestones {
		snap := MilestoneSnapshot{
			Index:           m.index,
			Title:           m.title,
			WeightBps:       m.weightBps,
			PayoutUgnot:     m.payoutUgnot,
			Status:          m.status,
			ProofURL:        m.proofURL,
			DeliveryNotes:   m.deliveryNotes,
			SponsorFeedback: m.sponsorFeedback,
			RevisionCount:   m.revisionCount,
		}
		if m.dispute != nil {
			snap.HasDispute = true
			snap.ApproveVotes = m.dispute.approveCount
			snap.RejectVotes = m.dispute.rejectCount
			snap.DisputeResolved = m.dispute.resolved
			snap.BuilderWon = m.dispute.builderWon
		}
		out[i] = snap
	}
	return out
}

// GetBoardJSON returns a clean, compact JSON snapshot of the board stats and
// most recent bounties (up to limit, max 25) for zero-friction querying via
// `vm/qeval` or `vm/qeval_json` from web explorers, indexers, and AI agents.
func GetBoardJSON(limit int) string {
	if limit <= 0 || limit > 25 {
		limit = 20
	}
	st := GetStats()
	var sb strings.Builder
	sb.WriteString(`{"stats":{`)
	sb.WriteString(`"totalBounties":` + strconv.FormatInt(st.TotalBounties, 10))
	sb.WriteString(`,"openBounties":` + strconv.FormatInt(st.OpenBounties, 10))
	sb.WriteString(`,"completedBounties":` + strconv.FormatInt(st.CompletedBounties, 10))
	sb.WriteString(`,"disputesResolved":` + strconv.FormatInt(st.DisputesResolved, 10))
	sb.WriteString(`,"totalFundedUgnot":` + strconv.FormatInt(st.TotalFundedUgnot, 10))
	sb.WriteString(`,"totalPaidUgnot":` + strconv.FormatInt(st.TotalPaidUgnot, 10))
	sb.WriteString(`,"activeEscrowUgnot":` + strconv.FormatInt(st.ActiveEscrowUgnot, 10))
	sb.WriteString(`,"rankedBuilders":` + strconv.Itoa(st.RankedBuilders))
	sb.WriteString(`,"archivedBounties":` + strconv.FormatInt(st.ArchivedBounties, 10))
	sb.WriteString(`},"bounties":[`)

	count := 0
	bounties.ReverseIterate("", "", func(_ string, val any) bool {
		if count >= limit {
			return true
		}
		b := val.(*bounty)
		if count > 0 {
			sb.WriteString(",")
		}
		writeBountyJSON(&sb, b)
		count++
		return false
	})

	sb.WriteString(`]}`)
	return sb.String()
}

func writeBountyJSON(sb *strings.Builder, b *bounty) {
	escrowAddr := DeriveEscrowAddress(b.id)
	settled := 0
	for _, m := range b.milestones {
		if m.status.IsTerminal() {
			settled++
		}
	}
	sb.WriteString(`{"id":` + strconv.FormatUint(b.id, 10))
	sb.WriteString(`,"title":` + jsonQuote(b.title))
	sb.WriteString(`,"tags":` + jsonQuote(b.tags))
	sb.WriteString(`,"sponsor":` + jsonQuote(b.sponsor.String()))
	sb.WriteString(`,"builder":` + jsonQuote(b.builder.String()))
	sb.WriteString(`,"status":` + jsonQuote(b.status.String()))
	sb.WriteString(`,"fundedUgnot":` + strconv.FormatInt(b.totalFundedUgnot, 10))
	sb.WriteString(`,"releasedUgnot":` + strconv.FormatInt(b.totalReleasedUgnot, 10))
	sb.WriteString(`,"escrowVault":` + jsonQuote(escrowAddr.String()))
	sb.WriteString(`,"escrowLiveUgnot":` + strconv.FormatInt(liveVaultUgnot(escrowAddr), 10))
	sb.WriteString(`,"milestones":` + strconv.Itoa(len(b.milestones)))
	sb.WriteString(`,"settledMilestones":` + strconv.Itoa(settled))
	sb.WriteString(`,"deadlineUnix":` + strconv.FormatInt(b.deadline.Unix(), 10))
	sb.WriteString(`,"archived":` + strconv.FormatBool(b.archived))
	sb.WriteString(`}`)
}

func jsonQuote(s string) string {
	var sb strings.Builder
	sb.WriteByte('"')
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch c {
		case '"':
			sb.WriteString(`\"`)
		case '\\':
			sb.WriteString(`\\`)
		case '\n':
			sb.WriteString(`\n`)
		case '\r':
			sb.WriteString(`\r`)
		case '\t':
			sb.WriteString(`\t`)
		default:
			if c < 0x20 {
				sb.WriteString(" ")
			} else {
				sb.WriteByte(c)
			}
		}
	}
	sb.WriteByte('"')
	return sb.String()
}

package tavernboard

import (
	"sort"
	"strconv"
	"strings"

	"gno.land/p/moul/mdtable/v0"
	"gno.land/p/moul/txlink/v0"
	"gno.land/p/nt/avl/pager/v0"
	"gno.land/p/nt/avl/rotree/v0"
	"gno.land/p/nt/markdown/sanitize/v0"
	"gno.land/p/nt/mdalert/v0"
	"gno.land/p/nt/mux/v0"
	"gno.land/p/nt/ufmt/v0"
	"gno.land/p/g1uhez53ghm94hh8m4ezxs82240ql87vfppjq0mc/tavernkit"
	"gno.land/r/sys/users"
)

var router *mux.Router

func initRouter() {
	router = mux.NewRouter()
	router.HandleFunc("", renderHome)
	router.HandleFunc("bounty/{id}", renderBountyDetail)
	router.HandleFunc("guild", renderGuildHall)
	router.HandleFunc("builder/{addr}", renderBuilderProfile)
	router.HandleFunc("guide", renderGuide)
	router.NotFoundHandler = renderNotFound
}

// Render serves TavernBoard's full multi-route Markdown & SVG interface
// natively inside gnoweb without requiring any external backend server.
func Render(path string) string {
	return router.Render(path)
}

func realmRoutePrefix() string {
	idx := strings.Index(realmPkgPath, "/r/")
	if idx >= 0 {
		return realmPkgPath[idx:]
	}
	return "/r/tavernboard/tavernboard"
}

func navBar(active string) string {
	base := realmRoutePrefix()
	postURL := txlink.NewLink("PostBounty").SetSend("1000000ugnot").URL()

	items := []struct {
		key   string
		label string
		href  string
	}{
		{"home", "Quest Board", base},
		{"open", "Open Quests", base + ":?status=open"},
		{"review", "In Review", base + ":?status=review"},
		{"disputed", "Disputed", base + ":?status=disputed"},
		{"guild", "Guild Hall", base + ":guild"},
		{"guide", "Architecture & Guide", base + ":guide"},
	}

	parts := make([]string, 0, len(items)+1)
	for _, it := range items {
		if it.key == active {
			parts = append(parts, "**"+it.label+"**")
		} else {
			parts = append(parts, "["+it.label+"]("+it.href+")")
		}
	}
	parts = append(parts, "[+ Post a Quest]("+postURL+")")
	return strings.Join(parts, " · ")
}

func resolveDisplayName(addr address) string {
	if addr == "" {
		return "_Unclaimed_"
	}
	if u := users.ResolveAddress(addr); !u.IsDeleted() {
		return "@" + u.Name()
	}
	return tavernkit.ShortAddr(addr)
}

func builderLink(addr address) string {
	if addr == "" {
		return "_Unclaimed_"
	}
	label := sanitize.InlineText(resolveDisplayName(addr))
	return "[" + label + "](" + realmRoutePrefix() + ":builder/" + sanitize.URL(addr.String()) + ")"
}

func safeCell(raw string) string {
	flat := strings.ReplaceAll(raw, "\r", " ")
	flat = strings.ReplaceAll(flat, "\n", " ")
	flat = strings.ReplaceAll(flat, "\t", " ")
	return sanitize.InlineText(strings.TrimSpace(flat))
}

func renderHome(res *mux.ResponseWriter, req *mux.Request) {
	statusFilter := strings.ToLower(strings.TrimSpace(req.Query.Get("status")))
	activeNav := "home"
	if statusFilter == "open" || statusFilter == "review" || statusFilter == "disputed" {
		activeNav = statusFilter
	}

	st := GetStats()
	base := realmRoutePrefix()

	var sb strings.Builder
	sb.WriteString("# TavernBoard — On-Chain Quest Escrow & Guild Reputation\n\n")
	sb.WriteString(navBar(activeNav) + "\n\n")
	sb.WriteString("Pure on-chain micro-bounties powered by **Gno.land v1.8 Sub-Realm Escrow Vaults** (`cur.Sub(\"escrow/<id>\")`), **Stake-Backed Reviewer Quorums**, **On-Chain SVG Guild Crests**, and **Composable Reputation**.\n\n")

	// Protocol summary table.
	statsTbl := mdtable.Table{
		Headers: []string{"Total Quests", "Open", "Active Escrow TVL", "Total Paid Out", "Disputes Settled", "Ranked Guild Members"},
	}
	statsTbl.Append([]string{
		strconv.FormatInt(st.TotalBounties, 10),
		strconv.FormatInt(st.OpenBounties, 10),
		"**" + tavernkit.FormatGNOT(st.ActiveEscrowUgnot) + "**",
		tavernkit.FormatGNOT(st.TotalPaidUgnot),
		strconv.FormatInt(st.DisputesResolved, 10),
		strconv.Itoa(st.RankedBuilders),
	})
	sb.WriteString(statsTbl.String() + "\n")

	if bounties.Size() == 0 {
		postURL := txlink.NewLink("PostBounty").SetSend("1000000ugnot").URL()
		sb.WriteString(mdalert.Tip(
			"The Quest Board Awaits Its First Contract",
			"Post the first funded bounty directly from gnoweb: [Post a 1 GNOT Quest]("+postURL+"). Every quest mints its own isolated sub-realm escrow vault.",
		) + "\n")
		res.Write(sb.String())
		return
	}

	heading := "## Active & Recent Quests"
	if statusFilter != "" {
		heading = "## Quests — Filter: `" + sanitize.InlineText(statusFilter) + "`"
	}
	sb.WriteString(heading + "\n\n")

	tbl := mdtable.Table{
		Headers: []string{"ID", "Quest", "Status", "Reward", "Milestones", "Sponsor", "Builder", "Deadline"},
	}

	if statusFilter == "" {
		// O(log n) paginated view over all bounties (newest first).
		ro := rotree.Wrap(bounties, nil)
		pg := pager.NewPager(ro, 10, true)
		page, err := pg.GetPageByPath(req.RawPath)
		if err != nil {
			page = pg.GetPage(1)
		}
		for _, item := range page.Items {
			b := item.Value.(*bounty)
			tbl.Append(bountyTableRow(base, b))
		}
		sb.WriteString(tbl.String() + "\n")
		if picker := page.Picker(req.RawPath); picker != "" {
			sb.WriteString("Pages: " + picker + "\n\n")
		}
	} else {
		matched := 0
		bounties.ReverseIterate("", "", func(_ string, val any) bool {
			b := val.(*bounty)
			if matchesStatusFilter(b.status, statusFilter) {
				tbl.Append(bountyTableRow(base, b))
				matched++
				if matched >= 25 {
					return true
				}
			}
			return false
		})
		if matched == 0 {
			sb.WriteString(mdalert.Info("No Matching Quests", "No quests match this filter right now. [View all quests]("+base+").") + "\n")
		} else {
			sb.WriteString(tbl.String() + "\n")
		}
	}

	sb.WriteString(mdalert.Note(
		"Composable Reputation API",
		"External Gno realms can import `tavernboard` and gate permissions via `tavernboard.HasCraftTier(caller, tavernkit.TierArtisan)` or read live JSON state via `vm/qeval` on `GetBoardJSON(20)`.",
	))

	res.Write(sb.String())
}

func matchesStatusFilter(st tavernkit.Status, filter string) bool {
	switch filter {
	case "open":
		return st == tavernkit.StatusOpen
	case "claimed":
		return st == tavernkit.StatusClaimed
	case "review":
		return st == tavernkit.StatusInReview
	case "disputed":
		return st == tavernkit.StatusDisputed
	case "completed":
		return st == tavernkit.StatusCompleted
	default:
		return true
	}
}

func bountyTableRow(base string, b *bounty) []string {
	idStr := strconv.FormatUint(b.id, 10)
	titleLink := "[" + safeCell(b.title) + "](" + base + ":bounty/" + idStr + ")"
	settled := 0
	for _, m := range b.milestones {
		if m.status.IsTerminal() {
			settled++
		}
	}
	return []string{
		"#" + idStr,
		titleLink,
		"`" + b.status.String() + "`",
		"**" + tavernkit.FormatGNOT(b.totalFundedUgnot) + "**",
		strconv.Itoa(settled) + "/" + strconv.Itoa(len(b.milestones)),
		builderLink(b.sponsor),
		builderLink(b.builder),
		b.deadline.Format("2006-01-02"),
	}
}

func renderBountyDetail(res *mux.ResponseWriter, req *mux.Request) {
	idRaw := req.GetVar("id")
	id, err := strconv.ParseUint(idRaw, 10, 64)
	if err != nil || id == 0 {
		renderNotFound(res, req)
		return
	}
	b := getBounty(id)
	if b == nil {
		renderNotFound(res, req)
		return
	}

	idStr := strconv.FormatUint(b.id, 10)
	escrowAddr := DeriveEscrowAddress(b.id)
	stakeAddr := DeriveStakeAddress(b.id)
	liveEscrow := liveVaultUgnot(escrowAddr)
	liveStake := liveVaultUgnot(stakeAddr)

	settled := 0
	for _, m := range b.milestones {
		if m.status.IsTerminal() {
			settled++
		}
	}

	var sb strings.Builder
	sb.WriteString("# Quest #" + idStr + ": " + sanitize.InlineText(b.title) + "\n\n")
	sb.WriteString(navBar("") + "\n\n")

	// Live on-chain SVG Escrow Vault Card.
	sb.WriteString(tavernkit.RenderEscrowCardSVG(
		idStr,
		b.status,
		b.totalFundedUgnot,
		b.totalReleasedUgnot,
		settled,
		len(b.milestones),
	) + "\n\n")

	if b.archived {
		sb.WriteString(mdalert.Info(
			"Archived Tombstone (Storage Deposit Reclaimed)",
			"Heavy prose fields for this closed quest were pruned to refund on-chain GnoVM storage deposits while preserving financial settlement and reputation history.",
		) + "\n")
	} else {
		sb.WriteString("## Quest Brief\n\n")
		sb.WriteString(sanitize.Block(b.summary) + "\n\n")
	}

	// Vault & metadata table.
	meta := mdtable.Table{
		Headers: []string{"Field", "Value"},
	}
	meta.Append([]string{"Status", "`" + b.status.String() + "`"})
	meta.Append([]string{"Sponsor", builderLink(b.sponsor)})
	meta.Append([]string{"Assigned Builder", builderLink(b.builder)})
	if b.tags != "" {
		meta.Append([]string{"Tags", "`" + safeCell(b.tags) + "`"})
	}
	meta.Append([]string{"Escrow Sub-Vault (`escrow/" + idStr + "`)", "`" + escrowAddr.String() + "` (live: **" + tavernkit.FormatGNOT(liveEscrow) + "**)"})
	meta.Append([]string{"Stake Sub-Vault (`stake/" + idStr + "`)", "`" + stakeAddr.String() + "` (live: " + tavernkit.FormatGNOT(liveStake) + ")"})
	meta.Append([]string{"Dispute Quorum", strconv.Itoa(b.reviewerQuorum) + " reviewers · min stake " + tavernkit.FormatGNOT(b.minReviewerStakeUgnot)})
	meta.Append([]string{"Deadline (UTC)", b.deadline.Format("2006-01-02 15:04 UTC")})
	sb.WriteString(meta.String() + "\n")

	if b.builderPitch != "" {
		sb.WriteString("**Builder Pitch:**\n")
		sb.WriteString(sanitize.Blockquote(b.builderPitch) + "\n\n")
	}

	// Context-aware one-click gnoweb txlink action bar.
	sb.WriteString("## Quick Actions\n\n")
	actions := []string{}
	if b.status == tavernkit.StatusOpen {
		actions = append(actions, "[Claim Quest]("+txlink.NewLink("ClaimBounty").AddArgs("bountyID", idStr).URL()+")")
		actions = append(actions, "[Cancel & Refund]("+txlink.NewLink("CancelOrReclaimExpired").AddArgs("bountyID", idStr).URL()+")")
	}
	if b.status == tavernkit.StatusOpen || b.status == tavernkit.StatusClaimed || b.status == tavernkit.StatusInReview {
		actions = append(actions, "[Top Up +1 GNOT]("+txlink.NewLink("TopUpBounty").AddArgs("bountyID", idStr).SetSend("1000000ugnot").URL()+")")
		if liveEscrow > b.vaultAccountedUgnot {
			actions = append(actions, "[Sync Direct Vault Deposit]("+txlink.NewLink("SyncBountyVault").AddArgs("bountyID", idStr).URL()+")")
		}
	}
	if b.status == tavernkit.StatusClaimed {
		actions = append(actions, "[Release Claim]("+txlink.NewLink("ReleaseClaim").AddArgs("bountyID", idStr).URL()+")")
	}
	if (b.status == tavernkit.StatusCompleted || b.status == tavernkit.StatusCancelled) && !b.archived && b.vaultAccountedUgnot == 0 {
		actions = append(actions, "[Archive & Reclaim Storage Deposit]("+txlink.NewLink("ArchiveClosedBounty").AddArgs("bountyID", idStr).URL()+")")
	}
	if len(actions) > 0 {
		sb.WriteString(strings.Join(actions, " · ") + "\n\n")
	}

	// Milestones table.
	sb.WriteString("## Milestones\n\n")
	mtbl := mdtable.Table{
		Headers: []string{"#", "Deliverable", "Weight", "Payout", "Status", "Proof", "Action"},
	}
	for _, m := range b.milestones {
		idxStr := strconv.Itoa(m.index)
		proofCell := "—"
		if m.proofURL != "" {
			safeHref := sanitize.URL(m.proofURL)
			if safeHref != "" {
				proofCell = "[View Proof](" + safeHref + ")"
			}
		}
		actCell := "—"
		switch m.status {
		case tavernkit.MilestonePending, tavernkit.MilestoneRevisionRequested:
			if b.builder != "" && b.status != tavernkit.StatusCancelled && b.status != tavernkit.StatusArchived {
				submitLink := txlink.NewLink("SubmitMilestone").AddArgs("bountyID", idStr, "milestoneIdx", idxStr).URL()
				actCell = "[Submit Proof](" + submitLink + ")"
				if m.status == tavernkit.MilestoneRevisionRequested {
					dispLink := txlink.NewLink("OpenDispute").AddArgs("bountyID", idStr, "milestoneIdx", idxStr).URL()
					actCell += " · [Dispute](" + dispLink + ")"
				}
			}
		case tavernkit.MilestoneSubmitted:
			approveLink := txlink.NewLink("ApproveMilestone").AddArgs("bountyID", idStr, "milestoneIdx", idxStr).URL()
			revLink := txlink.NewLink("RequestRevision").AddArgs("bountyID", idStr, "milestoneIdx", idxStr).URL()
			dispLink := txlink.NewLink("OpenDispute").AddArgs("bountyID", idStr, "milestoneIdx", idxStr).URL()
			actCell = "[Approve & Pay](" + approveLink + ") · [Revise](" + revLink + ") · [Dispute](" + dispLink + ")"
		case tavernkit.MilestoneDisputed:
			stakeStr := strconv.FormatInt(b.minReviewerStakeUgnot, 10) + nativeDenom
			voteApprove := txlink.NewLink("StakeAndVoteDispute").AddArgs("bountyID", idStr, "milestoneIdx", idxStr, "approveBuilder", "true").SetSend(stakeStr).URL()
			voteReject := txlink.NewLink("StakeAndVoteDispute").AddArgs("bountyID", idStr, "milestoneIdx", idxStr, "approveBuilder", "false").SetSend(stakeStr).URL()
			actCell = "[Stake & Vote Builder](" + voteApprove + ") · [Stake & Vote Sponsor](" + voteReject + ")"
		}
		mtbl.Append([]string{
			idxStr,
			safeCell(m.title),
			tavernkit.FormatBpsPercent(m.weightBps),
			"**" + tavernkit.FormatGNOT(m.payoutUgnot) + "**",
			"`" + m.status.String() + "`",
			proofCell,
			actCell,
		})
	}
	sb.WriteString(mtbl.String() + "\n")

	// Render delivery notes, sponsor feedback, and active/resolved disputes.
	for _, m := range b.milestones {
		if m.deliveryNotes != "" || m.sponsorFeedback != "" || m.dispute != nil {
			sb.WriteString(ufmt.Sprintf("### Milestone #%d — %s\n\n", m.index, sanitize.InlineText(m.title)))
			if m.deliveryNotes != "" {
				sb.WriteString("**Delivery Notes:**\n" + sanitize.Block(m.deliveryNotes) + "\n\n")
			}
			if m.sponsorFeedback != "" {
				sb.WriteString("**Sponsor Feedback:**\n" + sanitize.Blockquote(m.sponsorFeedback) + "\n\n")
			}
			if m.dispute != nil {
				renderDisputeSection(&sb, b, m)
			}
		}
	}

	res.Write(sb.String())
}

func renderDisputeSection(sb *strings.Builder, b *bounty, m *milestone) {
	d := m.dispute
	statusMsg := ufmt.Sprintf("Quorum progress: %d approve / %d reject (quorum: %d, stake pool: %s)",
		d.approveCount, d.rejectCount, b.reviewerQuorum, tavernkit.FormatGNOT(d.stakePoolUgnot))
	if d.resolved {
		winner := "Sponsor (Refunded)"
		if d.builderWon {
			winner = "Builder (Paid)"
		}
		sb.WriteString(mdalert.Success("Dispute Resolved — "+winner, statusMsg) + "\n")
	} else {
		sb.WriteString(mdalert.Warning("Active Stake-Backed Reviewer Quorum", statusMsg) + "\n")
	}
	if d.reason != "" {
		sb.WriteString("**Dispute Reason** (opened by " + builderLink(d.openedBy) + "):\n" + sanitize.Blockquote(d.reason) + "\n\n")
	}
	if len(d.votes) > 0 {
		vtbl := mdtable.Table{
			Headers: []string{"Reviewer", "Vote", "Stake", "Rationale"},
		}
		for _, v := range d.votes {
			voteLabel := "Reject (Sponsor)"
			if v.approveBuilder {
				voteLabel = "Approve (Builder)"
			}
			rat := "_(archived)_"
			if v.rationale != "" {
				rat = safeCell(v.rationale)
			}
			vtbl.Append([]string{
				builderLink(v.reviewer),
				voteLabel,
				tavernkit.FormatGNOT(v.stakeUgnot),
				rat,
			})
		}
		sb.WriteString(vtbl.String() + "\n")
	}
}

type rankedEntry struct {
	profile *builderProfile
	score   tavernkit.ReputationScore
}

type rankedList []rankedEntry

func (r rankedList) Len() int { return len(r) }

func (r rankedList) Less(i, j int) bool {
	if r[i].score.XP != r[j].score.XP {
		return r[i].score.XP > r[j].score.XP
	}
	return r[i].profile.addr < r[j].profile.addr
}

func (r rankedList) Swap(i, j int) {
	r[i], r[j] = r[j], r[i]
}

func renderGuildHall(res *mux.ResponseWriter, _ *mux.Request) {
	var sb strings.Builder
	sb.WriteString("# TavernBoard — Guild Hall & Reputation Leaderboard\n\n")
	sb.WriteString(navBar("guild") + "\n\n")
	sb.WriteString("Reputation XP, Craft Tiers, and Reliability are computed deterministically on-chain from settled deliveries and aligned quorum reviews — never self-reported.\n\n")

	if profiles.Size() == 0 {
		sb.WriteString(mdalert.Info("Guild Hall Is Quiet", "No builders or sponsors have recorded activity yet.") + "\n")
		res.Write(sb.String())
		return
	}

	entries := make(rankedList, 0, profiles.Size())
	profiles.Iterate("", "", func(_ string, val any) bool {
		p := val.(*builderProfile)
		sc := tavernkit.ComputeReputation(profileToReputationInput(p))
		entries = append(entries, rankedEntry{profile: p, score: sc})
		return false
	})

	sort.Sort(entries)

	tbl := mdtable.Table{
		Headers: []string{"Rank", "Member", "Craft Tier", "XP", "Quests Done", "Earned", "Aligned Reviews", "Reliability"},
	}
	limit := len(entries)
	if limit > 30 {
		limit = 30
	}
	for i := 0; i < limit; i++ {
		e := entries[i]
		tbl.Append([]string{
			"#" + strconv.Itoa(i+1),
			builderLink(e.profile.addr),
			"**" + e.score.Tier.String() + "**",
			strconv.FormatInt(e.score.XP, 10),
			strconv.FormatInt(e.profile.completedBounties, 10),
			tavernkit.FormatGNOT(e.profile.totalEarnedUgnot),
			strconv.FormatInt(e.profile.reviewsAligned, 10),
			tavernkit.FormatBpsPercent(e.score.ReliabilityBps),
		})
	}
	sb.WriteString(tbl.String() + "\n")
	res.Write(sb.String())
}

func renderBuilderProfile(res *mux.ResponseWriter, req *mux.Request) {
	rawAddr := strings.TrimSpace(req.GetVar("addr"))
	addr := address(rawAddr)
	if !addr.IsValid() {
		renderNotFound(res, req)
		return
	}

	snap := GetProfile(addr)
	displayName := resolveDisplayName(addr)

	var sb strings.Builder
	sb.WriteString("# Guild Member: " + sanitize.InlineText(displayName) + "\n\n")
	sb.WriteString(navBar("guild") + "\n\n")

	// Render pure on-chain SVG Guild Crest card!
	sb.WriteString(tavernkit.RenderGuildCrestSVG(
		displayName,
		snap.Score,
		snap.CompletedBounties,
		snap.TotalEarnedUgnot,
	) + "\n\n")

	tbl := mdtable.Table{
		Headers: []string{"Metric", "Value"},
	}
	tbl.Append([]string{"Address", "`" + sanitize.InlineText(addr.String()) + "`"})
	tbl.Append([]string{"Craft Tier", "**" + snap.Score.Tier.String() + "** (" + strconv.FormatInt(snap.Score.XP, 10) + " XP)"})
	tbl.Append([]string{"Reliability", tavernkit.FormatBpsPercent(snap.Score.ReliabilityBps)})
	tbl.Append([]string{"Completed Quests", strconv.FormatInt(snap.CompletedBounties, 10)})
	tbl.Append([]string{"Approved Milestones", strconv.FormatInt(snap.ApprovedMilestones, 10)})
	tbl.Append([]string{"Total Earned", "**" + tavernkit.FormatGNOT(snap.TotalEarnedUgnot) + "**"})
	tbl.Append([]string{"Quorum Reviews (Aligned / Slashed)", strconv.FormatInt(snap.ReviewsAligned, 10) + " / " + strconv.FormatInt(snap.ReviewsSlashed, 10)})
	tbl.Append([]string{"Disputes (Won / Lost)", strconv.FormatInt(snap.DisputesWon, 10) + " / " + strconv.FormatInt(snap.DisputesLost, 10)})
	tbl.Append([]string{"Quests Posted / Claimed", strconv.FormatInt(snap.BountiesPosted, 10) + " / " + strconv.FormatInt(snap.BountiesClaimed, 10)})
	sb.WriteString(tbl.String() + "\n")

	// Show quests involving this address.
	base := realmRoutePrefix()
	qtbl := mdtable.Table{
		Headers: []string{"ID", "Role", "Quest", "Status", "Reward"},
	}
	found := 0
	bounties.ReverseIterate("", "", func(_ string, val any) bool {
		b := val.(*bounty)
		role := ""
		if b.sponsor == addr {
			role = "Sponsor"
		} else if b.builder == addr {
			role = "Builder"
		}
		if role != "" {
			idStr := strconv.FormatUint(b.id, 10)
			qtbl.Append([]string{
				"#" + idStr,
				role,
				"[" + safeCell(b.title) + "](" + base + ":bounty/" + idStr + ")",
				"`" + b.status.String() + "`",
				tavernkit.FormatGNOT(b.totalFundedUgnot),
			})
			found++
			if found >= 15 {
				return true
			}
		}
		return false
	})
	if found > 0 {
		sb.WriteString("## Quest History\n\n" + qtbl.String() + "\n")
	}

	res.Write(sb.String())
}

func renderGuide(res *mux.ResponseWriter, _ *mux.Request) {
	var sb strings.Builder
	sb.WriteString("# TavernBoard — Sub-Realm Escrow & Quorum Architecture\n\n")
	sb.WriteString(navBar("guide") + "\n\n")

	sb.WriteString("## 1. Isolated Sub-Realm Escrow Vaults (`cur.Sub`)\n\n")
	sb.WriteString("Every quest mints two dedicated Gno.land v1.8 sub-realm addresses:\n\n")
	sb.WriteString("- **`cur.Sub(\"escrow/<id>\")`** — holds that quest's locked `ugnot` reward pool.\n")
	sb.WriteString("- **`cur.Sub(\"stake/<id>\")`** — holds reviewer stakes during an active milestone dispute.\n\n")
	sb.WriteString("Payouts execute through `banker.NewBanker(banker.BankerTypeRealmSend, cur.Sub(\"escrow/<id>\"))`, so the GnoVM banker itself guarantees Quest #1 can never spend a single `ugnot` belonging to Quest #2.\n\n")

	sb.WriteString("## 2. Composable DAO & Cross-Realm Co-Funding\n\n")
	sb.WriteString("Any external DAO realm or user can compute `tavernboard.DeriveEscrowAddress(id)` (via `chain.DerivePkgSubAddr`), transfer `ugnot` directly to that sub-address, and call `SyncBountyVault(cross(cur), id)` to co-fund remaining milestones proportionally.\n\n")

	sb.WriteString("## 3. Stake-Backed Reviewer Quorum\n\n")
	sb.WriteString("- Independent reviewers (neither sponsor nor builder) stake `>= minReviewerStakeUgnot` into `stake/<id>`.\n")
	sb.WriteString("- Once strict majority quorum is met, settlement executes atomically: the milestone pays out or refunds, aligned reviewers reclaim 100% of their stake plus an equal share of the 50% slashed dissenting stakes, and reputation updates on-chain.\n\n")

	sb.WriteString("## 4. Storage-Deposit Hygiene\n\n")
	sb.WriteString("Once a quest closes and its vaults drain to `0 ugnot`, anyone can call `ArchiveClosedBounty(cross(cur), id)` to prune heavy prose strings into a compact tombstone and reclaim Gno.land storage deposits.\n")

	res.Write(sb.String())
}

func renderNotFound(res *mux.ResponseWriter, req *mux.Request) {
	var sb strings.Builder
	sb.WriteString("# TavernBoard — Route Not Found\n\n")
	sb.WriteString(navBar("") + "\n\n")
	sb.WriteString(mdalert.Caution(
		"Unknown Route",
		"No TavernBoard view matched `"+sanitize.InlineText(req.Path)+"`. Return to the [Quest Board]("+realmRoutePrefix()+").",
	))
