package tavernboard

import (
	"strconv"
	"time"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/seqid/v0"
	"gno.land/p/g1uhez53ghm94hh8m4ezxs82240ql87vfppjq0mc/tavernkit"
)

const (
	// Native coin denomination used across all escrows and reviewer stakes.
	nativeDenom = "ugnot"

	// Minimum bounty funding: 0.1 GNOT (100,000 ugnot) keeps testnet demos
	// accessible while preventing dust spam.
	MinBountyUgnot int64 = 100_000

	// Default minimum stake required per dispute reviewer: 0.05 GNOT.
	DefaultMinReviewerStakeUgnot int64 = 50_000

	// Absolute floor for per-bounty reviewer stake.
	FloorReviewerStakeUgnot int64 = 10_000

	// Default reviewer quorum size (3 independent staked reviewers).
	DefaultReviewerQuorum = 3

	// Maximum reviewer quorum size to keep dispute resolution bounded.
	MaxReviewerQuorum = 7

	// Slash share taken from dissenting reviewers' stakes (50% = 5000 bps).
	DissentSlashBps int64 = 5000

	// Maximum sponsor revision requests before builder can force quorum review.
	MaxRevisionRequests = 3

	// Review grace period: if a sponsor ignores a submitted milestone for 48h,
	// the builder may escalate directly to staked reviewer quorum.
	ReviewGracePeriod = 48 * time.Hour

	// Bounds on user strings to protect on-chain storage and gas predictability.
	MaxTitleLen     = 120
	MaxSummaryLen   = 1200
	MaxTagsLen      = 120
	MaxPitchLen     = 400
	MaxProofURLLen  = 256
	MaxNotesLen     = 800
	MaxFeedbackLen  = 500
	MaxRationaleLen = 400
	MaxDeadlineDays = 365
)

var (
	// Realm identity captured once at init(cur realm).
	realmPkgPath string
	realmAddr    address
	deployerAddr address

	// Primary persistent stores (all unexported; never returned as pointers).
	nextBountyID seqid.ID
	bounties     *avl.Tree // key: seqid.ID(id).String() -> *bounty
	profiles     *avl.Tree // key: addr.String()         -> *builderProfile

	// Aggregate counters maintained incrementally in O(1).
	statTotalBounties     int64
	statOpenBounties      int64
	statCompletedBounties int64
	statDisputesResolved  int64
	statTotalFundedUgnot  int64
	statTotalPaidUgnot    int64
	statActiveEscrowUgnot int64
	statArchivedBounties  int64
)

func init(cur realm) {
	realmPkgPath = cur.PkgPath()
	realmAddr = cur.Address()
	if cur.Previous() != nil {
		deployerAddr = cur.Previous().Address()
	}
	bounties = avl.NewTree()
	profiles = avl.NewTree()
	initRouter()
}

func bountyKey(id uint64) string {
	return seqid.ID(id).String()
}

func getBounty(id uint64) *bounty {
	if id == 0 {
		return nil
	}
	v := bounties.Get(bountyKey(id))
	if v == nil {
		return nil
	}
	return v.(*bounty)
}

func mustGetBounty(id uint64) *bounty {
	b := getBounty(id)
	if b == nil {
		panic("bounty not found: #" + strconv.FormatUint(id, 10))
	}
	return b
}

func getOrCreateProfile(addr address) *builderProfile {
	key := addr.String()
	if v := profiles.Get(key); v != nil {
		return v.(*builderProfile)
	}
	p := &builderProfile{addr: addr}
	profiles.Set(key, p)
	return p
}

func getProfileReadOnly(addr address) *builderProfile {
	if v := profiles.Get(addr.String()); v != nil {
		return v.(*builderProfile)
	}
	return nil
}

func profileToReputationInput(p *builderProfile) tavernkit.ReputationInput {
	if p == nil {
		return tavernkit.ReputationInput{}
	}
	return tavernkit.ReputationInput{
		CompletedBounties:  p.completedBounties,
		ApprovedMilestones: p.approvedMilestones,
		TotalEarnedUgnot:   p.totalEarnedUgnot,
		ReviewsAligned:     p.reviewsAligned,
		ReviewsSlashed:     p.reviewsSlashed,
		DisputesWon:        p.disputesWon,
		DisputesLost:       p.disputesLost,
	}
}

func requireLiveCaller(_ int, rlm realm) address {
	if !rlm.IsCurrent() {
		panic("spoofed realm handle")
	}
	return rlm.Previous().Address()
}

func requireDirectUserCall(_ int, rlm realm) address {
	if !rlm.IsCurrent() {
		panic("spoofed realm handle")
	}
	if !rlm.Previous().IsUserCall() {
		panic("direct user call (maketx call) required for coin transfers")
	}
	return rlm.Previous().Address()
}

package sandiwara

import (
	"chain/runtime"
)

// copyBytes returns an independent copy of b. Every byte slice that enters
// realm state goes through here, so a caller cannot mutate stored state by
// keeping a reference to the slice they passed in.
func copyBytes(b []byte) []byte {
	if b == nil {
		return nil
	}
	out := make([]byte, len(b))
	copy(out, b)
	return out
}

// bytesEqual reports whether a and b hold the same bytes.
func bytesEqual(a, b []byte) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

// shortAddr renders an address as its first 10 characters, which is enough to
// tell seats apart on the board without printing 40 characters per seat.
func shortAddr(a address) string {
	s := a.String()
	if len(s) <= 10 {
		return s
	}
	return s[:10]
}

// shortHex renders a hash as its first 8 bytes in hex.
func shortHex(b []byte) string {
	const hexdigits = "0123456789abcdef"
	if len(b) > 8 {
		b = b[:8]
	}
	out := make([]byte, 0, len(b)*2)
	for _, c := range b {
		out = append(out, hexdigits[c>>4], hexdigits[c&0x0f])
	}
	return string(out)
}

// fullHex renders a hash as lowercase hex.
func fullHex(b []byte) string {
	const hexdigits = "0123456789abcdef"
	out := make([]byte, 0, len(b)*2)
	for _, c := range b {
		out = append(out, hexdigits[c>>4], hexdigits[c&0x0f])
	}
	return string(out)
}

// chainHeight is the current block height, wrapped so render code does not
// import chain/runtime directly in several places.
func chainHeight() int64 {
	return runtime.ChainHeight()
}

// seatsFilled returns how many seats are taken.
func seatsFilled(g *Game) int {
	return len(g.Seats)
}

// livingCount returns how many players are still alive.
func livingCount(g *Game) int {
	n := 0
	for i := range g.Seats {
		if g.Seats[i].Alive {
			n++
		}
	}
	return n
}

// submittedNight returns how many living players have committed a night action.
func submittedNight(g *Game) int {
	n := 0
	for i := range g.Seats {
		if g.Seats[i].Alive && len(g.Seats[i].NightCommit) != 0 {
			n++
		}
	}
	return n
}

// submittedVote returns how many living players have committed a vote.
func submittedVote(g *Game) int {
	n := 0
	for i := range g.Seats {
		if g.Seats[i].Alive && len(g.Seats[i].VoteCommit) != 0 {
			n++
		}
	}
	return n
}

// gameCount returns the number of games ever opened.
func gameCount() int {
	return len(games)
}

package sandiwara

// This file holds the phase machine: every function that moves a game from one
// phase to the next, plus the commit-reveal cycles inside NIGHT and VOTE.
//
// Three rules are uniform across the file:
//
//  1. A function that changes state checks the phase first and the caller
//     second, and panics with a stable message on either failure.
//  2. No phase advances on a timer by itself. A phase advances when its work is
//     complete, or when anyone calls the matching force-advance function after
//     the deadline has passed. That keeps every transition attributable to a
//     transaction in the transcript.
//  3. A rejection panics and therefore changes nothing. Marking a seat absent or
//     unrevealed happens only inside Dawn, ForceDawn, and ForceVote — calls that
//     succeed — because a write inside a panicking transaction is rolled back
//     by the VM and would leave no trace.
//
// # Why DAWN exists and how it ends
//
// The brief fixes the order LOBBY -> SEAL -> NIGHT -> DAWN -> VOTE -> REVEAL ->
// DONE, but the required API has no "advance" function. DAWN therefore cannot
// be a phase that waits for an explicit call, or a game played through the
// documented surface alone would stall there forever. DAWN is instead the phase
// in which the night result is public and nobody has started voting yet: the
// last night reveal enters it, and the first accepted vote leaves it. That is
// what "dawn" means at a real table, and it keeps the required API sufficient
// to finish a game.

import (
	"chain"
	"chain/runtime"

	"gno.land/p/g1xf93j69vmuav53rlshfd249yyehq9jedrkwteq/acak"
	"gno.land/p/nt/ufmt/v0"
)

// StallGrace is how many blocks a phase runs before anyone may force it
// forward. It gives the players a window to act first.
const StallGrace = 100

// --- LOBBY ---------------------------------------------------------------

// Join seats the caller. Joining locks a seat and is only possible in LOBBY.
func Join(cur realm, gameID int64) {
	g := game(gameID)
	if g.Phase != PhaseLobby {
		panic("sandiwara: joining is only possible in the lobby")
	}
	addr := cur.Previous().Address()
	if seatIndex(g, addr) >= 0 {
		panic("sandiwara: caller is already seated")
	}
	if len(g.Seats) >= g.MaxPlyrs {
		panic("sandiwara: the table is full")
	}

	g.Seats = append(g.Seats, Seat{
		Addr:     addr,
		JoinedAt: runtime.ChainHeight(),
		Alive:    true,
	})
	i := len(g.Seats) - 1
	logf(g, "seat %d taken by %s", i, shortAddr(addr))

	chain.Emit("PlayerJoined",
		"gameID", ufmt.Sprintf("%d", gameID),
		"seat", ufmt.Sprintf("%d", i),
		"player", addr.String(),
	)
}

// --- SEAL ----------------------------------------------------------------

// Seal closes the lobby and publishes the dealer's commitment to the role map.
//
// root must be the Merkle root over the per-seat envelope leaves in seat order,
// where leaf i is acak.Commit(salt_i, []byte(role_i)). The realm cannot check
// that now — it does not know the roles — so it records the root and checks
// every envelope against it at reveal time.
func Seal(cur realm, gameID int64, root []byte) {
	g := game(gameID)
	if g.Phase != PhaseLobby {
		panic("sandiwara: the lobby is already closed")
	}
	if cur.Previous().Address() != g.Dealer {
		panic("sandiwara: only the dealer may seal the role map")
	}
	if len(g.Seats) < g.MinPlyrs {
		panic("sandiwara: not enough players to start")
	}
	if len(root) != HashSize {
		panic("sandiwara: role root must be 32 bytes")
	}

	g.RoleRoot = copyBytes(root)
	logf(g, "role root sealed: %s", fullHex(g.RoleRoot))

	// The lobby is now frozen and night opens immediately. The deadline is
	// armed so a silent table can still move on.
	setPhase(g, PhaseNight, runtime.ChainHeight()+StallGrace)

	chain.Emit("GameSealed",
		"gameID", ufmt.Sprintf("%d", gameID),
		"root", fullHex(g.RoleRoot),
		"players", ufmt.Sprintf("%d", len(g.Seats)),
	)
}

// --- NIGHT ---------------------------------------------------------------

// SubmitNight records the caller's night action commitment.
//
// The commitment is acak.Commit(salt, boundPayload(seat, action)), so it is
// bound to the caller's seat. Copying another player's commitment into your own
// seat cannot work: at reveal the realm recomputes the hash with your seat
// index, and the copy will not open.
func SubmitNight(cur realm, gameID int64, commitment []byte) {
	g := game(gameID)
	if g.Phase != PhaseNight {
		panic("sandiwara: night actions are only accepted in NIGHT")
	}
	i := mustSeat(g, cur.Previous().Address())
	if !g.Seats[i].Alive {
		panic("sandiwara: the dead do not act")
	}
	if len(commitment) != HashSize {
		panic("sandiwara: commitment must be 32 bytes")
	}
	if len(g.Seats[i].NightCommit) != 0 {
		panic("sandiwara: night action already submitted")
	}

	g.Seats[i].NightCommit = copyBytes(commitment)
	g.Seats[i].Absent = false
	logf(g, "seat %d committed a night action", i)

	chain.Emit("NightSubmitted",
		"gameID", ufmt.Sprintf("%d", gameID),
		"seat", ufmt.Sprintf("%d", i),
		"player", g.Seats[i].Addr.String(),
	)
}

// RevealNight opens one player's night commitment.
//
// A wrong salt or action is rejected with a panic and changes nothing: the
// commitment stays on record and the player may retry with the correct salt
// while the phase is open. A player who never manages to open their commitment
// is marked UNREVEALED by Dawn, in a transaction that actually succeeds.
//
// When the last living seat opens its commitment the night resolves by itself.
// That is what makes a full game playable through the required API alone: no
// seat has to remember to call an "advance" function, and a table that has
// finished its work cannot be left sitting in NIGHT.
func RevealNight(cur realm, gameID int64, action []byte, salt []byte) {
	g := game(gameID)
	if g.Phase != PhaseNight {
		panic("sandiwara: night actions are only revealed in NIGHT")
	}
	i := mustSeat(g, cur.Previous().Address())
	s := &g.Seats[i]
	if len(s.NightCommit) == 0 {
		panic("sandiwara: nothing was submitted to reveal")
	}
	if s.NightOpen {
		panic("sandiwara: night action already revealed")
	}
	if len(salt) != SaltSize {
		panic("sandiwara: salt must be 32 bytes")
	}

	if !commitMatches(s.NightCommit, i, action, salt) {
		logf(g, "seat %d night reveal rejected: does not match the commitment", i)
		chain.Emit("NightRevealRejected",
			"gameID", ufmt.Sprintf("%d", gameID),
			"seat", ufmt.Sprintf("%d", i),
		)
		panic("sandiwara: reveal does not match the commitment")
	}

	s.NightAction = string(action)
	s.NightSalt = copyBytes(salt)
	s.NightOpen = true
	logf(g, "seat %d revealed night action %q", i, s.NightAction)

	chain.Emit("NightRevealed",
		"gameID", ufmt.Sprintf("%d", gameID),
		"seat", ufmt.Sprintf("%d", i),
		"action", s.NightAction,
	)

	if everyLivingRevealedNight(g) {
		resolveNight(g)
	}
}

// --- DAWN ----------------------------------------------------------------

// Dawn resolves a night in which every living player committed but not every
// player opened their commitment.
//
// It requires every living player to have committed — that is the "cannot
// advance a phase with a missing submission" rule — and then records the seats
// that stayed shut as UNREVEALED. Their action is discarded and their
// commitment stays on the record, exactly as the brief specifies.
//
// The common case does not need this call: the last RevealNight resolves the
// night by itself. Dawn exists for the table where somebody committed and then
// went quiet.
func Dawn(cur realm, gameID int64) {
	g := game(gameID)
	if g.Phase != PhaseNight {
		panic("sandiwara: dawn only breaks after NIGHT")
	}
	if !everyLivingSubmittedNight(g) {
		panic("sandiwara: a living player has not submitted a night action")
	}
	resolveNight(g)
}

// ForceDawn advances a stalled NIGHT after its deadline, marking every player
// who did not commit as absent. This is the timeout that keeps one silent
// player from freezing the table forever.
func ForceDawn(cur realm, gameID int64) {
	g := game(gameID)
	if g.Phase != PhaseNight {
		panic("sandiwara: dawn only breaks after NIGHT")
	}
	requireDeadlinePassed(g)
	markAbsentNight(g)
	resolveNight(g)
}

// resolveNight is the shared tail of the last RevealNight, Dawn, and ForceDawn.
//
// It names every committed-but-unrevealed seat, then opens DAWN. The deadline is
// armed so a table that never votes can still be pushed forward.
func resolveNight(g *Game) {
	for i := range g.Seats {
		s := &g.Seats[i]
		if s.Alive && len(s.NightCommit) != 0 && !s.NightOpen {
			s.NightAction = UnrevealedAction
			logf(g, "seat %d did not reveal; night action discarded", i)
		}
	}
	setPhase(g, PhaseDawn, runtime.ChainHeight()+StallGrace)
	logf(g, "dawn resolved, voting opens")

	chain.Emit("DawnResolved", "gameID", ufmt.Sprintf("%d", g.ID))
}

// markAbsentNight records every living seat that never committed.
func markAbsentNight(g *Game) {
	for i := range g.Seats {
		s := &g.Seats[i]
		if s.Alive && len(s.NightCommit) == 0 {
			s.Absent = true
			s.NightAction = UnrevealedAction
			logf(g, "seat %d did not submit; marked absent", i)
		}
	}
}

// --- VOTE ----------------------------------------------------------------

// SubmitVote records the caller's elimination-vote commitment.
//
// The first accepted vote is also what ends DAWN: the table has seen the night
// result, so voting is under way. Later votes are accepted in VOTE as normal.
func SubmitVote(cur realm, gameID int64, commitment []byte) {
	g := game(gameID)
	if g.Phase != PhaseDawn && g.Phase != PhaseVote {
		panic("sandiwara: votes are only accepted once dawn has resolved")
	}
	i := mustSeat(g, cur.Previous().Address())
	if !g.Seats[i].Alive {
		panic("sandiwara: the dead do not vote")
	}
	if len(commitment) != HashSize {
		panic("sandiwara: commitment must be 32 bytes")
	}
	if len(g.Seats[i].VoteCommit) != 0 {
		panic("sandiwara: vote already submitted")
	}

	if g.Phase == PhaseDawn {
		setPhase(g, PhaseVote, runtime.ChainHeight()+StallGrace)
		logf(g, "the first vote opens voting")
	}

	g.Seats[i].VoteCommit = copyBytes(commitment)
	g.Seats[i].Absent = false
	logf(g, "seat %d committed a vote", i)

	chain.Emit("VoteSubmitted",
		"gameID", ufmt.Sprintf("%d", gameID),
		"seat", ufmt.Sprintf("%d", i),
		"player", g.Seats[i].Addr.String(),
	)
}

// RevealVote opens one player's vote.
//
// As with RevealNight, the last living reveal closes voting by itself, so the
// required API is enough to reach REVEAL.
func RevealVote(cur realm, gameID int64, target []byte, salt []byte) {
	g := game(gameID)
	if g.Phase != PhaseVote {
		panic("sandiwara: votes are only revealed in VOTE")
	}
	i := mustSeat(g, cur.Previous().Address())
	s := &g.Seats[i]
	if len(s.VoteCommit) == 0 {
		panic("sandiwara: nothing was submitted to reveal")
	}
	if s.VoteOpen {
		panic("sandiwara: vote already revealed")
	}
	if len(salt) != SaltSize {
		panic("sandiwara: salt must be 32 bytes")
	}

	if !commitMatches(s.VoteCommit, i, target, salt) {
		logf(g, "seat %d vote reveal rejected: does not match the commitment", i)
		chain.Emit("VoteRevealRejected",
			"gameID", ufmt.Sprintf("%d", gameID),
			"seat", ufmt.Sprintf("%d", i),
		)
		panic("sandiwara: reveal does not match the commitment")
	}

	s.VoteTarget = string(target)
	s.VoteSalt = copyBytes(salt)
	s.VoteOpen = true
	logf(g, "seat %d voted for %q", i, s.VoteTarget)

	chain.Emit("VoteRevealed",
		"gameID", ufmt.Sprintf("%d", gameID),
		"seat", ufmt.Sprintf("%d", i),
		"target", s.VoteTarget,
	)

	if everyLivingRevealedVote(g) {
		closeVote(g)
	}
}

// ForceVote advances a stalled DAWN or VOTE after its deadline.
//
// A seat that never committed is marked absent; a seat that committed and never
// revealed keeps its commitment on record and is marked unrevealed. Either way
// the vote does not count and the table moves on.
func ForceVote(cur realm, gameID int64) {
	g := game(gameID)
	if g.Phase != PhaseDawn && g.Phase != PhaseVote {
		panic("sandiwara: voting is not open")
	}
	requireDeadlinePassed(g)
	for i := range g.Seats {
		s := &g.Seats[i]
		if !s.Alive {
			continue
		}
		if len(s.VoteCommit) == 0 {
			s.Absent = true
			s.VoteTarget = UnrevealedAction
			logf(g, "seat %d did not submit a vote; marked absent", i)
		} else if !s.VoteOpen {
			s.VoteTarget = UnrevealedAction
			logf(g, "seat %d did not reveal; vote discarded", i)
		}
	}
	closeVote(g)
}

// closeVote is the shared tail of the last RevealVote and ForceVote.
func closeVote(g *Game) {
	setPhase(g, PhaseReveal, runtime.ChainHeight()+StallGrace)
	logf(g, "voting closed, the dealer must now open the envelopes")

	chain.Emit("VotingClosed", "gameID", ufmt.Sprintf("%d", g.ID))
}

// --- REVEAL --------------------------------------------------------------

// RevealRoles opens every role envelope in one transaction and verifies them
// against the sealed root.
//
// This is the moment the product's promise is kept or broken. Each (role, salt)
// pair must hash to the leaf the dealer committed to for that seat, and the tree
// rebuilt from those leaves must equal the stored root. A single mismatch marks
// the game disputed and emits DealerDisputed — the permanent public record that
// the dealer cheated.
//
// A dispute does NOT panic. A panic in Gno reverts the whole transaction, so a
// realm that panicked here would erase the very evidence it was trying to keep.
// Instead the envelopes are recorded, the verdict says DISPUTED, the phase goes
// to DONE, and DealerDisputed is emitted. The game cannot continue and the
// accusation is on the record forever.
//
// # Why this signature is not callable through `gnokey maketx call`
//
// The chain encodes MsgCall arguments with convertArgToGno, which accepts only
// primitives, [N]byte, and []byte. A []string or [][]byte argument is rejected
// with "unexpected slice type in contract arg" before the realm is ever
// entered, so this function cannot be invoked by a normal transaction no matter
// what it does internally. It exists because the brief fixes this exact surface,
// and it is the right shape for a Go/Gno caller, a filetest, or a future
// MsgRun-based client. For a real table on chain, use RevealRole per seat: same
// verification, same verdict, one callable transaction per envelope.
func RevealRoles(cur realm, gameID int64, roles []string, salts [][]byte) {
	g := game(gameID)
	requireRevealCaller(g, cur)

	if len(roles) != len(g.Seats) {
		panic("sandiwara: one role per seat is required")
	}
	if len(salts) != len(g.Seats) {
		panic("sandiwara: one salt per seat is required")
	}
	for i := range g.Seats {
		if len(salts[i]) != SaltSize {
			panic("sandiwara: envelope salt must be 32 bytes")
		}
	}

	beginReveal(g)
	for i := range g.Seats {
		recordEnvelope(g, i, roles[i], salts[i])
	}
	finalizeReveal(g, gameID)
}

// RevealRole opens ONE role envelope and records it, then verifies the whole map
// once the last envelope is in.
//
// This is the on-chain path: every argument is a type MsgCall can encode
// (int64, int, string, []byte), so the dealer calls it once per seat and the
// final call runs the same check RevealRoles runs. Splitting the reveal does not
// weaken anything — each envelope is fixed by the sealed root before the first
// call, so revealing one early cannot help a dealer who intends to lie; it only
// makes the lie visible one seat sooner.
//
// A seat may be revealed at most once, and the index must be a real seat.
func RevealRole(cur realm, gameID int64, index int, role string, salt []byte) {
	g := game(gameID)
	requireRevealCaller(g, cur)

	if index < 0 || index >= len(g.Seats) {
		panic("sandiwara: no such seat")
	}
	if len(salt) != SaltSize {
		panic("sandiwara: envelope salt must be 32 bytes")
	}

	beginReveal(g)
	if len(g.Revealed[index].Leaf) != 0 {
		panic("sandiwara: envelope already revealed")
	}

	recordEnvelope(g, index, role, salt)
	logf(g, "seat %d envelope opened: %q", index, role)

	chain.Emit("RoleEnvelopeOpened",
		"gameID", ufmt.Sprintf("%d", gameID),
		"seat", ufmt.Sprintf("%d", index),
	)

	if allEnvelopesClaimed(g) {
		finalizeReveal(g, gameID)
	}
}

// requireRevealCaller enforces the two preconditions shared by RevealRoles and
// RevealRole: the game is in REVEAL, and the caller is the dealer.
//
// The realm value is named rlm, not cur, because this is not a crossing
// function: only a crossing function's first realm parameter may be called cur.
// Passing the caller's cur through as an ordinary argument is exactly what is
// wanted here — it names the realm that was current when cur was minted.
func requireRevealCaller(g *Game, rlm realm) {
	if g.Phase != PhaseReveal {
		panic("sandiwara: roles may only be revealed in REVEAL")
	}
	if rlm.Previous().Address() != g.Dealer {
		panic("sandiwara: only the dealer may reveal the roles")
	}
}

// beginReveal allocates the per-seat claim slots on the first reveal call.
func beginReveal(g *Game) {
	if g.Revealed != nil {
		return
	}
	g.Revealed = make([]EnvelopeRecord, len(g.Seats))
	for i := range g.Revealed {
		g.Revealed[i].Index = i
	}
}

// recordEnvelope stores one seat's claimed (role, salt) and the leaf they imply.
func recordEnvelope(g *Game, i int, role string, salt []byte) {
	g.Revealed[i] = EnvelopeRecord{
		Index: i,
		Role:  role,
		Salt:  copyBytes(salt),
		Leaf:  roleLeaf(role, salt),
	}
}

// allEnvelopesClaimed reports whether every seat has a claimed envelope.
func allEnvelopesClaimed(g *Game) bool {
	for i := range g.Revealed {
		if len(g.Revealed[i].Leaf) == 0 {
			return false
		}
	}
	return true
}

// finalizeReveal is the shared tail of RevealRoles and the last RevealRole.
//
// It rebuilds the tree from the claimed leaves and compares it to the sealed
// root. The root is recomputed here rather than trusted: the whole point is that
// the realm, not the dealer, decides whether the claim holds.
func finalizeReveal(g *Game, gameID int64) {
	leaves := make([][]byte, len(g.Seats))
	for i := range leaves {
		leaves[i] = g.Revealed[i].Leaf
	}

	tree := acak.NewTree(leaves)
	recomputed := tree.Root()

	if !bytesEqual(recomputed, g.RoleRoot) {
		g.Disputed = true
		g.Verdict = "DISPUTED: the revealed envelopes do not hash to the sealed root"
		logf(g, "DEALER DISPUTED: revealed root %s != sealed root %s",
			fullHex(recomputed), fullHex(g.RoleRoot))
		setPhase(g, PhaseDone, 0)

		chain.Emit(EventDealerDisputed,
			"gameID", ufmt.Sprintf("%d", gameID),
			"sealed", fullHex(g.RoleRoot),
			"revealed", fullHex(recomputed),
		)
		return
	}

	// Verified. Record each envelope with its own proof so a third party can
	// re-check one seat without rebuilding the whole tree.
	for i := range g.Revealed {
		aunts, total := tree.Prove(i)
		g.Revealed[i].Verified = acak.Verify(g.RoleRoot, g.Revealed[i].Leaf, i, total, aunts)
	}
	g.Verdict = "VERIFIED: every envelope hashes to the sealed root"
	logf(g, "role envelopes verified against the sealed root")

	setPhase(g, PhaseDone, 0)

	chain.Emit("RolesRevealed",
		"gameID", ufmt.Sprintf("%d", gameID),
		"verdict", "VERIFIED",
	)
}

// --- helpers -------------------------------------------------------------

// requireDeadlinePassed panics unless the current phase's deadline has passed.
func requireDeadlinePassed(g *Game) {
	if g.PhaseDeadline == 0 {
		panic("sandiwara: this phase has no deadline")
	}
	if runtime.ChainHeight() <= g.PhaseDeadline {
		panic("sandiwara: the phase deadline has not passed yet")
	}
}

// everyLivingSubmittedNight reports whether every living player committed.
func everyLivingSubmittedNight(g *Game) bool {
	for i := range g.Seats {
		s := &g.Seats[i]
		if s.Alive && len(s.NightCommit) == 0 {
			return false
		}
	}
	return true
}

// everyLivingRevealedNight reports whether every living player opened their
// night commitment.
func everyLivingRevealedNight(g *Game) bool {
	for i := range g.Seats {
		s := &g.Seats[i]
		if s.Alive && !s.NightOpen {
			return false
		}
	}
	return true
}

// everyLivingRevealedVote reports whether every living player opened their vote.
func everyLivingRevealedVote(g *Game) bool {
	for i := range g.Seats {
		s := &g.Seats[i]
		if s.Alive && !s.VoteOpen {
			return false
		}
	}
	return true
}

package sandiwara

// Rendering. Four pages, all built with p/nt/mux:
//
//	/                        lobby list, one seat map per game
//	/game/{id}               the board for one game
//	/game/{id}/transcript    every commitment and reveal, phase by phase
//	/game/{id}/verify        the role root and the exact recomputation
//
// Every user-supplied string that reaches markdown goes through
// sanitize.InlineText or sanitize.TableCell. Game titles are user input.

import (
	"strconv"
	"strings"

	"gno.land/p/nt/markdown/sanitize/v0"
	"gno.land/p/nt/mux/v0"
	"gno.land/p/nt/svg/v0"
	"gno.land/p/nt/ufmt/v0"
)

// Colour palette. Kept here so the board and the transcript agree.
const (
	colBackground = "#12161f"
	colSeatAlive  = "#243447"
	colSeatDead   = "#3a2028"
	colSeatActed  = "#1f4d3a"
	colStroke     = "#4a5b73"
	colText       = "#e6edf6"
	colMuted      = "#8b9bb4"
	colAccent     = "#63b3ed"
	colWarn       = "#f6ad55"
	colGood       = "#68d391"
	colBad        = "#fc8181"
)

func init() {
	router = mux.NewRouter()
	router.HandleFunc("", lobbyHandler)
	router.HandleFunc("game/{id}", boardHandler)
	router.HandleFunc("game/{id}/transcript", transcriptHandler)
	router.HandleFunc("game/{id}/verify", verifyHandler)
}

// Render is the realm's entry point. path is attacker-controlled.
func Render(path string) string {
	return router.Render(path)
}

// honestyLine is the one sentence the brief requires, unhedged, in the UI.
const honestyLine = "This realm does not implement an autonomous referee that secretly " +
	"knows who the werewolf is — Gno.land state is public, so a contract cannot hold a " +
	"secret; secrecy during play depends on the dealer not leaking, and only " +
	"verifiability after play is total."

// --- handlers --------------------------------------------------------------

func lobbyHandler(res *mux.ResponseWriter, req *mux.Request) {
	var b strings.Builder

	b.WriteString("# Sandiwara\n\n")
	b.WriteString("> The roles are sealed before the first night, and the dealer cannot rewrite them after the last.\n\n")
	b.WriteString("**" + honestyLine + "**\n\n")

	if gameCount() == 0 {
		b.WriteString("No tables yet. Open one with `NewGame`, then five to twelve players `Join`.\n")
		res.Write(b.String())
		return
	}

	b.WriteString("## Tables\n\n")
	b.WriteString("| # | title | seats | phase |\n")
	b.WriteString("|---|---|---|---|\n")
	for _, g := range games {
		b.WriteString("| " + strconv.FormatInt(g.ID, 10) + " | ")
		b.WriteString(sanitize.TableCell(g.Title))
		b.WriteString(" | " + strconv.Itoa(seatsFilled(g)) + "/" + strconv.Itoa(g.MaxPlyrs) + " | ")
		b.WriteString(g.Phase.String() + " |\n")
	}
	b.WriteString("\n")

	for _, g := range games {
		b.WriteString("### Table " + strconv.FormatInt(g.ID, 10) + ": " + sanitize.InlineText(g.Title) + "\n\n")
		b.WriteString(seatMap(g))
		b.WriteString("\n")
		b.WriteString(linkRow(g))
		b.WriteString("\n\n")
	}

	res.Write(b.String())
}

func boardHandler(res *mux.ResponseWriter, req *mux.Request) {
	g, ok := gameFromRequest(res, req)
	if !ok {
		return
	}

	var b strings.Builder
	b.WriteString("# " + sanitize.InlineText(g.Title) + "\n\n")
	b.WriteString("Table " + strconv.FormatInt(g.ID, 10) + " · phase **" + g.Phase.String() + "** · ")
	b.WriteString("dealer `" + shortAddr(g.Dealer) + "`\n\n")
	b.WriteString(seatMap(g))
	b.WriteString("\n")
	b.WriteString(seatGrid(g))
	b.WriteString("\n")

	b.WriteString("## This phase\n\n")
	b.WriteString(phaseSummary(g))
	b.WriteString("\n\n")
	b.WriteString(linkRow(g))
	b.WriteString("\n")

	res.Write(b.String())
}

func transcriptHandler(res *mux.ResponseWriter, req *mux.Request) {
	g, ok := gameFromRequest(res, req)
	if !ok {
		return
	}

	var b strings.Builder
	b.WriteString("# Transcript: " + sanitize.InlineText(g.Title) + "\n\n")
	b.WriteString("Table " + strconv.FormatInt(g.ID, 10) + " · phase **" + g.Phase.String() + "**\n\n")

	b.WriteString("## Phase log\n\n")
	if len(g.Transcript) == 0 {
		b.WriteString("_Nothing has happened yet._\n")
	}
	for _, line := range g.Transcript {
		b.WriteString("- " + sanitize.InlineText(line) + "\n")
	}
	b.WriteString("\n")

	b.WriteString("## Commitments and reveals\n\n")
	b.WriteString("| seat | player | night commitment | night action | vote commitment | vote target |\n")
	b.WriteString("|---|---|---|---|---|---|\n")
	for i := range g.Seats {
		s := &g.Seats[i]
		b.WriteString("| " + strconv.Itoa(i) + " | `" + shortAddr(s.Addr) + "` | ")
		b.WriteString(hexOrDash(s.NightCommit) + " | " + actionOrDash(s.NightAction) + " | ")
		b.WriteString(hexOrDash(s.VoteCommit) + " | " + actionOrDash(s.VoteTarget) + " |\n")
	}
	b.WriteString("\n")

	b.WriteString("## Verification\n\n")
	if g.Verdict == "" {
		b.WriteString("Not yet verified: the dealer has not opened the envelopes.\n")
	} else {
		b.WriteString("**" + sanitize.InlineText(g.Verdict) + "**\n")
	}

	res.Write(b.String())
}

func verifyHandler(res *mux.ResponseWriter, req *mux.Request) {
	g, ok := gameFromRequest(res, req)
	if !ok {
		return
	}

	var b strings.Builder
	b.WriteString("# Verify: " + sanitize.InlineText(g.Title) + "\n\n")
	b.WriteString("A third party does not have to trust this realm's verdict. Everything needed to ")
	b.WriteString("recompute it is below.\n\n")

	b.WriteString("## The dealer's sealed commitment\n\n")
	if len(g.RoleRoot) == 0 {
		b.WriteString("_The role root has not been sealed yet._\n\n")
	} else {
		b.WriteString("```\nsealed root  " + fullHex(g.RoleRoot) + "\n```\n\n")
	}

	if len(g.Revealed) == 0 {
		b.WriteString("## Envelopes\n\n_The dealer has not revealed the envelopes yet._\n\n")
		b.WriteString(recomputeRecipe())
		res.Write(b.String())
		return
	}

	b.WriteString("## Revealed envelopes\n\n")
	b.WriteString("| seat | role | salt | leaf sha256(salt‖role) | verified |\n")
	b.WriteString("|---|---|---|---|---|\n")
	for i := range g.Revealed {
		e := &g.Revealed[i]
		b.WriteString("| " + strconv.Itoa(e.Index) + " | ")
		b.WriteString(sanitize.TableCell(e.Role) + " | `" + fullHex(e.Salt) + "` | ")
		b.WriteString("`" + fullHex(e.Leaf) + "` | ")
		if e.Verified {
			b.WriteString("yes |\n")
		} else {
			b.WriteString("no |\n")
		}
	}
	b.WriteString("\n")

	b.WriteString("## Verdict\n\n")
	b.WriteString("**" + sanitize.InlineText(g.Verdict) + "**\n\n")

	b.WriteString(recomputeRecipe())
	res.Write(b.String())
}

// recomputeRecipe prints the exact steps a third party runs.
func recomputeRecipe() string {
	var b strings.Builder
	b.WriteString("## How to check this yourself\n\n")
	b.WriteString("1. For each seat `i`, compute `leaf_i = acak.Commit(salt_i, []byte(role_i))`, ")
	b.WriteString("which is `sha256(salt_i ‖ role_i)`.\n")
	b.WriteString("2. Build the tree over the leaves **in seat order**: `acak.NewTree(leaves)`.\n")
	b.WriteString("3. Compare `tree.Root()` with the sealed root printed above.\n")
	b.WriteString("4. For a single seat: `aunts, total := tree.Prove(i)` then ")
	b.WriteString("`acak.Verify(root, leaf_i, i, total, aunts)`.\n\n")
	b.WriteString("If step 3 does not match, the dealer changed the role map after sealing it. ")
	b.WriteString("That is what `DealerDisputed` records, permanently, in this realm's state.\n")
	return b.String()
}

// --- the seat map ----------------------------------------------------------

// seatMap draws the table as an SVG grid. Each seat shows its address prefix,
// whether the player is alive, and whether they have acted in the current
// phase. During NIGHT this is the only public information, which is exactly
// right: who has acted is public, what they did is not.
func seatMap(g *Game) string {
	const (
		cellW  = 210
		cellH  = 96
		margin = 18
		perRow = 3
		gap    = 12
	)

	rows := (len(g.Seats) + perRow - 1) / perRow
	if rows == 0 {
		rows = 1
	}
	w := margin*2 + perRow*cellW + (perRow-1)*gap
	h := margin*2 + 46 + rows*cellH + (rows-1)*gap

	c := svg.NewCanvas(w, h).WithViewBox(0, 0, w, h)
	c.Append(svg.NewRectangle(0, 0, w, h, colBackground))

	// Title strip: the phase, so a screenshot of the board is self-describing.
	c.Append(svg.NewText(margin, margin+16, g.Phase.String(), colAccent))
	c.Append(svg.NewText(margin+150, margin+16,
		ufmt.Sprintf("seats %d/%d   alive %d", seatsFilled(g), g.MaxPlyrs, livingCount(g)), colMuted))

	for i := range g.Seats {
		s := &g.Seats[i]
		col := i % perRow
		row := i / perRow
		x := margin + col*(cellW+gap)
		y := margin + 46 + row*(cellH+gap)

		fill := colSeatAlive
		if !s.Alive {
			fill = colSeatDead
		}
		acted := hasActed(g.Phase, s)
		if acted {
			fill = colSeatActed
		}

		c.Append(svg.NewRectangle(x, y, cellW, cellH, fill))
		// A second, unfilled rectangle with a visible stroke, so the cell
		// edge reads clearly against the dark background.
		border := svg.NewRectangle(x, y, cellW, cellH, "none")
		border.Attr.Stroke = colStroke
		border.Attr.StrokeWidth = "2"
		c.Append(border)

		// Seat number and address prefix.
		c.Append(svg.NewText(x+14, y+26, ufmt.Sprintf("#%d", i), colMuted))
		c.Append(svg.NewText(x+14, y+50, shortAddr(s.Addr), colText))

		// Status line: alive/dead, then acted/not.
		status := "alive"
		statusCol := colGood
		if !s.Alive {
			status = "dead"
			statusCol = colBad
		}
		c.Append(svg.NewText(x+14, y+76, status, statusCol))

		act := "not submitted"
		actCol := colMuted
		if acted {
			act = "submitted"
			actCol = colGood
		}
		if s.Absent {
			act = "absent"
			actCol = colWarn
		}
		c.Append(svg.NewText(x+86, y+76, act, actCol))

		// A small marker for the dealer, so the table's authority is visible.
		if s.Addr == g.Dealer {
			c.Append(svg.NewText(x+cellW-72, y+26, "dealer", colWarn))
		}
	}

	return c.Render("table " + strconv.FormatInt(g.ID, 10) + ", phase " + g.Phase.String())
}

// seatGrid is the same information as the SVG, as a markdown table. The SVG is
// the thing a human looks at; the table is the thing a screen reader, a diff,
// and `grep` can read. Both are generated from the same state, so they cannot
// disagree.
func seatGrid(g *Game) string {
	var b strings.Builder
	b.WriteString("| seat | player | status | this phase |\n")
	b.WriteString("|---|---|---|---|\n")
	for i := range g.Seats {
		s := &g.Seats[i]
		b.WriteString("| " + strconv.Itoa(i) + " | `" + shortAddr(s.Addr) + "` | ")
		if s.Alive {
			b.WriteString("alive")
		} else {
			b.WriteString("dead")
		}
		b.WriteString(" | ")
		switch {
		case s.Absent:
			b.WriteString("absent")
		case hasActed(g.Phase, s):
			b.WriteString("submitted")
		default:
			b.WriteString("not submitted")
		}
		b.WriteString(" |\n")
	}
	return b.String()
}

// hasActed reports whether the seat has acted in the given phase.
func hasActed(p Phase, s *Seat) bool {
	switch p {
	case PhaseNight:
		return len(s.NightCommit) != 0
	case PhaseDawn, PhaseVote:
		return len(s.VoteCommit) != 0
	case PhaseReveal, PhaseDone:
		return s.VoteOpen
	}
	return false
}

// phaseSummary is one paragraph of plain prose about the current phase.
func phaseSummary(g *Game) string {
	switch g.Phase {
	case PhaseLobby:
		return ufmt.Sprintf("%d of %d minimum seats filled. The dealer seals the role map when the table is ready.",
			seatsFilled(g), g.MinPlyrs)
	case PhaseSeal:
		return "The lobby is closed."
	case PhaseNight:
		return ufmt.Sprintf("%d of %d living players have committed a night action. Nothing they did is public until they reveal.",
			submittedNight(g), livingCount(g))
	case PhaseDawn:
		return "The night has resolved. Voting opens."
	case PhaseVote:
		return ufmt.Sprintf("%d of %d living players have committed a vote.",
			submittedVote(g), livingCount(g))
	case PhaseReveal:
		return "Voting is closed. The dealer must now open every role envelope."
	case PhaseDone:
		if g.Disputed {
			return "**The dealer disputed the record: the revealed envelopes do not match the sealed root.**"
		}
		return "The game is over and the transcript is final."
	}
	return ""
}

// --- small formatters ------------------------------------------------------

// linkRow renders the three per-game navigation links.
func linkRow(g *Game) string {
	base := "/r/" + realmPath + "/game/" + strconv.FormatInt(g.ID, 10)
	return "[board](" + base + ") · [transcript](" + base + "/transcript) · [verify](" + base + "/verify)"
}

// gameFromRequest resolves the {id} path variable, writing a 404 body when it
// does not name a game.
func gameFromRequest(res *mux.ResponseWriter, req *mux.Request) (*Game, bool) {
	id, ok := parseGameID(req.GetVar("id"))
	if !ok {
		res.Write("No such table.\n")
		return nil, false
	}
	return games[id], true
}

// hexOrDash renders a commitment as short hex, or a dash when absent.
func hexOrDash(b []byte) string {
	if len(b) == 0 {
		return "—"
	}
	return "`" + shortHex(b) + "…`"
}

// actionOrDash renders a revealed action, or a dash when absent.
func actionOrDash(s string) string {
	if s == "" {
		return "—"
	}
	if s == UnrevealedAction {
		return "_unrevealed_"
	}
	return sanitize.TableCell(s)
}

// parseGameID parses a game id from a render path segment.
func parseGameID(s string) (int64, bool) {
	if s == "" {
		return 0, false
	}
	n, err := strconv.ParseInt(s, 10, 64)
	if err != nil || n < 0 || n >= int64(len(games)) {
		return 0, false
	}
	return n, true
}

// Package sandiwara is a sealed-envelope social deduction game.
//
// The roles are sealed before the first night, and the dealer cannot rewrite
// them after the last.
//
// # What this realm does, and what it does not do
//
// Gno.land state is public. A contract cannot hold a secret. This realm
// therefore does NOT implement an autonomous referee that secretly knows who
// the werewolf is: without MPC or zero-knowledge proofs there is nowhere to
// put such a secret, and claiming otherwise would be a lie.
//
// What it does implement is a dealer commitment. Before play starts the dealer
// publishes a Merkle root over one envelope per seat, where envelope i is
// acak.Commit(salt_i, []byte(role_i)) = sha256(salt_i || role_i). The root is
// public; the roles are not. At the end the dealer must open every envelope and
// the realm recomputes the tree itself. So the role map provably could not have
// changed after the game began.
//
// Night actions and votes are committed during play and revealed when their
// phase closes, so the action log is equally non-rewritable.
//
// Secrecy DURING play depends on the dealer not leaking. Verifiability AFTER
// play is total.
//
// # Phases
//
//	LOBBY -> SEAL -> NIGHT -> DAWN -> VOTE -> REVEAL -> DONE
//
// See docs/ARCHITECTURE.md for the phase table: who may call what, when.
package sandiwara

import (
	"chain"
	"chain/runtime"

	"gno.land/p/g1xf93j69vmuav53rlshfd249yyehq9jedrkwteq/acak"
	"gno.land/p/nt/mux/v0"
	"gno.land/p/nt/ufmt/v0"
)

// Phase is a stage of the game. The integer values are part of the public
// transcript, so they are fixed here and never reordered.
type Phase int

const (
	PhaseLobby  Phase = iota // players join
	PhaseSeal                // dealer publishes the role root
	PhaseNight               // night actions committed, then revealed
	PhaseDawn                // night resolved, outcome public
	PhaseVote                // elimination votes committed, then revealed
	PhaseReveal              // dealer opens every role envelope
	PhaseDone                // transcript is final
)

// phaseNames maps a phase to the word used in the UI and the transcript.
var phaseNames = [...]string{
	PhaseLobby:  "LOBBY",
	PhaseSeal:   "SEAL",
	PhaseNight:  "NIGHT",
	PhaseDawn:   "DAWN",
	PhaseVote:   "VOTE",
	PhaseReveal: "REVEAL",
	PhaseDone:   "DONE",
}

func (p Phase) String() string {
	if p < 0 || int(p) >= len(phaseNames) {
		return "UNKNOWN"
	}
	return phaseNames[p]
}

// Limits on table size. The brief fixes these; they are also what keeps the
// SVG seat map legible.
const (
	MinPlayersFloor = 5
	MaxPlayersCeil  = 12

	// realmPath is this realm's own package path, used to build in-realm
	// links in Render output.
	realmPath = "g1xf93j69vmuav53rlshfd249yyehq9jedrkwteq/sandiwara"

	// SaltSize is the envelope salt length. It matches acak.Commit, which
	// refuses anything but 32 bytes: a shorter salt would let an observer
	// brute-force an envelope's role before the dealer reveals it.
	SaltSize = 32

	// HashSize is the length of every commitment and of the role root.
	HashSize = 32

	// UnrevealedAction is the marker stored for a player who committed and
	// then refused to reveal, or who let the phase deadline pass. Their
	// commitment stays on record; their action does not resolve.
	UnrevealedAction = "UNREVEALED"

	// EventDealerDisputed is the permanent, indexed record that the dealer's
	// reveal did not match the root sealed before play. This is the single
	// most important event this realm emits.
	EventDealerDisputed = "DealerDisputed"
)

// Seat is one player at the table.
//
// Note what is NOT here: no role. Roles never enter realm state before the
// dealer's reveal, because state is public and storing them would leak them.
type Seat struct {
	Addr     address
	JoinedAt int64

	// Night commitment and reveal.
	NightCommit []byte
	NightAction string
	NightSalt   []byte
	NightOpen   bool // revealed and verified

	// Vote commitment and reveal.
	VoteCommit []byte
	VoteTarget string
	VoteSalt   []byte
	VoteOpen   bool

	Alive bool

	// Absent records that this seat let a phase deadline pass without acting.
	// It is public, and it is the whole penalty: a stall does not block the
	// table, it only writes this seat's name into the transcript.
	Absent bool
}

// EnvelopeRecord is what the dealer claimed at reveal time, kept so a third
// party can recompute the verification without trusting this realm's summary.
type EnvelopeRecord struct {
	Index    int
	Role     string
	Salt     []byte
	Leaf     []byte // sha256(salt || role), the value hashed into the tree
	Verified bool
}

// Game is one table's full state and transcript.
type Game struct {
	ID       int64
	Title    string
	Dealer   address
	MinPlyrs int
	MaxPlyrs int
	Phase    Phase
	PhaseAt  int64 // block height the current phase was entered

	// PhaseDeadline is the height at which a stalled phase may be advanced.
	// Zero means no deadline is armed (LOBBY, DONE).
	PhaseDeadline int64

	Seats []Seat

	// RoleRoot is the dealer's commitment to the role map, published at Seal.
	RoleRoot []byte

	// Revealed is the dealer's reveal, filled at RevealRoles.
	Revealed []EnvelopeRecord

	// Verdict is the final verification result, computed at RevealRoles.
	Verdict string

	// Disputed records that the dealer's reveal failed verification. This is
	// the permanent, public record that the dealer cheated.
	Disputed bool

	// Transcript is the append-only human-readable log.
	Transcript []string
}

var (
	games  []*Game
	router *mux.Router
)

// NewGame opens a table. The caller becomes the dealer.
//
// The dealer is the only address allowed to Seal the role map and to open it at
// the end. Everything else is permissionless.
func NewGame(cur realm, title string, minPlayers, maxPlayers int) int64 {
	dealer := cur.Previous().Address()

	if minPlayers < MinPlayersFloor {
		panic("sandiwara: minPlayers must be at least 5")
	}
	if maxPlayers > MaxPlayersCeil {
		panic("sandiwara: maxPlayers must be at most 12")
	}
	if minPlayers > maxPlayers {
		panic("sandiwara: minPlayers must not exceed maxPlayers")
	}

	id := int64(len(games))
	g := &Game{
		ID:       id,
		Title:    title,
		Dealer:   dealer,
		MinPlyrs: minPlayers,
		MaxPlyrs: maxPlayers,
		Phase:    PhaseLobby,
		PhaseAt:  runtime.ChainHeight(),
	}
	games = append(games, g)
	logf(g, "table opened by %s", shortAddr(dealer))

	chain.Emit("GameOpened",
		"gameID", ufmt.Sprintf("%d", id),
		"dealer", dealer.String(),
	)

	return id
}

// game returns the game with the given id, panicking if there is none.
func game(id int64) *Game {
	if id < 0 || id >= int64(len(games)) {
		panic("sandiwara: no such game")
	}
	return games[id]
}

// seatIndex returns the index of addr in g.Seats, or -1.
func seatIndex(g *Game, addr address) int {
	for i := range g.Seats {
		if g.Seats[i].Addr == addr {
			return i
		}
	}
	return -1
}

// mustSeat returns the seat index of the caller, panicking if they have none.
func mustSeat(g *Game, addr address) int {
	i := seatIndex(g, addr)
	if i < 0 {
		panic("sandiwara: caller is not seated at this table")
	}
	return i
}

// logf appends one line to the game's transcript.
func logf(g *Game, format string, args ...any) {
	g.Transcript = append(g.Transcript, ufmt.Sprintf(format, args...))
}

// setPhase advances g to p and arms its deadline.
func setPhase(g *Game, p Phase, deadline int64) {
	g.Phase = p
	g.PhaseAt = runtime.ChainHeight()
	g.PhaseDeadline = deadline
	logf(g, "phase %s at height %d", p, g.PhaseAt)
}

// boundPayload builds the exact byte string a player's commitment covers: a
// fixed 4-byte big-endian seat index followed by the action.
//
// This is what makes a commitment non-transferable. The realm recomputes the
// hash with the *revealing* seat's index, so a player who copies somebody
// else's commitment into their own slot can never open it: they would have to
// find a salt and action that hash to it under their own index. The commitment
// is bound to the seat, and the seat is bound to the address.
func boundPayload(seat int, action []byte) []byte {
	out := make([]byte, 0, 4+len(action))
	out = append(out,
		byte(seat>>24), byte(seat>>16), byte(seat>>8), byte(seat))
	out = append(out, action...)
	return out
}

// commitMatches reports whether commitment is the hash of this seat's bound
// payload under salt.
func commitMatches(commitment []byte, seat int, payload, salt []byte) bool {
	if len(salt) != SaltSize {
		return false
	}
	return bytesEqual(acak.Commit(salt, boundPayload(seat, payload)), commitment)
}

// roleLeaf is the envelope leaf: sha256(salt || role), via acak.Commit.
func roleLeaf(role string, salt []byte) []byte {
	return acak.Commit(salt, []byte(role))
}

package cube3x3

// PhaseSegment describes an inclusive range of one-based solution move indices.
type PhaseSegment struct {
	Name      string
	StartMove int
	EndMove   int
	OBTM      int
}

// PhaseReport records the first Cross, F2L, and OLL checkpoints and the PLL
// checkpoint for the terminal solved run. A zero index means absent.
type PhaseReport struct {
	CrossFace   string
	CrossColor  uint8
	CrossAtMove int
	F2LAtMove   int
	OLLAtMove   int
	PLLAtMove   int
	Segments    []PhaseSegment
}

// Each row maps a face in the new frame to its location in the old frame
// after one clockwise quarter rotation. The columns follow move base order.
var priorFrame = [3][6]uint8{
	X - X: {F, B, L, R, D, U},
	Y - X: {U, D, F, B, R, L},
	Z - X: {L, R, D, U, F, B},
}

// ToPureFaceMoves projects each turn onto the starting frame. A wide turn
// emits its opposite-layer turn and changes the frame. Rotations only change
// the frame. Every projected turn keeps its original modifier and order.
func ToPureFaceMoves(moves []Move) []Move {
	frame := [6]uint8{U, D, L, R, F, B}
	pure := make([]Move, 0, len(moves))
	for _, move := range moves {
		if !isValidMove(move) {
			continue
		}
		if move.Base < Uw {
			pure = append(pure, Move{frame[move.Base], move.Mod})
			continue
		}
		if move.Base < X {
			wide := wideTurns[move.Base-Uw]
			pure = append(pure, Move{frame[wide.oppositeFace], move.Mod})
			move.Base = wide.rotation
			if wide.reverseRotation {
				move.Mod = 4 - move.Mod
			}
		}
		for turn := uint8(0); turn < move.Mod; turn++ {
			previous := frame
			for face, oldFace := range priorFrame[move.Base-X] {
				frame[face] = previous[oldFace]
			}
		}
	}
	return pure
}

var parallelFaceOrder = [3][2]uint8{{U, D}, {R, L}, {F, B}}

// NormalizePureFaceMoves reduces contiguous turns of parallel faces. A pass
// that removes a whole axis block can expose another reducible block.
func NormalizePureFaceMoves(moves []Move) []Move {
	current := ToPureFaceMoves(moves)
	if len(current) < 2 {
		return current
	}
	next := make([]Move, 0, len(current))
	for {
		next = next[:0]
		for i := 0; i < len(current); {
			// Opposite faces have consecutive move bases, grouped by axis.
			axis := current[i].Base / 2
			var totals [2]uint8
			for i < len(current) && current[i].Base/2 == axis {
				move := current[i]
				side := move.Base % 2
				totals[side] = (totals[side] + move.Mod) % 4
				i++
			}
			for _, face := range parallelFaceOrder[axis] {
				if mod := totals[face%2]; mod != 0 {
					next = append(next, Move{face, mod})
				}
			}
		}
		if sameMoveSequence(current, next) {
			return next
		}
		current, next = next, current
	}
}

// IsTrivialInverse compares the reduced physical solution with the reduced
// inverse scramble followed by the target algorithm.
func IsTrivialInverse(scramble, solution, targetAlg []Move) bool {
	expected := append(InvertMoves(scramble), targetAlg...)
	return sameMoveSequence(NormalizePureFaceMoves(solution), NormalizePureFaceMoves(expected))
}

func sameMoveSequence(a, b []Move) bool {
	if len(a) != len(b) {
		return false
	}
	for i, move := range a {
		if move != b[i] {
			return false
		}
	}
	return true
}

type phaseSide struct {
	crossEdge int
	sideEdge  int
	stride    int
}

const phaseFaceLetters = "URFDLB"

// The rows follow facelet order. Each entry gives a cross edge sticker, the
// adjoining side sticker, and the stride along that side's parallel strips.
// Centering strips on the side edge and the side center covers the first two
// layers on the side face.
var phaseSides = [6][4]phaseSide{
	{{5, 10, 1}, {7, 19, 1}, {3, 37, 1}, {1, 46, 1}},     // U
	{{10, 5, 3}, {12, 23, 3}, {16, 32, 3}, {14, 48, 3}},  // R
	{{19, 7, 1}, {23, 12, 3}, {25, 28, 1}, {21, 41, 3}},  // F
	{{32, 16, 1}, {28, 25, 1}, {30, 43, 1}, {34, 52, 1}}, // D
	{{37, 3, 3}, {41, 21, 3}, {43, 30, 3}, {39, 50, 3}},  // L
	{{46, 1, 1}, {48, 14, 3}, {52, 34, 1}, {50, 39, 3}},  // B
}

// AnalyzePhases replays the solution from its scramble state. CrossFace is
// the face at the Cross checkpoint. Later phases follow that center's color
// through rotations and wide turns.
func AnalyzePhases(scrambleState Cube, moves []Move) PhaseReport {
	_, report := replayWithPhases(scrambleState, moves)
	return report
}

// replayWithPhases returns both the final cube and the report from one replay.
func replayWithPhases(scrambleState Cube, moves []Move) (Cube, PhaseReport) {
	state := scrambleState
	var report PhaseReport
	lastTurn := 0
	for i, move := range moves {
		if !isValidMove(move) {
			continue
		}
		state = ApplyMove(state, move)
		if move.Base >= X {
			continue // Every phase is invariant under a whole-cube rotation.
		}

		lastTurn = i + 1
		if report.OLLAtMove != 0 {
			continue
		}
		if report.CrossAtMove == 0 {
			face := findCross(&state)
			if face < 0 || IsSolved(state) {
				continue
			}
			report.CrossFace = phaseFaceLetters[face : face+1]
			report.CrossColor = state[face*9+4]
			report.CrossAtMove = lastTurn
		}

		face := findCenter(&state, report.CrossColor)
		if face < 0 || !firstTwoLayersSolved(&state, face) {
			continue
		}
		if report.F2LAtMove == 0 {
			report.F2LAtMove = lastTurn
		}
		if phaseFaceSolved(&state, (face+3)%6) {
			report.OLLAtMove = lastTurn
		}
	}

	if report.CrossAtMove == 0 {
		if IsSolved(state) {
			report.PLLAtMove = len(moves)
		}
		return state, report
	}
	// A face or wide turn changes a solved cube. If replay ends solved,
	// its terminal solved run began at the last turn before any rotations.
	if IsSolved(state) {
		report.PLLAtMove = lastTurn
	}
	end := 0
	for _, phase := range [4]struct {
		name string
		step int
	}{
		{"Cross", report.CrossAtMove}, {"F2L", report.F2LAtMove},
		{"OLL", report.OLLAtMove}, {"PLL", report.PLLAtMove},
	} {
		if phase.step > end {
			obtm, _ := CountMetrics(moves[end:phase.step])
			report.Segments = append(report.Segments, PhaseSegment{phase.name, end + 1, phase.step, obtm})
			end = phase.step
		}
	}
	return state, report
}

func findCross(state *Cube) int {
	for face, sides := range phaseSides {
		color := state[face*9+4]
		matched := 0
		for _, side := range sides {
			if state[side.crossEdge] != color || state[side.sideEdge] != state[side.sideEdge/9*9+4] {
				break
			}
			matched++
		}
		if matched == len(sides) {
			return face
		}
	}
	return -1
}

func findCenter(state *Cube, color uint8) int {
	for face := 0; face < 6; face++ {
		if state[face*9+4] == color {
			return face
		}
	}
	return -1
}

func firstTwoLayersSolved(state *Cube, face int) bool {
	if !phaseFaceSolved(state, face) {
		return false
	}
	for _, side := range phaseSides[face] {
		center := side.sideEdge/9*9 + 4
		color := state[center]
		for offset := -side.stride; offset <= side.stride; offset += side.stride {
			if state[side.sideEdge+offset] != color || state[center+offset] != color {
				return false
			}
		}
	}
	return true
}

func phaseFaceSolved(state *Cube, face int) bool {
	start := face * 9
	color := state[start+4]
	for i := start; i < start+9; i++ {
		if state[i] != color {
			return false
		}
	}
	return true
}

package cube3x3

import "testing"

func TestToPureFaceMovesFrameTracking(t *testing.T) {
	start := ApplyMoves(SolvedCube(), analyzerMoves(t, "R U' B2 D F2 L'"))
	cases := []struct{ input, want string }{
		{"R x R", "R R"},
		{"R y2 L", "R R"},
		{"R Lw", "R R"},
		{"R Rw", "R L"},
		{"x U x'", "F"},
		{"y F y'", "R"},
		{"z U z'", "L"},
		{"Rw U Lw'", "L F R'"},
		{"R R' U2 U2", "R R' U2 U2"},
		{"x y2 z'", ""},
	}
	for _, tc := range cases {
		moves := analyzerMoves(t, tc.input)
		pure := ToPureFaceMoves(moves)
		if got := FormatMoves(pure); got != tc.want || len(pure) != len(analyzerMoves(t, tc.want)) {
			t.Errorf("%q projected to %q, want %q", tc.input, got, tc.want)
		}
		if ApplyMoves(start, pure) != NormalizeOrientation(ApplyMoves(start, moves)) {
			t.Errorf("%q changed the physical cube state", tc.input)
		}
	}

	// Every wide-turn modifier must also update the frame for subsequent turns.
	follow := analyzerMoves(t, "U D' F2 B R' L x2 z y' Rw2 U")
	for base := Uw; base <= Bw; base++ {
		for mod := uint8(1); mod <= 3; mod++ {
			moves := append([]Move{{base, mod}}, follow...)
			pure := ToPureFaceMoves(moves)
			obtm, _ := CountMetrics(moves)
			if len(pure) != obtm || ApplyMoves(start, pure) != NormalizeOrientation(ApplyMoves(start, moves)) {
				t.Errorf("base %d modifier %d: wrong physical sequence %q", base, mod, FormatMoves(pure))
			}
		}
	}
}

func TestAnalyzePhasesColorTrackedAcrossRotationsAndSkips(t *testing.T) {
	const crossAndF2L = "F R U R'"
	const sune = " R U R' U R U2 R'"
	const tPerm = " R U R' U' R' F R2 U' R' U' R U R' F'"
	const rotatedF2L = "F x2 y F D F'"
	const rotatedSune = " F D F' D F D2 F'"
	const rotatedTPerm = " F D F' D' F' R F2 D' F' D' F D F' R'"
	cases := []struct {
		name, physical, solution string
		checkpoints              [4]int
		segments                 []PhaseSegment
	}{
		{
			"rotated CFOP", crossAndF2L + sune + tPerm, rotatedF2L + rotatedSune + rotatedTPerm,
			[4]int{1, 6, 13, 27},
			[]PhaseSegment{{"Cross", 1, 1, 1}, {"F2L", 2, 6, 3}, {"OLL", 7, 13, 7}, {"PLL", 14, 27, 14}},
		},
		{
			"OLL skip", crossAndF2L + tPerm, rotatedF2L + rotatedTPerm,
			[4]int{1, 6, 6, 20},
			[]PhaseSegment{{"Cross", 1, 1, 1}, {"F2L", 2, 6, 3}, {"PLL", 7, 20, 14}},
		},
		{
			"PLL skip", crossAndF2L + sune, rotatedF2L + rotatedSune,
			[4]int{1, 6, 13, 13},
			[]PhaseSegment{{"Cross", 1, 1, 1}, {"F2L", 2, 6, 3}, {"OLL", 7, 13, 7}},
		},
		{
			"last layer oriented while F2L is broken", crossAndF2L + " D" + sune + " D'", crossAndF2L + " D" + sune + " D'",
			[4]int{1, 4, 13, 13},
			[]PhaseSegment{{"Cross", 1, 1, 1}, {"F2L", 2, 4, 3}, {"OLL", 5, 13, 9}},
		},
	}
	for _, tc := range cases {
		state := ApplyMoves(SolvedCube(), InvertMoves(analyzerMoves(t, tc.physical)))
		moves := analyzerMoves(t, tc.solution)
		if !IsSolved(ApplyMoves(state, moves)) {
			t.Fatalf("%s: fixture does not solve the cube", tc.name)
		}
		got := AnalyzePhases(state, moves)
		if got.CrossFace != "D" || got.CrossColor != 3 {
			t.Errorf("%s: cross face/color = %q/%d, want D/3", tc.name, got.CrossFace, got.CrossColor)
		}
		checkpoints := [4]int{got.CrossAtMove, got.F2LAtMove, got.OLLAtMove, got.PLLAtMove}
		if checkpoints != tc.checkpoints {
			t.Errorf("%s: checkpoints = %v, want %v", tc.name, checkpoints, tc.checkpoints)
		}
		if len(got.Segments) != len(tc.segments) {
			t.Errorf("%s: segments = %v, want %v", tc.name, got.Segments, tc.segments)
			continue
		}
		for i, segment := range got.Segments {
			if segment != tc.segments[i] {
				t.Errorf("%s: segment %d = %v, want %v", tc.name, i, segment, tc.segments[i])
			}
		}
	}
}

func TestAnalyzePhasesDirectSolve(t *testing.T) {
	state := ApplyMove(SolvedCube(), Move{F, 3})
	for _, solution := range []string{"F", "F x y", "x U x'"} {
		moves := analyzerMoves(t, solution)
		if !IsSolved(ApplyMoves(state, moves)) {
			t.Fatalf("%q: fixture does not solve the cube", solution)
		}
		got := AnalyzePhases(state, moves)
		if got.CrossFace != "" || got.CrossAtMove != 0 || got.F2LAtMove != 0 || got.OLLAtMove != 0 || got.PLLAtMove != len(moves) || len(got.Segments) != 0 {
			t.Errorf("%q: got %v, want only PLL at move %d", solution, got, len(moves))
		}
	}
}

func TestAnalyzePhasesAllCrossFaces(t *testing.T) {
	// The same solve in six frames puts the initial cross on each face in turn.
	for _, tc := range []struct {
		solution, face string
		color          uint8
	}{
		{"B R D R' D", "U", 0},
		{"F U L U' L", "R", 1},
		{"U R B R' B", "F", 2},
		{"F R U R' U", "D", 3},
		{"F D R D' R", "L", 4},
		{"D R F R' F", "B", 5},
	} {
		moves := analyzerMoves(t, tc.solution)
		state := ApplyMoves(SolvedCube(), InvertMoves(moves))
		got := AnalyzePhases(state, moves)
		if got.CrossFace != tc.face || got.CrossColor != tc.color || got.CrossAtMove != 1 || got.F2LAtMove != 4 || got.OLLAtMove != 4 || got.PLLAtMove != 5 {
			t.Errorf("%q: got %v, want cross face/color %s/%d and moves 1, 4, 4, 5", tc.solution, got, tc.face, tc.color)
		}
	}
}

func TestAnalyzePhasesPLLUsesTerminalSolvedRun(t *testing.T) {
	const solution = "F R U R' U"
	state := ApplyMoves(SolvedCube(), InvertMoves(analyzerMoves(t, solution)))
	for _, tc := range []struct {
		suffix string
		pll    PhaseSegment
	}{
		{" R R'", PhaseSegment{"PLL", 5, 7, 3}},
		{" R", PhaseSegment{}},
		{" R R' x y", PhaseSegment{"PLL", 5, 7, 3}},
	} {
		moves := analyzerMoves(t, solution+tc.suffix)
		wantSolved := tc.pll.EndMove > 0
		if IsSolved(ApplyMoves(state, moves)) != wantSolved {
			t.Fatalf("suffix %q: fixture should have solved=%t", tc.suffix, wantSolved)
		}
		wantSegments := []PhaseSegment{{"Cross", 1, 1, 1}, {"F2L", 2, 4, 3}}
		if wantSolved {
			wantSegments = append(wantSegments, tc.pll)
		}
		got := AnalyzePhases(state, moves)
		if got.PLLAtMove != tc.pll.EndMove {
			t.Errorf("suffix %q: PLL at %d, want %d", tc.suffix, got.PLLAtMove, tc.pll.EndMove)
		}
		if len(got.Segments) != len(wantSegments) {
			t.Errorf("suffix %q: segments = %v, want %v", tc.suffix, got.Segments, wantSegments)
			continue
		}
		for i, segment := range got.Segments {
			if segment != wantSegments[i] {
				t.Errorf("suffix %q: segment %d = %v, want %v", tc.suffix, i, segment, wantSegments[i])
			}
		}
	}
}

func TestNormalizeFixpointAndAntiInverse(t *testing.T) {
	start := ApplyMoves(SolvedCube(), analyzerMoves(t, "R U' B2 D F2 L'"))
	for _, tc := range []struct{ input, want string }{
		{"R L R'", "L"},
		{"R L R' L'", ""},
		{"R R'", ""},
		{"D U L R B F", "U D R L F B"},
		{"R F U D U' D' F' R'", ""},
		{"R2 L R2 L L", "L'"},
		{"x U x' F' y2", ""},
	} {
		moves := analyzerMoves(t, tc.input)
		normalized := NormalizePureFaceMoves(moves)
		if got := FormatMoves(normalized); got != tc.want {
			t.Errorf("normalize(%q) = %q, want %q", tc.input, got, tc.want)
		}
		if ApplyMoves(start, normalized) != NormalizeOrientation(ApplyMoves(start, moves)) {
			t.Errorf("normalize(%q) changed the physical cube state", tc.input)
		}
	}

	const checkerboard = "R2 L2 U2 D2 F2 B2"
	for _, tc := range []struct {
		scramble, solution, target string
		want                       bool
	}{
		{"R U", "U' R' x y", "", true},
		{"R U", "x y R' F'", "", true},
		{"R U", "U' x R'", "", true},
		{"R L R' L'", "x y L R L' R'", "", true},
		{"R U", "x y U' R'", "", false},
		{"R U", "U' R' " + checkerboard, checkerboard, true},
		{"R U", "U' R'", checkerboard, false},
		{"x R U", "U' R' U'", "F'", true},
		{
			"R' U' F D2 L2 F R2 U2 R2 B D2 L B2 D' B2 L' R' B D2 B U2 L U2 R' U' F",
			"D2 F' D2 U2 F' L2 D R2 D B2 F L2 R' F' D U'", "", false,
		},
	} {
		scramble := analyzerMoves(t, tc.scramble)
		solution := analyzerMoves(t, tc.solution)
		target := analyzerMoves(t, tc.target)
		if got := IsTrivialInverse(scramble, solution, target); got != tc.want {
			t.Errorf("IsTrivialInverse(%q, %q, %q) = %t, want %t", tc.scramble, tc.solution, tc.target, got, tc.want)
		}
	}
}

func analyzerMoves(t *testing.T, raw string) []Move {
	_, moves, err := Canonicalize(raw)
	if err != nil {
		t.Fatalf("invalid fixture %q: %v", raw, err)
	}
	return moves
}

package cube3x3

import "errors"

const (
	ErrInputTooLong    = "ERR_INPUT_TOO_LONG"
	ErrInvalidNotation = "ERR_INVALID_NOTATION"
	ErrMoveLimit       = "ERR_MOVE_LIMIT"
	ErrNotSolved       = "ERR_NOT_SOLVED"
	ErrTrivialInverse  = "ERR_TRIVIAL_INVERSE"
	ErrRuleViolation   = "ERR_RULE_VIOLATION"
)

// MoveTrace carries the starting state, replay, scores, and checkpoints for a rule.
type MoveTrace struct {
	Scramble      []Move
	ScrambleState Cube
	Moves         []Move
	PureMoves     []Move
	FinalState    Cube
	Phases        PhaseReport
	OBTM          int
	QTM           int
}

// CloneTrace copies the slice data so a rule can inspect or edit its own trace.
func CloneTrace(t MoveTrace) MoveTrace {
	t.Scramble = cloneTraceMoves(t.Scramble)
	t.Moves = cloneTraceMoves(t.Moves)
	t.PureMoves = cloneTraceMoves(t.PureMoves)
	if t.Phases.Segments != nil {
		segments := make([]PhaseSegment, len(t.Phases.Segments))
		copy(segments, t.Phases.Segments)
		t.Phases.Segments = segments
	}
	return t
}

func cloneTraceMoves(moves []Move) []Move {
	if moves == nil {
		return nil
	}
	cloned := make([]Move, len(moves))
	copy(cloned, moves)
	return cloned
}

// ConstraintRule defines a challenge target, scramble alphabet, and replay checks.
// AllowedMoves returns a fresh slice. An empty TargetAlg targets the solved cube.
// Validate returns an error for a rule violation and must not panic.
type ConstraintRule interface {
	ID() string
	Title() string
	Description() string
	AllowedMoves() []Move
	TargetAlg() []Move
	Validate(trace MoveTrace) error
}

// BuiltinRule resolves the five built-in challenge IDs.
func BuiltinRule(id string) (ConstraintRule, bool) {
	switch id {
	case "wca_obtm":
		return wcaOBTMRule{}, true
	case "checkpoint_cross_f2l":
		return checkpointCrossF2LRule{}, true
	case "pattern_checkerboard":
		return checkerboardRule{}, true
	case "no_fb":
		return noFBRule{}, true
	case "no_half_turns":
		return noHalfTurnsRule{}, true
	default:
		return nil, false
	}
}

// DailyTwistedRule selects the daily rule in the fixed four-day cycle.
func DailyTwistedRule(dayID int64) ConstraintRule {
	switch ((dayID % 4) + 4) % 4 {
	case 0:
		return checkpointCrossF2LRule{}
	case 1:
		return checkerboardRule{}
	case 2:
		return noFBRule{}
	default:
		return noHalfTurnsRule{}
	}
}

type wcaOBTMRule struct{}

func (wcaOBTMRule) ID() string    { return "wca_obtm" }
func (wcaOBTMRule) Title() string { return "Classic Fewest Moves" }
func (wcaOBTMRule) Description() string {
	return "Solve the cube in 80 moves or fewer (up to 120 turns including cube rotations). Middle-layer slice turns are not allowed."
}
func (wcaOBTMRule) AllowedMoves() []Move     { return allFaceTurns() }
func (wcaOBTMRule) TargetAlg() []Move        { return nil }
func (wcaOBTMRule) Validate(MoveTrace) error { return nil }

type checkpointCrossF2LRule struct{}

func (checkpointCrossF2LRule) ID() string    { return "checkpoint_cross_f2l" }
func (checkpointCrossF2LRule) Title() string { return "Step-by-Step: Cross then First Two Layers" }
func (checkpointCrossF2LRule) Description() string {
	return "Complete a cross on any face first, then finish the first two layers on a later move."
}
func (checkpointCrossF2LRule) AllowedMoves() []Move { return allFaceTurns() }
func (checkpointCrossF2LRule) TargetAlg() []Move    { return nil }
func (checkpointCrossF2LRule) Validate(trace MoveTrace) error {
	if trace.Phases.CrossAtMove > 0 && trace.Phases.F2LAtMove > trace.Phases.CrossAtMove {
		return nil
	}
	return errors.New("Complete a cross first, then finish the first two layers on a later move.")
}

type checkerboardRule struct{}

func (checkerboardRule) ID() string    { return "pattern_checkerboard" }
func (checkerboardRule) Title() string { return "Checkerboard Pattern" }
func (checkerboardRule) Description() string {
	return "Finish with a checkerboard pattern from any cube angle."
}
func (checkerboardRule) AllowedMoves() []Move { return allFaceTurns() }
func (checkerboardRule) TargetAlg() []Move {
	return []Move{{R, 2}, {L, 2}, {U, 2}, {D, 2}, {F, 2}, {B, 2}}
}
func (checkerboardRule) Validate(MoveTrace) error { return nil }

type noFBRule struct{}

func (noFBRule) ID() string    { return "no_fb" }
func (noFBRule) Title() string { return "No Front or Back Turns" }
func (noFBRule) Description() string {
	return "Solve using only Right, Up, Left, and Down face turns. Front and Back face turns stay locked even after rotating the cube."
}
func (noFBRule) AllowedMoves() []Move {
	return faceTurnAlphabet([]uint8{U, D, L, R}, []uint8{1, 2, 3})
}
func (noFBRule) TargetAlg() []Move { return nil }
func (noFBRule) Validate(trace MoveTrace) error {
	for _, move := range trace.PureMoves {
		switch move.Base {
		case R, U, L, D:
		default:
			return errors.New("Only Right (R), Up (U), Left (L), and Down (D) face turns are allowed in this challenge.")
		}
	}
	return nil
}

type noHalfTurnsRule struct{}

func (noHalfTurnsRule) ID() string    { return "no_half_turns" }
func (noHalfTurnsRule) Title() string { return "Quarter Turns Only" }
func (noHalfTurnsRule) Description() string {
	return "Use 90-degree single turns on alternating faces. 180-degree face turns and repeated turns on the same face are not allowed."
}
func (noHalfTurnsRule) AllowedMoves() []Move {
	return faceTurnAlphabet([]uint8{U, D, L, R, F, B}, []uint8{1, 3})
}
func (noHalfTurnsRule) TargetAlg() []Move { return nil }
func (noHalfTurnsRule) Validate(trace MoveTrace) error {
	for i, move := range trace.PureMoves {
		if move.Mod == 2 || (i > 0 && move.Base == trace.PureMoves[i-1].Base) {
			return errors.New("180-degree face turns and back-to-back turns on the same face are not allowed in Quarter Turns Only.")
		}
	}
	return nil
}

func allFaceTurns() []Move {
	return faceTurnAlphabet([]uint8{U, D, L, R, F, B}, []uint8{1, 2, 3})
}

// VerifyResult contains the verdict and metrics. Solved reports whether the
// target was reached. Phases is present only for an accepted solution.
type VerifyResult struct {
	Valid          bool
	ErrorCode      string
	ErrorMessage   string
	CanonicalMoves string
	OBTM           int
	QTM            int
	Solved         bool
	Phases         *PhaseReport
}

func (result VerifyResult) withError(code, message string) VerifyResult {
	result.ErrorCode = code
	result.ErrorMessage = message
	return result
}

// VerifySolution parses raw notation and verifies it for the supplied rule.
func VerifySolution(scrambleMoves []Move, rawMoves string, rule ConstraintRule) VerifyResult {
	if len(rawMoves) > MaxRawMovesBytes {
		return VerifyResult{ErrorCode: ErrInputTooLong, ErrorMessage: "Move notation is too long (maximum 512 bytes)."}
	}
	canonical, moves, err := Canonicalize(rawMoves)
	if err != nil {
		return VerifyResult{ErrorCode: ErrInvalidNotation, ErrorMessage: "Use standard face turns, wide turns, and cube rotations (middle-layer slices are not allowed)."}
	}
	return VerifyCanonicalMoves(scrambleMoves, canonical, moves, rule)
}

// VerifyCanonicalMoves verifies a canonical string and moves from Canonicalize
// without parsing them again.
func VerifyCanonicalMoves(scrambleMoves []Move, canonical string, moves []Move, rule ConstraintRule) VerifyResult {
	obtm, qtm := CountMetrics(moves)
	result := VerifyResult{CanonicalMoves: canonical, OBTM: obtm, QTM: qtm}
	if obtm < 1 || obtm > MaxOBTM || len(moves) > MaxTotalMoves {
		return result.withError(ErrMoveLimit, "Solutions must use 1 to 80 moves (maximum 120 turns including cube rotations).")
	}

	scrambleState := ApplyMoves(SolvedCube(), scrambleMoves)
	finalState, phases := replayWithPhases(scrambleState, moves)
	pureMoves := ToPureFaceMoves(moves)

	if rule == nil {
		return result.withError(ErrRuleViolation, "A challenge rule is required.")
	}
	targetAlg := rule.TargetAlg()
	if len(targetAlg) == 0 {
		result.Solved = IsSolved(finalState)
	} else {
		targetState := ApplyMoves(SolvedCube(), targetAlg)
		result.Solved = NormalizeOrientation(finalState) == NormalizeOrientation(targetState)
	}
	if !result.Solved {
		return result.withError(ErrNotSolved, "These moves do not reach the target cube state.")
	}
	if IsTrivialInverse(scrambleMoves, reduceReplayTurns(pureMoves), targetAlg) {
		return result.withError(ErrTrivialInverse, "This solution simply reverses the scramble. Find an original solve instead.")
	}

	trace := MoveTrace{
		Scramble:      scrambleMoves,
		ScrambleState: scrambleState,
		Moves:         moves,
		PureMoves:     pureMoves,
		FinalState:    finalState,
		Phases:        phases,
		OBTM:          obtm,
		QTM:           qtm,
	}
	if err := rule.Validate(CloneTrace(trace)); err != nil {
		return result.withError(ErrRuleViolation, err.Error())
	}
	result.Valid = true
	result.Phases = &phases
	return result
}

// reduceReplayTurns computes the same parallel-axis reduction used by
// IsTrivialInverse. Processing the replay once also bounds the cost when
// many nested blocks disappear. The trace retains the unreduced turns.
func reduceReplayTurns(pureMoves []Move) []Move {
	type axisBlock struct {
		axis  uint8
		turns [2]uint8
	}
	blocks := make([]axisBlock, 0, len(pureMoves))
	for _, move := range pureMoves {
		axis := move.Base / 2
		n := len(blocks)
		if n == 0 || blocks[n-1].axis != axis {
			blocks = append(blocks, axisBlock{axis: axis})
			n++
		}
		last := &blocks[n-1]
		side := move.Base % 2
		last.turns[side] = (last.turns[side] + move.Mod) % 4
		if last.turns[0] == 0 && last.turns[1] == 0 {
			blocks = blocks[:n-1]
		}
	}

	reduced := make([]Move, 0, len(pureMoves))
	for _, block := range blocks {
		for _, face := range parallelFaceOrder[block.axis] {
			if mod := block.turns[face%2]; mod != 0 {
				reduced = append(reduced, Move{face, mod})
			}
		}
	}
	return reduced
}

